window.GAMES = [{"id": "01", "title": "Khao Chang Hai Cave", "category": "biodiversity", "cover": "assets/cover-01.webp", "players": "Flexible group", "time": "2 game years", "intro": "Explore the value of a living cave ecosystem, from biodiversity to community livelihoods.", "research": "Valuing ecosystem services and testing an integrated model for shared learning at Khao Chang Hai Cave, Trang Province.", "overview": "Human activities, including tourism, put limestone and cave ecosystems under pressure. This game helps local communities and stakeholders discuss biodiversity, ecosystem services and their economic value at Khao Chang Hai Cave in Trang.", "materials": ["Forest-product, tree, animal and activity cards; an A2 board.", "Ecosystem-service information sheets, pre/post tests, evaluation forms, answer sheets, a turn guide and a carbon-credit facilitator script.", "Seven colours of tokens and beads, two dice, play money, role labels and a nine-piece elephant puzzle."], "play": ["Assign community roles and distribute resources as specified in the source guide. Players collect biodiversity cards while working together to complete the elephant puzzle.", "Roll the dice, move and follow the space instructions. Place animal beads in the appropriate habitat; remove them when an animal card is discarded. Keep tree and forest-product cards.", "Complete two forest habitats with ten animal species each and seven cave chambers with three species each to collect nine puzzle pieces. Completing the puzzle ends the game; the player with the most biodiversity cards wins.", "Passing the start marks one game year. At annual intervals, trade forest products, discuss carbon-credit registration and allocate role budgets. The usual activity spans two game years, adjustable by the facilitator.", "In the second year, registered players can trade tree-based carbon credits. The facilitator introduces a carbon-tax scenario to explore emissions and offsets. Use the source tables for role budgets and detailed conditions."], "learning": "Connect tourism, forest products, biodiversity, carbon storage and community responsibilities. The source includes space-by-space learning points and discussion questions.", "debrief": "Discuss how ecosystem services support community income and wellbeing, how activities affect biodiversity, and which conservation and maintenance practices can sustain the cave ecosystem.", "file": "documents/01_เกมถ้ำเขาช้างหาย.docx", "titleTh": "เกมถ้ำเขาช้างหาย", "introTh": "สำรวจคุณค่าระบบนิเวศถ้ำ ความหลากหลายทางชีวภาพ และวิถีชีวิตของชุมชน", "researchTh": "การประเมินมูลค่าบริการของระบบนิเวศและการทดสอบแบบจำลองเชิงบูรณาการเพื่อแลกเปลี่ยนเรียนรู้เกี่ยวกับมูลค่าบริการของระบบนิเวศในพื้นที่ถ้ำเขาช้างหาย จังหวัดตรัง", "sourceTh": "งานวิจัย", "tags": [{"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "ความหลากหลายทางชีวภาพ", "en": "Biodiversity"}, {"th": "มูลค่าทางเศรษฐศาสตร์", "en": "Economic Value"}, {"th": "คาร์บอนเครดิต", "en": "Carbon Credit"}, {"th": "การอนุรักษ์", "en": "Conservation"}, {"th": "การกักเก็บคาร์บอน", "en": "Carbon Sequestration"}], "sectionsTh": {"overview": "<p>ในปัจจุบันระบบนิเวศเขาหินปูนและถ้ำเขาช้างหายเสียหายจากกิจกรรมต่าง ๆ ของมนุษย์ เช่น การท่องเที่ยว และชุมชนในพื้นที่ยังขาดความรู้เกี่ยวความสำคัญ และ มูลค่าทางเศรษฐศาสตร์ของระบบนิเวศ จึงมีการพัฒนาเครื่องมือที่สามารถส่งเสริมการเรียนรู้ให้กับคนในชุมชนและผู้ที่เกี่ยวข้อง นั้นคือ เกมถ้ำเขาช้างหาย โดยมีวัตถุประสงค์เพื่อใช้เป็นเครื่องมือในการสร้างความรู้ และ ความเข้าใจ พร้อมทั้งยังสามารถแลกเปลี่ยนเรียนรู้เกี่ยวกับบริการระบบนิเวศ มูลค่าบริการระบบนิเวศ และความหลากหลายทางชีวภาพในพื้นที่ถ้ำเขาช้างหาย จังหวัดตรัง เพื่อให้เข้าใจถึงปัญหาที่เกิดมากยิ่งขึ้น</p>", "materials": "<p>การ์ด</p><p>การ์ดของป่า</p><p>การ์ดต้นไม้</p><p>การ์ดสัตว์</p><p>การ์ดกิจกรรม</p><p>บอร์ด ขนาด A2</p><p>ใบความรูปบริการระบบนิเวศและมูลค่าบริการระบบนิเวศ</p><p>แบบทดสอบความรู้ก่อนและหลังการใช้แบบจำลอง</p><p>แบบประเมินความพึงพอจากแบบจำลอง</p><p>ใบจดบันทึกคำตอบของผู้เล่น</p><p>ใบแสดงลำดับการดำเนินเกม</p><p>บทพูดสำหรับผู้ช่วยนำเกมในกิจกรรมคาร์บอนเครดิต</p><p>ตัวเดินและลูกปัด 7 สีลำหรับแต่ละผู้เล่น</p><p>ลูกเต๋า 2 ลูก</p><p>เงินปลอม</p><p>ป่ายชื่อแสดงบทบาท</p><p>จิ๊กซอว์ช้าง 9 ชิ้น</p>", "play": "<p>แนะนำและกติการเกม</p><p>วางการ์ดกิจกรรม และ การ์ดความหลากหลายความหลายลงในช่องบนกระดานเกม แจกอุปกรณ์ต่าง ๆ ให้ผู้เล่นตามบทบาทที่ได้ โดยผู้เล่นแต่ละคนจะมีเป้าหมายคือ รวบรวมการ์ดความหลากหลายให้ได้มากที่สุด และ เป้าหมายรวมของผู้เล่นทั้งกลุ่มคือ การตามหาช้าง จากการวางลูกปักที่เป็นตัวแทนสัตว์บนกระดานในบริเวณถิ่นอาศัยของสัตว์ชนิดนั้น ๆ ประกอบด้วย ป่า 2 บริเวณ ต้องลงสัตว์ให้ได้ 10 ชนิดต่อบริเวณ และ ห้องในถ้ำ 7 บริเวณ ต้องลงสัตว์ให้ได้ 3 ชนิดต่อบริเวณ เมื่อรวบรวมจิ๊กซอว์ช้างครบทั้ง 9 ชิ้นเกมจะจบลง และ ผู้ที่รวบรวมการ์ดความหลากหลายได้มากที่สุดจะเป็นผู้ชนะ โดย 1 รอบการเดินคือเมื่อผู้เล่นคนใดคนหนึ่งเดินผ่านจุดเริ่มต้นอีกครั้ง จะถือว่าจบรอบนั้น ๆ ซึ่ง 1 รอบการเดินจะกำหนดให้เป็น 1 รอบปี โดยจะเล่นทั้งหมด 2 รอบ หรือ แล้วแต่ความเหมาะสม</p><p>บทบาท</p><div class=\"table-scroll\"><table><tbody><tr><td><p>บทบาท</p></td><td><p>อุปกรณ์</p></td></tr><tr><td><p>พระ</p></td><td><p>ลูกปัดและตัวเดิน</p><p>การ์ดต้นไม้ 30 ใบ</p></td></tr><tr><td><p>ชาวบ้าน</p></td><td><p>ลูกปัดและตัวเดิน</p><p>เงิน 3,000 บาท</p></td></tr><tr><td><p>หน่วยงานเอกชล</p></td><td><p>ลูกปัดและตัวเดิน</p><p>เงิน 100,000 บาท</p><p>คลิปหนีบกระดาษ 20 อัน แทนก๊าซคาร์บอนไดออกไซด์ที่หน่วยงานปล่อยออกมา</p></td></tr><tr><td><p>พ่อค้า/แม่ค้า</p></td><td><p>ลูกปัดและตัวเดิน</p><p>เงิน 5,000 บาท</p></td></tr><tr><td><p>โรงเรียน (ครู/นักเรียน)</p></td><td><p>ลูกปัดและตัวเดิน</p><p>เงิน 3,000 บาท</p></td></tr><tr><td><p>อบต.</p></td><td><p>ลูกปัดและตัวเดิน</p><p>เงิน 3,000 บาท</p></td></tr></tbody></table></div><p>ขั้นตอนการเล่นเกม</p><p>วางตัวเดินของผู้เล่นบนจุดเริ่มต้น</p><p>ทอยลูกเต๋าเดินไปตามช่องต่าง ๆ ตามจำนวนแต้มบนหน้าลูกเต๋า</p><p>ปฏิบัติตามสิ่งที่แต่ละช่องกำหนด</p><p>หากหยิบการ์ดความหลากหลาย</p><p>การ์ดสัตว์ อ่านชื่อแล้วนำลูกปัดไปวางไว้ในบริเวณถิ่นอาศัย และก็การ์ดไว้</p><p>การ์ดต้นไม้หรือของป่า อ่านชื่อและเก็บการ์ดไว้</p><p>หากตกช่องที่ต้องหารือหรือตอบคำถาม จะต้องตอบคำถามในข้อนั้นๆ และ ให้ผู้อื่นตอบไม่เกิน 3 คนรวมผู้เล่นที่ตกช่องนั้นๆ</p><p>หากตกช่องโรงเรียน ให้นำใบความรู้ให้ผู้เล่นที่ได้รับบทบาท โรงเรียน (ครู/นักเรียน) อ่าน</p><p>หากต้องทิ้งการ์ด</p><p>การ์ดสัตว์ ให้วางไว้ที่กองทิ้ง และ นำลูกปัดที่เป็นตัวแทนสัตว์ชนิดนั้น ๆ ออกจากกระดาน</p><p>การ์ดต้นไม้หรือการ์ดของป่า ให้วางไว้ที่กองทิ้ง</p><p>หากมีสถานการณ์ที่ อบต. ต้องจ่ายเงินในการทำกิจกรรม แต่เงินไม่เพียงพอ ผู้ช่วยคุมเกมสร้างสถานการณ์ ให้มีการระดมทุนเพื่อช่วยเหลือ อบต. หากเงินที่ได้จากการระดมทุนรวมกับเงินที่ อบต. มีอยู่ไม่เพียงพอที่จะทำกิจกรรมนั้น ๆ ให้นำลูกปัดทั้งหมด 1 บริเวณ และ การ์ดสัตว์ที่เป็นตัวแทนลูกปัดนั้น ๆ ออกจากกระดานและวางไว้ที่กองทิ้ง</p><p>เมื่อผู้เล่นคนใดคนหนึ่งเดินครบทุก ๆ 1 รอบเดินจะมีกิจกรรม</p><p>เปิดตลาดให้ผู้เล่นสามารถขายของป่าที่มีอยู่กับตัวผู้เล่นแต่ละคนได้ โดยราคาขึ้นอยู่กับการ์ดแต่ละใบ</p><p>การขึ้นทะเบียนคาร์บอนเครดิต ให้ผู้ช่วยคุมเกมอ่านบทพูดก่อนชักชวนขึ้นทะเบียนโครงการ และ อธิบายลายละเอียด หาผู้เล่นต้องการขึ้นทะเบียนโครงการเสียเงิน 10,000 บาท และ จะได้รับใบ Validation โครงการซื้อขายคาร์บอนเครดิต</p><p>อบต. และ หน่วยงานเอกชน ได้รับประมาณประจำปี จำนวน 30,000 และ 100,000 บาท ตามลำดับ</p><p>การซื้อขายคาร์บอน</p><p>ผู้เล่นจะได้รับการ์ดต้นไม้สะสมไว้กับตนเอง โดยแต่ละต้นจะสามารถดูดซับก๊าซคาร์บอนไดออกไซด์ได้ในปริมาณที่แตกต่างกัน จึงทำให้มีมูลค่าคาร์บอนเครดิตแตกต่างๆกัน</p><p>ในปีที่ 2 จะสามารถขายคาร์บอนเครดิต โดยจะทำได้เมื่อผู้เล่นขึ้นทะเบียนโครงการ ซึ่งสามารถขายได้ตามจำนวนการ์ดต้นไม้ที่มีอยู่ในปีที่สอง</p><p>เมื่อจบปีที่ 2 จะมีการสร้างสถานการณ์ที่รัฐบาลจะมีการเก็บภาษีคาร์บอน ซึ่งจะกำหนดอัตราภาษีสำหรับการปล่อยคาร์บอนเกินกว่ากำหนด โดยหน่วยงานเอกชนจะมีการปล่อยก๊าซคาร์บอนไดออกไซด์จากกิจกรรมต่าง ๆ โดยให้คลิปหนีบกระดาษ 1 อันแทนก๊าซคาร์บอนไดออกไซด์ที่ปล่อยออกมา จำเป็นต้องใช้คาร์บอนเครดิตของตน หรือ ซื้อจากผู้เล่นอื่นเพื่อชดเชยที่ปล่อยออกมา และนำคลิปหนีบกระดาษไปติดไว้กับต้นไม้นั้นๆ</p>", "learning": "<div class=\"table-scroll\"><table><tbody><tr><td><p>รายละเอียดเกม</p></td><td><p>ความรู้ที่แลกเปลี่ยนในเกม</p></td></tr><tr><td colspan=\"2\"><p>1. ส่วนกระดานเกม</p></td></tr><tr><td><p>โรงเรียนให้ความรู้เรื่องบริการระบบนิเวศครูพา</p></td><td><p>แนวคิดเรื่องบริการของระบบนิเวศแต่ละข้อ และมูลค่าทางเศรษฐศาสตร์ของบริการของระบบนิเวศ และครู/นักเรียน มีบทบาทสำคัญในการเผยแพร่ความรู้เรื่องคุณค่าบริการของระบบนิเวศในพื้นที่</p></td></tr><tr><td><p>นักเรียนมาทัศนศึกษา ทำให้ได้รู้ความสำคัญของระบบนิเวศ</p></td><td></td></tr><tr><td><p>ช่วยกันบอกวิธีอนุรักษ์พื้นที่ถ้ำเขาช้างหาย</p></td><td><p>แนวทางการอนุรักษ์ที่ยั่งยืน</p></td></tr><tr><td><p>นักท่องเที่ยวหยิบหินออกจากถ้ำทำให้รบกวนระบบนิเวศถ้ำ</p></td><td><p>การนำหินออกจากถ้ำส่งผลต่อสมดุลทางกายภาพและเคมีของถ้ำ</p></td></tr><tr><td><p>มีนักท่องเที่ยวมือบอนจับ/หักหินงอกหินย้อยและประติมากรรมในถ้ำ ต้องเสียค่าซ่อมแซม</p></td><td><p>การทำลายหินงอกหินย้อยเป็นการทำลายโครงสร้างธรรมชาติที่ใช้เวลาสร้างนานนับพันปี อีกทั้งยังทำลายโอกาสการชมความงามของถ้ำของคนอื่นด้วย</p></td></tr><tr><td><p>มีคนมาลักลอบจับสัตว์ในพื้นที่ ทำให้ความหลากหลายลดลง</p></td><td><p>การลักลอบจับสัตว์ส่งผลให้ความหลากหลายทางชีวภาพลดลง ทำให้ห่วงโซ่อาหารในถ้ำเสียสมดุล</p></td></tr><tr><td><p>นักท่องเที่ยวทิ้งขยะ ทำให้ราขึ้น</p></td><td><p>ขยะจากนักท่องเที่ยวอาจนำไปสู่การเติบโตของเชื้อราและแบคทีเรียที่ส่งผลต่อระบบนิเวศถ้ำ</p></td></tr><tr><td><p>พระจัดกิจกรรมบวชป่าทำให้คนหวงแหนพื้นที่ป่ามากขึ้น</p></td><td><p>พระสงฆ์สามารถเป็นผู้นำในการสร้างจิตสำนึกด้านสิ่งแวดล้อม อีกทั้งการบวชป่าเป็นกลไกทางวัฒนธรรมที่ช่วยสร้างจิตสำนึกในการอนุรักษ์ป่า</p></td></tr><tr><td><p>ภาคเอกชนเข้ามาจัดกิจกรรมเพื่อสังคม</p></td><td><p>ภาคเอกชนสามารถสนับสนุนการอนุรักษ์ผ่านกิจกรรม CSR เช่น ปลูกป่า หรือพัฒนาสิ่งอำนวยความสะดวกที่เป็นมิตรต่อสิ่งแวดล้อม อีกทั้งความร่วมมือระหว่างภาคเอกชนและชุมชนช่วยให้การพัฒนาเป็นไปอย่างยั่งยืน</p></td></tr><tr><td><p>เทศกาลลูกลมทำให้นักท่องเที่ยวมาเพิ่ม</p></td><td><p>เทศกาลเป็นเครื่องมือดึงดูดนักท่องเที่ยวที่สำคัญที่กระตุ้นเศรษฐกิจท้องถิ่น</p></td></tr><tr><td><p>ช่วยกันหารือวิธีดึงดูดนักท่องเที่ยวมาเที่ยวถ้ำมากขึ้น</p></td><td><p>หารือกลยุทธ์ในการพัฒนาแหล่งท่องเที่ยว</p></td></tr><tr><td></td><td></td></tr><tr><td><p>รายละเอียดเกม</p></td><td><p>ความรู้ที่แลกเปลี่ยนในเกม</p></td></tr><tr><td><p>เสียภาษีให้ อบต.</p></td><td><p>ภาษีที่จ่ายให้ อบต. สามารถนำไปใช้พัฒนาโครงสร้างพื้นฐานและอนุรักษ์ทรัพยากรธรรมชาติในพื้นที่</p></td></tr><tr><td><p>เกิดภัยพิบัติน้ำท่วม</p></td><td><p>การเปลี่ยนแปลงสภาพภูมิอากาศไม่ใช่เรื่องไกลตัว แต่ส่งผลต่อระบบนิเวศและเศรษฐกิจโดยตรง</p></td></tr><tr><td><p>โลกร้อนขึ้นผลิตของป่าได้น้อยลง</p></td><td></td></tr><tr><td><p>มีการแยกขยะ เพื่อนำไปสร้างรายได้ให้ชุมชน</p></td><td><p>การแยกขยะสามารถลดปริมาณขยะที่ส่งไปฝังกลบ และช่วยสร้างรายได้จากการรีไซเคิล (recycle)</p></td></tr><tr><td colspan=\"2\"><p>2. ส่วนการ์ดกิจกรรม</p></td></tr><tr><td><p>มีการประชาสัมพันธ์สถานที่ท่องเที่ยว ทำให้นักท่องเที่ยวเพิ่มขึ้น</p></td><td><p>การประชาสัมพันธ์ช่วยดึงดูดนักท่องเที่ยว ทำให้เศรษฐกิจในชุมชนดีขึ้น</p></td></tr><tr><td><p>มีนักท่องเที่ยวจำนวนมากมาเที่ยว ทำให้ร้านค้าขายของดี</p></td><td></td></tr><tr><td><p>ไกด์สอนนักท่องเที่ยวเรื่องกฎระเบียบ ในการเที่ยวถ้ำ ทำให้นักท่องเที่ยวมีพฤติกรรมที่ดี</p></td><td><p>นักท่องเที่ยวที่ได้รับความรู้เกี่ยวกับกฎระเบียบจะลดพฤติกรรมที่ส่งผลเสียต่อสิ่งแวดล้อม</p></td></tr><tr><td><p>มีการจัดกิจกรรมดูแลป่า ทำให้ป่ามีความความหลากหลายมากขึ้น</p></td><td><p>การปลูกป่าและฟื้นฟูพื้นที่ธรรมชาติช่วยเพิ่มถิ่นที่อยู่อาศัยของสัตว์ป่า รวมทั้งป่าที่มีความอุดมสมบูรณ์ช่วยรักษาสมดุลของระบบนิเวศ</p></td></tr><tr><td><p>มีการจัดอบรมให้ความรู้กับคนในพื้นที่ ทำให้คนในพื้นที่มีการเก็บของป่ามากขึ้น</p></td><td><p>การอบรมให้ความรู้กับคนในพื้นที่ช่วยให้เกิดการใช้ประโยชน์จากป่าอย่างยั่งยืน</p></td></tr><tr><td><p>นักวิจัยเข้ามาสำรวจป่า เพื่อศึกษาความหลากหลายของสิ่งมีชีวิต</p></td><td><p>การสำรวจทางวิทยาศาสตร์ช่วยให้เข้าใจระบบนิเวศและเป็นข้อมูลสำหรับการอนุรักษ์</p></td></tr><tr><td><p>นักท่องเที่ยวไปไหว้เจ้าที่ แล้วทิ้งขนมไว้ มดเข้ามาทำลายระบบนิเวศ</p></td><td><p>การทิ้งอาหารเช่นไหว้ทำให้มดและสัตว์รบกวนเพิ่มขึ้น ส่งผลกระทบต่อสมดุลของระบบนิเวศ</p></td></tr><tr><td><p>นักท่องเที่ยวหยิบหินต่าง ๆ ออกจากถ้ำ ทำให้รบกวนระบบนิเวศในถ้ำ</p></td><td><p>การนำหินออกจากถ้ำทำให้เกิดความเสียหายต่อระบบนิเวศถ้ำที่ต้องใช้เวลาหลายพันปีในการก่อตัว</p></td></tr><tr><td><p>มีเด็กแว้นเข้ามาในพื้นที่ ทำให้ นักท่องเที่ยวน้อยลง</p></td><td><p>การขับขี่เสียงดังรบกวนบรรยากาศการท่องเที่ยว ทำให้นักท่องเที่ยวลดลง</p></td></tr><tr><td></td><td></td></tr><tr><td><p>รายละเอียดเกม</p></td><td><p>ความรู้ที่แลกเปลี่ยนในเกม</p></td></tr><tr><td><p>ลักลอบจับสัตว์ในถ้ำ ทำให้สัตว์ในถ้ำมีความหลากหลายน้อยลง</p></td><td><p>สัตว์ในถ้ำมีความสำคัญต่อสมดุลของระบบนิเวศ หากถูกจับไปอาจส่งผลต่อวงจรชีวิตในถ้ำ</p></td></tr><tr><td><p>ภาคเอกชนให้งบประมาณศึกษาความหลากหลายทางชีวภาพ</p></td><td><p>การร่วมมือระหว่างภาครัฐ ภาคเอกชน และนักวิชาการเป็นแนวทางสำคัญในการพัฒนาการอนุรักษ์แบบยั่งยืน</p></td></tr><tr><td><p>นักเรียนเข้ามาทำโครงงานวิทยาศาสตร์ ทำให้ได้ข้อมูลในการดูแลพื้นที่</p></td><td><p>การเรียนรู้ผ่านโครงงานวิทยาศาสตร์ช่วยพัฒนาการดูแลทรัพยากรธรรมชาติ</p></td></tr><tr><td><p>มีการทำป้ายความรู้ในสถานที่เพิ่มเติมช่วยดึงดูดนักท่องเที่ยว</p></td><td><p>การให้ความรู้ในรูปแบบที่น่าสนใจ เช่น แผนที่เชิงนิเวศหรือเรื่องราวทางธรณีวิทยา ช่วยดึงดูดนักท่องเที่ยวให้สนใจมากขึ้น</p></td></tr><tr><td><p>จัดให้มีการอบรมสร้างมัคคุเทศก์น้อยทำให้เด็กในชุมชนหวงแหนถ้ำเขาช้างหายมากขึ้น</p></td><td><p>การให้เยาวชนมีส่วนร่วมในการอนุรักษ์ช่วยสร้างความต่อเนื่องในการดูแลสิ่งแวดล้อม</p></td></tr><tr><td><p>คำถาม นักท่องเที่ยวไม่ควรทำอะไรในการมาเที่ยวถ้ำเขาช้างหาย</p></td><td><p>นักท่องเที่ยวควรมีจิตสำนึกในการท่องเที่ยวอย่างรับผิดชอบและเคารพกฎระเบียบเพื่อร่วมอนุรักษ์ถ้ำเขาช้างหายอย่างยั่งยืน</p></td></tr></tbody></table></div><p>คำถามเกี่ยวกับการจัดการหรือการอนุรักษ์พื้นที่</p><div class=\"table-scroll\"><table><tbody><tr><td><p>คำถาม</p></td><td><p>ตัวอย่างคำตอบ</p></td></tr><tr><td><p>ช่วยกันบอกวิธีอนุรักษ์พื้นที่ถ้ำเขาช้างหาย</p></td><td><p>- ช่วยกันดูแลพื้นที่ธรรมชาติ ไม่ทิ้งขยะ หรือหากพบเห็นขยะให้เก็บไปทิ้งในจุดทิ้งขยะ</p><p>- ไม่รบกวนสัตว์ป่า ไม่ให้อาหารสัตว์ป่า</p><p>- ปฏิบัติตามกฎระเบียบของสถานที่</p><p>- ส่งเสริมการท่องเที่ยวเชิงนิเวศ</p><p>- ทำป้ายความรู้ในพื้นที่</p></td></tr><tr><td><p>หารือวิธีดึงดูดนักท่องเที่ยวให้มาท่องเที่ยวถ้ำมากขึ้น</p></td><td><p>- เผยแพร่ภาพถ่าย ข้อมูล ที่ได้มาเที่ยวถ้ำในโซเชียลมีเดีย</p><p>- จัดกิจกรรมพิเศษช่วงวันหยุดสำคัญ เช่น วันเด็ก ปีใหม่ สงกรานต์</p><p>- ประชาสัมพันธ์ถ้ำผ่านหน่วยงานในจังหวัด หรือหน่วยงานที่เกี่ยวข้อง</p><p>- สร้างจุด landmark ให้เป็นที่จดจำ</p><p>- จัดหาไกด์วัยละอ่อน มัคคุเทศก์น้อย พาชมถ้ำให้ความรู้</p></td></tr><tr><td><p>คำถาม นักท่องเที่ยวไม่ควรทำอะไรในการมาเที่ยวถ้ำเขาช้างหาย</p></td><td><p>- ไม่ทิ้งขยะในบริเวณถ้ำเขาช้างหาย</p><p>- ไม่ควรนำอาหาร/เครื่องดื่ม เข้าไปรับประทาน</p><p>- ไม่สัมผัสหินภายในถ้ำ</p><p>- ห้ามเก็บก้อนหิน หรือย้ายตำแหน่งก้อนหินในถ้ำ</p></td></tr></tbody></table></div>", "debrief": "<p>ชี้ให้เห็นถึงมูลค่าของบริการระบบนิเวศต่างๆ เกี่ยวกับความสำคัญของระบบนิเวศภายในพื้นที่ และการนำไปประยุกต์ใช้ให้เกิดประโยชน์ต่อชุมชนได้ เช่น การสร้างรายได้จากการหาของป่า การดูดซับคาร์บอนไดออกไซด์ และ นำไปแปลงให้อยู่ในรูปของเม็ดเงิน อีกทั้งสามารถชี้ให้เห็นถึงผลกระทบของการใช้พื้นที่ต่อความหลากหลายทางชีวภาพในพื้นที่ รวมทั้งวิธีการบำรุงรักษา และ การอนุรักษ์พื้นที่เพื่อให้คนในชุมชนสามารถใช้ประโยชน์จากพื้นที่ได้อย่างยั่งยืน</p>", "gallery": ""}, "gallery": [{"src": "assets/01-image1.png", "section": "materials"}, {"src": "assets/01-image2.png", "section": "materials"}, {"src": "assets/01-image3.png", "section": "materials"}, {"src": "assets/01-image4.png", "section": "materials"}, {"src": "assets/01-image5.png", "section": "materials"}, {"src": "assets/01-image6.png", "section": "materials"}, {"src": "assets/01-image7.png", "section": "materials"}, {"src": "assets/01-image8.png", "section": "materials"}, {"src": "assets/01-image9.png", "section": "materials"}, {"src": "assets/01-image10.png", "section": "materials"}, {"src": "assets/01-image11.png", "section": "materials"}, {"src": "assets/01-image12.png", "section": "materials"}, {"src": "assets/01-image13.png", "section": "materials"}, {"src": "assets/01-image14.png", "section": "materials"}, {"src": "assets/01-image15.png", "section": "materials"}, {"src": "assets/01-image16.png", "section": "materials"}, {"src": "assets/01-image17.png", "section": "materials"}, {"src": "assets/01-image18.png", "section": "materials"}, {"src": "assets/01-image19.png", "section": "materials"}, {"src": "assets/01-image20.png", "section": "materials"}, {"src": "assets/01-image21.png", "section": "materials"}, {"src": "assets/01-image22.png", "section": "materials"}, {"src": "assets/01-image23.png", "section": "gallery"}, {"src": "assets/01-image24.png", "section": "gallery"}], "images": ["assets/01-image11.png", "assets/01-image1.png", "assets/01-image16.png", "assets/01-image12.png", "assets/01-image2.png", "assets/01-image17.png", "assets/01-image13.png", "assets/01-image3.png", "assets/01-image18.png", "assets/01-image14.png", "assets/01-image4.png", "assets/01-image19.png", "assets/01-image10.png", "assets/01-image5.png", "assets/01-image20.png", "assets/01-image15.png", "assets/01-image6.png", "assets/01-image21.png", "assets/01-image7.png", "assets/01-image22.png", "assets/01-image8.png", "assets/01-image23.png", "assets/01-image24.png", "assets/01-image9.png"]}, {"id": "02", "title": "Soil Analysis & Fertilizer Use", "category": "agriculture", "cover": "assets/cover-02.webp", "players": "12–16 players", "time": "2 rounds", "intro": "Make soil nutrients visible and learn why different fields need different decisions.", "research": "Game for Low-Formal Education Farmers to Learn How to Improve Soil Quality.", "overview": "Repeated cultivation and limited understanding of soil quality can contribute to degraded farmland and pressure on forests. SAAFU is a learning tool for soil sampling, fertilizer selection and discussion of farmers’ soil-management challenges.", "materials": ["Pre/post tests; green, yellow, orange and pink beads; red, yellow and blue 4 × 4 cm foam pieces.", "Paper clips, six-well plastic trays, 1-inch cassava cards and fertilizer bags for each player.", "A sequence sheet, score board, fertilizer price table, fertilizer containers and a calculator."], "play": ["Arrange 12–16 players in a U shape or small groups. This is a learning activity, not a competition. Begin with a pretest and introduce soil quality, lime and fertilizer formulas.", "Distribute the source guide’s starting soil sets. Beads represent nitrogen, phosphorus, potassium and lime; clips represent organic matter and foam represents soil pH.", "Each six-well tray represents one rai. Players inspect their soil, plant cassava cards and buy fertilizer to meet the game’s crop requirements: N–P–K 22–4–29 and two units of organic matter per rai.", "Check the crop and soil conditions. In the simulation cassava is sold after at least two years, with half-price sales when the specified conditions are not met.", "Discuss nutrient uptake, leaching, fertilizer costs and income. Repeat for two rounds, then debrief and complete the posttest. Consult the source tables for starting sets, prices and soil conditions."], "debrief": "Compare outcomes across soils. Discuss why copying a neighbour’s fertilizer practice can produce different results, how soil analysis can avoid unnecessary expense, and how drought and other factors also affect soil quality. Keep the game’s learning purpose clear.", "file": "documents/02_เกมการวิเคราะห์ดินและการใช้ปุ๋ยอย่างเหมาะสม.docx", "titleTh": "เกมการวิเคราะห์ดิน และ การใช้ปุ๋ยอย่างเหมาะสม (Soil Analysis and Appropriate Fertilizer Use game: SAAFU game)", "introTh": "มองเห็นธาตุอาหารในดิน และเรียนรู้การเลือกปุ๋ยให้เหมาะกับพื้นที่", "researchTh": "เกมการศึกษาเพื่อส่งเสริมการเรียนรู้ด้านการปรับปรุงคุณภาพดิน สำหรับกลุ่มเกษตรกรที่มีข้อจำกัดทางการศึกษาในระบบ (Game for Low-Formal Education Farmers to Learn How to Improve Soil Quality)", "sourceTh": "งานวิจัย", "tags": [{"th": "การวิเคราะห์ดิน", "en": "Soil Analysis"}, {"th": "การใช้ปุ๋ยอย่างเหมาะสม", "en": "Appropriate Fertilizer Use"}, {"th": "ธาตุอาหารในดิน", "en": "Soil Nutrients"}, {"th": "การจัดการที่ดินการเกษตร", "en": "Agricultural Land Management"}, {"th": "การจัดการพื้นที่อนุรักษ์", "en": "Conservation Area Management"}], "sectionsTh": {"overview": "<p>เกษตรกรในพื้นที่พบปัญหาดินเสื่อมโทรมจากการปลูกพืชชนิดเดิมอย่างต่อเนื่อง ทั้งนี้เกษตรกรในพื้นที่มีข้อจำกัดในด้านการศึกษา, ขาดความเข้าใจความสำคัญของคุณภาพดิน, และ วิธีการใช้ปุ๋ยเคมีที่เหมาะสม ทำให้มีการบุกรุกพื้นที่ป่าเพื่อหาพื้นที่สามารถเพราะปลูกใหม่ นำไปสู่ปัญหาการบุกรุกป่า ทำให้พัฒนาเครื่องมือเรียนรู้คือ เกมการวิเคราะห์ดิน และ การใช้ปุ๋ยที่เหมาะสม (SAAFU game) โดยมีวัตถุประสงค์เพื่อ การสร้างความเข้าใจ และ เรียนรู้เกี่ยว วิธีการเก็บตัวอย่างดินเพื่อนำไปวิเคราะห์ การเลือกใช้สูตรปุ๋ยการปลูกพืช รวมถึงเป็นเครื่องมือในการพูดคุยถึงปัญหาที่เกี่ยวข้อง</p>", "materials": "<p>แบบทดสอบก่อน และ หลังการเล่น</p><p>ลูกปัดสีเขียว</p><p>ลูกปัดสีเหลือง</p><p>ลูกปัดสีส้ม</p><p>ลูกปัดสีชมพู</p><p>โฟมสีแดง ขนาด 4x4 เซนติเมตร</p><p>โฟมสีเหลือง ขนาด 4x4 เซนติเมตร</p><p>โฟมสีน้ำเงิน ขนาด 4x4 เซนติเมตร</p><p>คลิปหนีบกระดาษ</p><p>ถาดพลาสสติก ชนิด 6 หลุม</p><p>การ์ดรูปมันสำปะหลัง ขนาด 1x1 นิ้ว</p><p>ถุงปุ๋ยสำหรับผู้เล่นแต่ละคน</p><p>ใบอธิบายขั้นตอนเกม</p><p>กระดานบันทึกคะแนน</p><p>ตารางราคาปุ๋ย</p><p>กล่องใส่ปุ๋ยแต่ละสูตร</p><p>เครื่องคิดเลข</p>", "play": "<p>แนะนำและกติกาเกม</p><p>เป็นเกมสำหรับ 12–16 คน ผู้เล่นจะนั่งเป็นรูปตัว U หรือ แบ่งเป็นกลุ่มย่อย โดยมีพื้นที่สำหรับการวางอุปกรณ์เกม และ ให้ผู้นำเกมหรือผู้ช่วยนำเกมสามารถเขาไปช่วยเหลือและสังเกตการณ์ได้ โดยเกมไม่ได้ออกแบบมาให้ผู้เล่นแข่งขัน ก่อนเล่นเกมจะมีการทำแบบทดสอบก่อนเล่น หลังจากทำแบบทดสอบผู้นำเกมอธิบายความหมายของอุปกรณ์ชนิดต่างๆ อธิบายความหมายของคุณภาพดิน การใช้ปูนขาว และสูตรปุ๋ยชนิดต่างๆ</p><p>นำอุปกรณ์ต่างๆจัดเรียงเป็นชุดดังตารางแจกจ่ายให้ผู้เล่นแต่ละคน โดยลูกปัดสีเขียวแทนธาตุไนโตรเจน ลูกปัดสีเหลืองแทนฟอสฟอรัส ลูกปัดสีส้มแทนโพแทสเซียม ลูกปัดสีชมพูแทนปูนขาว คลิปหนีบกระดาษแทนสารอินทรีย์ และโฟมแต่ละสีแทน pH แต่ละช่วง สีเหลืองแทนดินที่เป็นกลาง (pH 6.5–7.5) สีแดงแทนดินที่เป็นกรด (pH &lt; 6.5)  ถ้าหากมีผู้เล่นเกิน 12 คนผู้เล่นคนที่ 13 เป็นคนไปจะวนกลับมาใช้ชุด 1 ใหม่</p><div class=\"table-scroll\"><table><tbody><tr><td><p>ผู้เล่น</p></td><td><p>ลูกปัดสีเขียว</p><p>(ไนโตรเจน: N)</p></td><td><p>ลูกปัดสีเหลือ</p><p>(ฟอสฟอรัส: P)</p></td><td><p>ลูกปัดสีส้ม</p><p>(โพแทสเซียม: K)</p></td><td><p>คลิปหนีบกระดาษ</p><p>(สารอินทรีย์)</p></td><td><p>สีของโฟม</p><p>(คุณภาพดิน)</p></td></tr><tr><td><p>1</p></td><td><p>19</p></td><td><p>1</p></td><td><p>10</p></td><td><p>0</p></td><td><p>แดง</p></td></tr><tr><td><p>2</p></td><td><p>22</p></td><td><p>1</p></td><td><p>12</p></td><td><p>0</p></td><td><p>แดง</p></td></tr><tr><td><p>3</p></td><td><p>24</p></td><td><p>2</p></td><td><p>6</p></td><td><p>1</p></td><td><p>แดง</p></td></tr><tr><td><p>4</p></td><td><p>24</p></td><td><p>0</p></td><td><p>5</p></td><td><p>1</p></td><td><p>แดง</p></td></tr><tr><td><p>5</p></td><td><p>22</p></td><td><p>1</p></td><td><p>8</p></td><td><p>1</p></td><td><p>แดง</p></td></tr><tr><td><p>6</p></td><td><p>22</p></td><td><p>5</p></td><td><p>27</p></td><td><p>1</p></td><td><p>เหลือง</p></td></tr><tr><td><p>7</p></td><td><p>52</p></td><td><p>2</p></td><td><p>68</p></td><td><p>2</p></td><td><p>เหลือง</p></td></tr><tr><td><p>8</p></td><td><p>31</p></td><td><p>0</p></td><td><p>14</p></td><td><p>1</p></td><td><p>แดง</p></td></tr><tr><td><p>9</p></td><td><p>31</p></td><td><p>8</p></td><td><p>16</p></td><td><p>1</p></td><td><p>แดง</p></td></tr><tr><td><p>10</p></td><td><p>29</p></td><td><p>1</p></td><td><p>5</p></td><td><p>0</p></td><td><p>แดง</p></td></tr><tr><td><p>11</p></td><td><p>34</p></td><td><p>1</p></td><td><p>15</p></td><td><p>1</p></td><td><p>แดง</p></td></tr><tr><td><p>12</p></td><td><p>41</p></td><td><p>3</p></td><td><p>51</p></td><td><p>1</p></td><td><p>น้ำเงิน</p></td></tr></tbody></table></div><p>นำอุปกรณ์ต่างจัดตามสูตรปุ๋ยสำหรับจำหน่ายให้ผู้เล่น</p><div class=\"table-scroll\"><table><tbody><tr><td><p>สูตรปุ๋ย</p></td><td><p>ลูกปัดสีเขียว</p><p>(ไนโตรเจน: N)</p></td><td><p>ลูกปัดสีเหลือ</p><p>(ฟอสฟอรัส: P)</p></td><td><p>ลูกปัดสีส้ม</p><p>(โพแทสเซียม: K)</p></td><td><p>คลิปหนีบกระดาษ</p><p>(สารอินทรีย์)</p></td><td><p>สีของโฟม</p><p>(คุณภาพดิน)</p></td></tr><tr><td><p>46-0-0</p></td><td><p>46</p></td><td><p>-</p></td><td><p>-</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>16-16-8</p></td><td><p>16</p></td><td><p>16</p></td><td><p>8</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>15-15-15</p></td><td><p>15</p></td><td><p>15</p></td><td><p>15</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>15-7-18</p></td><td><p>15</p></td><td><p>7</p></td><td><p>18</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>16-8-8</p></td><td><p>16</p></td><td><p>8</p></td><td><p>8</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>6-3-3</p></td><td><p>6</p></td><td><p>3</p></td><td><p>3</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>16-20-0</p></td><td><p>16</p></td><td><p>20</p></td><td><p>0</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>0-0-60</p></td><td><p>-</p></td><td><p>-</p></td><td><p>60</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>30-0-0</p></td><td><p>30</p></td><td><p>-</p></td><td><p>-</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>ปุ๋ยอินทรีย์</p></td><td><p>-</p></td><td><p>-</p></td><td><p>-</p></td><td><p>2</p></td><td><p>สีเหลือง (1/4 แผ่น)*</p></td></tr><tr><td><p>ปุ๋ยชีวภาพ</p></td><td><p>9</p></td><td><p>3</p></td><td><p>5</p></td><td><p>6</p></td><td><p>สีเหลือง (1/4 แผ่น)*</p></td></tr><tr><td><p>ปูนขาว</p></td><td colspan=\"3\"><p>ลูกปัดสีชมพู 10 ลูก</p></td><td><p>1</p></td><td><p>สีเหลือง</p></td></tr></tbody></table></div><p>*เพื่อแสดงให้เห็นว่าการใส่ปุ๋ยอินทรีย์ไม่ได้ช่วยปรับค่า pH ผู้เล่นสามารถใส่ปุ๋ยเคมีเพิ่มได้</p><p>วิธีการเล่น</p><p>ผู้เล่นตรวจสอบพื้นที่ของต้น (พื้นที่ 1 ไร่ แทนโดยถาดพลาสติก 6 หลุม)</p><p>ผู้เล่นวางการ์ดมันสำปะหลัง และ ซื้อปุ๋ยสำหรับมันสำปะหลัง โดยมันสำปะหลังต้องการสารอาหารเป็น N-P-K คือ 22-4-29 ต่อไร่ และ สารอินทรีย์ 2 หน่วยต่อไร่</p><p>เช็คสารอาหารที่จำเป็นต่อมันสำปะหลัง และ คุณภาพดิน ถ้าหากตรงตามเงื่อนไขสามารถขายมันสำปะหลังได้ โดยมันสำปะหลังจะต้องปลูกอย่างน้อย 2 ปีถึงจะขายได้ แต่ถ้าหากไม่สามารถทำให้ตรงตามเงื่อนไขได้จะขายได้ราคาเพียงครึ่งของราคาเต็ม</p><p>ผู้เล่นนำลูกปัดใส่ถุงและผู้นำเกมให้ความรู้ผู้เล่นเกี่ยวกับการใช้ปุ๋ยของต้นมันสำปะหลัง และ อาจหายไปจากการถูกน้ำฝนชะล้าง</p><p>พูดคุยถึงรายได้ของแต่ละผู้เล่น และ พูดคุยถึงวิธีการใช้ปุ๋ย</p><p>ผู้นำเกมอธิบายถึงข้อดีและข้อเสีย และ เริ่มรอบใหม่</p><p>เมื่อจบ 2 รอบจะมีการสรุปผลและหารือเกี่ยวกับผลลัพธ์การเรียนรู้ และทำแบบทดสอบหลังเล่น</p>", "learning": "", "debrief": "<p>ชี้ให้เห็นถึงการใช้ปุ๋ยแตกต่างกันไปตามสภาพดินให้ผลผลิตที่แตกต่างกัน การใช้ปุ๋ยตามเพื่อนบ้าน หรือ ชาวบ้านคนอื่น ๆ อาจไม่ได้ผลผลิตในระดับที่เท่ากัน ดังนั้นการวิเคราะห์ดินก่อนการเพราะปลูกจึงมีความสำคัญเป็นอย่างมากในการเลือกปุ๋ยชนิดต่าง ๆ อีกทั้งยังลดค่าใช้จ่ายในการซื้อปุ๋ยที่ไม่จำเป็น และ เพิ่มผลผลิตที่ได้อีกด้วย อย่างไรก็ตามยังมีปัจจัยอื่น ๆ ที่ส่งผลต่อคุณภาพดิน เช่น ความแห้งแล้ง หรือ ภัยพิบัติทางการเกษตร และควรย้ำเตือนถึงการเข้าใจวัตถุประสงค์ของเกมผิดพลาดไป</p>", "gallery": ""}, "gallery": [{"src": "assets/02-image25.png", "section": "materials"}, {"src": "assets/02-image26.png", "section": "materials"}, {"src": "assets/02-image27.png", "section": "materials"}, {"src": "assets/02-image28.png", "section": "materials"}, {"src": "assets/02-image31.png", "section": "materials"}, {"src": "assets/02-image32.png", "section": "gallery"}, {"src": "assets/02-image33.png", "section": "gallery"}], "images": ["assets/02-image26.png", "assets/02-image27.png", "assets/02-image28.png", "assets/02-image29.png", "assets/02-image30.png", "assets/02-image25.png", "assets/02-image31.png", "assets/02-image32.png", "assets/02-image33.png"]}, {"id": "03", "title": "Thung Tha Ruea–Pak Phli", "category": "water", "cover": "assets/cover-03.webp", "players": "12 players", "time": "2 rounds", "intro": "Balance livelihoods and a shared wetland as water becomes scarce.", "research": "Studying wetland ecosystem services and community knowledge at Thung Yai Pak Phli, Nakhon Nayok, using Companion Modelling.", "overview": "This game supports shared learning about wetland ecosystem services and climate adaptation at Thung Tha Ruea–Pak Phli. Players explore how natural pressures and human activities affect the wetland and surrounding communities.", "materials": ["Agricultural activity cards (4 × 4 cm), forest-product cards and scenario cards.", "An A2 board, blue and orange beads, dice, pins and playing pieces.", "Player record sheets, information tables and pre/post tests."], "play": ["Pair 12 players into six pairs, divided into three resource levels with two pairs per level. Land endowments and goals differ; use the source table.", "After a pretest, choose farming, water use, chemical use and forest-product collection activities and record decisions. Water is sufficient for everyone in the first year.", "Roll, move and follow board instructions. A player passing the starting space marks one year. Pause for discussion after the first round.", "For the second round, introduce reduced rainfall and additional upstream users. Continue play while facilitators observe adaptation and negotiation.", "After two rounds, complete the posttest and discuss the outcomes."], "debrief": "Compare how land resources, water availability and economic choices affect incomes. Discuss water negotiation, forest-product collection, drought, floods, climate change and outside users, then connect planning decisions to wetland conservation.", "file": "documents/03_เกมเศรษฐีทุ่งท่าเรือ-ปากพลี.docx", "titleTh": "เกมเศรษฐี ทุ่งท่าเรือ-ปากพลี", "introTh": "สร้างสมดุลระหว่างรายได้และพื้นที่ชุ่มน้ำ เมื่อทรัพยากรน้ำมีจำกัด", "researchTh": "การศึกษาการบริการของระบบนิเวศและความรู้ของชุมชนในพื้นที่ชุ่มน้ำทุ่งใหญ่ปากพลี จังหวัดนครนายก ด้วยการประยุกต์ใช้แบบจำลองเพื่อนคู่คิด", "sourceTh": "งานวิจัย", "tags": [{"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "การบริหารจัดการน้ำ", "en": "Water Management"}, {"th": "ความหลากหลายทางชีวภาพ", "en": "Biodiversity"}, {"th": "การเปลี่ยนแปลงสภาพภูมิอากาศ", "en": "Climate Change"}, {"th": "พื้นที่ชุ่มน้ำ", "en": "Wetland"}], "sectionsTh": {"overview": "<p>พื้นที่ชุ่มน้ำทุ่งท่าเรือ-ปากพลีมีความเสี่ยงต่อการกลายเป็นพื้นที่เสื่อมโครง จากปัจจัยธรรมชาติ หรือจากกิจกรรมต่าง ๆ ของมนุษย์ อีกทั้งชุมชนโดยรอบพื้นที่ยังขาดความเข้าใจในพื้นที่ เกมเศรษฐีทุ่งท่าเรือ-ปากพลี จึงสร้างมาเพื่อใช้เป็นเครื่องมือในการสร้างความเข้าใจเกี่ยวกับพื้นที่ชุ่มน้ำ และแลกเปลี่ยนเรียนรู้เกี่ยวกับ บริการระบบนิเวศของพื้นที่ชุ่มน้ำ และ เพื่อสามารถหาลือเกี่ยวกับการต่อการเปลี่ยนแปลงต่อสภาพภูมิอากาศที่เปลี่ยนไป ในพื้นที่ทุ่งท่าเรือ-ปากพลี จังหวัดนครนายก</p>", "materials": "<p>การ์ด</p><p>การ์ดกิจกรรมทางการเกษตร ขนาด 4x4 เซนติเมตร</p><p>การ์ดของป่า</p><p>การ์ดสถาณการณ์</p><p>บอร์ด ขนาด A2</p><p>ลูกปัดสีน้ำเงิน</p><p>ลูกปัดสีส้ม</p><p>ลูกเต๋า</p><p>เข็มหมุด</p><p>หมากสำหรับเดิน</p><p>ตารางบันทึกข้อมูลผู้เล่น</p><p>ตารางข้อมูล</p><p>แบบทดสอบก่อนและหลังเล่น</p>", "play": "<p>แนะนำและกติกาเกม</p><p>เกมเศรษฐีทุ่งท่าเรือ-ปากพลีออกแบบสำหรับผู้เล่น 12 คนสุ่มจับคู่ผู้เล่นและแบ่งออกเป็น 3 ระดับ ระดับละ 2 คู่ โดยแต่ละระดับจะได้ทรัพยากรต้นทุนที่ดิน และเป้าหมายต่างกันดังตาราง</p><div class=\"table-scroll\"><table><tbody><tr><td><p>ระดับ</p></td><td><p>ต้นทุนที่ดิน (ช่อง)</p></td><td><p>เป้าหมาย</p></td></tr><tr><td><p>ผู้เล่นระดับ 1</p></td><td><p>10</p></td><td><p>เก็บเงินปลดหนี้ 5,000 บาท</p></td></tr><tr><td><p>ผู้เล่นระดับ 2</p></td><td><p>20</p></td><td><p>เก็บเงิน 8,000 บาท เพื่อซื้อเครื่องซักผ้า</p></td></tr><tr><td><p>ผู้เล่นระดับ 3</p></td><td><p>30</p></td><td><p>เก็บเงิน 10,000 บาท เพื่อไปเที่ยวต่างประเทศ</p></td></tr></tbody></table></div><p>ผู้เล่นจะกำหมดผู้เริ่มเล่นคนแรกโดยการโยนเต๋า ผู้ที่โยนได้มากที่สุดจะได้เริ่มเล่นเป็นคนแรกแล้วเวียนไปทางซ้ายหรือขวาตามตกลง ผู้เล่นจะทำการโยนเต๋าและเดินบนช่องในบอร์ดและทำกิจกรรมจามที่ช่องกำหนด โดยบอร์ดจะมีทั้งหมด 27 ช่อง แบ่งเป็นช่องคำถาม 4 ช่อง ช่องคำถามฤดูแล้งและฤดูน้ำหลาก 6 ช่อง ช่องความรู้ 14 ช่อง และ ช่องหาของป่า 3 ช่อง โดยเล่นทั้งหมด 2 รอบกำหนดให้ 1 รอบแทน 1 ปี กำหนดให้ลูกปัดสีน้ำเงินแทนน้ำ และ ลูกปัดสีส้มแทนสารเคมีกำจัดวัชพืช</p><p>ช่องความรู้และเป้าหมายการเรียนรู้</p><div class=\"table-scroll\"><table><tbody><tr><td><p>รายละเอียดช่องความรู้ตามช่องต่าง ๆ ในเกมบอร์ด</p></td><td><p>เป้าหมาย การเรียนรู้</p></td></tr><tr><td><p>ช่องที่ 1: บอกของดีของ ต.ท่าเรือ 1 อย่าง</p></td><td><p>จุดเด่นและความสำคัญของพื้นที่</p></td></tr><tr><td><p>ช่องที่ 2: ให้เช่านาทำไร่แตงโมดินเสีย ผลผลิตข้าวเสียหาย</p></td><td><p>สาเหตุที่ทำให้พื้นที่ชุ่มน้ำเสื่อมโทรม</p></td></tr><tr><td><p>ช่องที่ 3: ยกตัวอย่างวัฒนธรรมที่เกี่ยวกับข้าว ปลูกข้าวเพิ่ม 1 ช่อง</p></td><td><p>การบริการของระบบนิเวศพื้นที่ชุ่มน้ำด้านวัฒนธรรม</p></td></tr><tr><td><p>ช่องที่ 4: บอกชื่อพันธุ์ข้าวพื้นเมืองของทุ่งท่าเรือปลูกข้าวเพิ่ม 1 ช่อง</p></td><td><p>การบริการของระบบนิเวศพื้นที่ชุ่มน้ำด้านการสนับสนุน</p></td></tr><tr><td><p>ช่องที่ 5: ทำบุญสงกรานต์แล้วแต่ศรัทธา</p></td><td><p>จำลองสถานการณ์เสมือนจริงที่อาจเกิดขึ้นได้</p></td></tr><tr><td><p>ช่องที่ 6: รถไถพังไถนาไม่ทันดึงนาออก 2 ช่อง</p></td><td><p>จำลองสถานการณ์เสมือนจริงที่อาจเกิดขึ้นได้</p></td></tr><tr><td><p>ช่องที่ 7: บอกของป่าที่หาได้ในช่วงฤดูฝน 1 ชนิด รับของป่าฟรี 2 กก.</p></td><td><p>การบริการของระบบนิเวศพื้นที่ชุ่มน้ำด้านการเป็นแหล่งผลิต</p></td></tr><tr><td><p>ช่องที่ 8: บอกวิธีการอนุรักษ์พื้นที่ชุ่มน้ำทุ่งท่าเรือ-ปากพลีให้สมบูรณ์ 1 ข้อ เพิ่มน้ำให้ระบบ 2 หน่วย</p></td><td><p>วิธีการอนุรักษ์พื้นที่ชุ่มน้ำและรักษาการบริการของระบบนิเวศพื้นที่ชุ่มน้ำ</p></td></tr><tr><td><p>ช่องที่ 9: นักท่องเที่ยวมาดูวิถีการเลี้ยงควายในทุ่ง คนเลี้ยงควายท่องเที่ยวเชิงนิเวศ ค้าขาย โฮมสเตย์ รับเงินเพิ่ม 200</p></td><td><p>การบริการของระบบนิเวศพื้นที่ชุ่มน้ำด้านวัฒนธรรม</p></td></tr><tr><td><p>ช่องที่ 10: จงหาปลาซิวสมพงษ์ในทุ่งท่าเรือ-ปากพลี (บอร์ดเกม) ให้เจอรับของป่าฟรี 1 กก.</p></td><td><p>รู้จักปลาซิวสมพงษ์ ปลาที่มีความเสี่ยงขั้นวิกฤตต่อการสูญพันธุ์ (Critical Endanger species)</p></td></tr><tr><td><p>ช่องที่ 11: โชคดีสุดๆ ถูกหวยเลขท้าย 2 ตัวรับเงิน 2,000</p></td><td><p>สร้างสถานการณ์เสมือนจริงที่อาจเกิดขึ้นได้</p></td></tr><tr><td><p>ช่องที่ 12: นักศึกษาเข้ามาวิจัยประเพณีเรียกขวัญข้าว ชาวนาทุกคนได้รับเงิน 300</p></td><td><p>การบริการของระบบนิเวศพื้นที่ชุ่มน้ำด้านวัฒนธรรม</p></td></tr><tr><td><p>ช่องที่ 13: ทุ่งท่าเรือ-ปากพลี มีอะไรที่ทำให้นกเหยี่ยวหรือสิ่งมีชีวิตมากมายอาศัยอยู่ที่นี่ได้</p></td><td><p>ความสัมพันธ์ขององค์ประกอบต่าง ๆ ในระบบนิเวศพื้นที่ชุ่มน้ำ</p></td></tr><tr><td><p>ช่องที่ 14: ช่วงนี้มีการลงแขกเกี่ยวข้าวเสียเงินทำอาหารเลี้ยงแขก 300</p></td><td><p>การบริการของระบบนิเวศพื้นที่ชุ่มน้ำด้านวัฒนธรรม</p></td></tr></tbody></table></div><p>คำถามและเป้าหมายการเรียนรู้</p><div class=\"table-scroll\"><table><tbody><tr><td><p>รายละเอียดการ์ดคำถาม</p></td><td><p>เป้าหมาย การเรียนรู้</p></td></tr><tr><td><p>บอกผลกระทบของการไม่มีทุ่งท่าเรือ-ปากพลีต่อการดำรงชีวิตของตนเอง</p></td><td><p>การบริการของระบบนิเวศพื้นที่ชุ่มน้ำต่อตนเอง</p></td></tr><tr><td><p>ปัญหาที่พบเกี่ยวกับการใช้ประโยชน์พื้นที่ชุ่มน้ำทุ่งท่าเรือ-ปากพลีในฤดูแล้งคืออะไรและอยากให้หน่วยงานรัฐช่วยอะไร</p></td><td><p>ปัญหาและความต้องการสำหรับการแก้ปัญหาการใช้ประโยชน์พื้นที่ชุ่มน้ำในฤดูแล้ง</p></td></tr><tr><td><p>ปัญหาที่พบเกี่ยวกับการใช้ประโยชน์พื้นที่ชุ่มน้ำทุ่งท่าเรือ-ปากพลีในฤดูน้ำหลากคืออะไรและอยากให้ช่วยอะไร</p></td><td><p>ปัญหาและความต้องการสำหรับการแก้ปัญหาการใช้ประโยชน์พื้นที่ชุ่มน้ำในฤดูน้ำหลาก</p></td></tr><tr><td><p>บอกประโยชน์และความสำคัญของพื้นที่ทุ่งท่าเรือ-ปากพลีต่อการเป็นแหล่งผลิตอาหาร</p></td><td><p>การบริการของระบบนิเวศด้านแหล่งผลิต</p></td></tr><tr><td><p>บอกประโยชน์และความสำคัญของพื้นที่ทุ่งท่าเรือ-ปากพลี ในด้านวัฒนธรรมและการศึกษา 1 ข้อ</p></td><td><p>การบริการของระบบนิเวศด้านวัฒนธรรม</p></td></tr></tbody></table></div><p>เหตุการณ์หรือสถานการณ์จำลองทางด้านสิ่งแวดล้อมและสังคม</p><div class=\"table-scroll\"><table><tbody><tr><td><p>รายละเอียดการ์ด</p></td><td><p>เป้าหมายการเรียนรู้</p></td></tr><tr><td colspan=\"2\"><p>เหตุการณ์/สถานการณ์จำลองทางด้านสิ่งแวดล้อม</p></td></tr><tr><td><p>อากาศร้อนและแห้งแล้งแมลงศัตรูพืชระบาด นาข้าว ปลูกพืชเศรษฐกิจผลผลิตเสียหาย ทุกคนถอนช่องการใช้ประโยชน์ดังกล่าวออก 1 ช่อง</p></td><td><p>ผลกระทบของการเปลี่ยนแปลงสภาพภูมิอากาศ</p></td></tr><tr><td><p>น้ำแล้งมากรายได้จากทุกการใช้ประโยชน์ลดลง จ่ายเงินเข้ากองกลาง 100</p></td><td><p>ผลกระทบของน้ำต่อคุณภาพชีวิตของชุมชน</p></td></tr><tr><td><p>น้ำในระบบนิเวศน้อยการประกอบอาชีพหยุดชะงักผู้หยิบการ์ดนี้เดินถอยหลัง 1 ช่อง</p></td><td><p>ผลกระทบของน้ำต่อคุณภาพชีวิตของชุมชน</p></td></tr><tr><td><p>พื้นที่ชุ่มน้ำมีน้ำหลากตามธรรมชาติเป็นที่อยู่อาศัยของปลา ร้านค้าขายมีรายได้จากการขายปลาแปรรูป รับเงิน 200</p></td><td><p>การบริการของระบบนิเวศด้านแหล่งผลิต</p></td></tr><tr><td><p>ฝนตกหลังจากแห้งแล้งมานาน ผู้ปลูกพืชเศรษฐกิจพืชไม่ตาย โตทันเก็บเกี่ยว รับเงินเพิ่ม 200</p></td><td><p>การบริการของระบบนิเวศด้านการควบคุม</p></td></tr><tr><td><p>พื้นที่ชุ่มน้ำสมบูรณ์ อากาศไม่แปรปรวน รายได้ดี ทุกคนได้รับรางวัลพิเศษ 1 ชิ้น</p></td><td><p>การบริการของระบบนิเวศด้านการควบคุม</p></td></tr><tr><td><p>น้ำลดทำให้พืชฤดูแล้งเจริญเติบโต เกิดความหลากหลาย เพิ่มของป่า 1 กก.</p></td><td><p>การบริการของระบบนิเวศด้านการสนับสนุน</p></td></tr><tr><td><p>น้ำหลากตามฤดูกาลเป็นที่อยู่ของพืชและสัตว์น้ำ เพิ่มพืชและสัตว์ อย่างละ 1 กก.</p></td><td><p>การบริการของระบบนิเวศด้านการสนับสนุน</p></td></tr><tr><td><p>น้ำท่วมพัดพาปลาจากที่อื่นเข้ามาในทุ่ง เพิ่มสัตว์น้ำลงในทุ่ง 5 กก.</p></td><td><p>การบริการของระบบนิเวศด้านการสนับสนุน</p></td></tr><tr><td><p>น้ำหลากตามฤดูกาลพัดพาตะกอนดินทำให้ดินสมบูรณ์นาข้าวได้ผลผลิตดี ใครที่ทำนาได้รับเงินเพิ่ม 500</p></td><td><p>การบริการของระบบนิเวศด้านการสนับสนุน</p></td></tr><tr><td><p>น้ำท่วมไหลทะลักเข้าบ่อปลา ปลาหลุดไปตามน้ำ คนเลี้ยงปลาทุกคนดึงบ่อปลาออก 1 ช่อง</p></td><td><p>จำลองสถานการณ์ที่อาจเกิดขึ้นได้และเรียนรู้การปรับตัว</p></td></tr><tr><td><p>ฝนเทลงมาอย่างหนักน้ำหลากเก็บของไม่ทันร้านค้าทุกร้านเสียหายขาดทุน 500</p></td><td><p>จำลองสถานการณ์ที่อาจเกิดขึ้นได้และเรียนรู้การปรับตัว</p></td></tr><tr><td><p>เกิดพายุฤดูร้อนทำให้โฮมสเตย์เสียหาย ผู้ทำอาชีพโฮมสเตย์ เสียเงินซ่อมหลังคา 500</p></td><td><p>จำลองสถานการณ์ที่อาจเกิดขึ้นได้และเรียนรู้การปรับตัว</p></td></tr><tr><td><p>รายละเอียดการ์ด</p></td><td><p>เป้าหมายการเรียนรู้</p></td></tr><tr><td><p>ฝนตกหนักต่อกันหลายวันผู้ปลูกพืชเศรษฐกิจทุกคนถูกน้ำท่วมเสียหาย ขาดทุน 200</p></td><td><p>จำลองสถานการณ์ที่อาจเกิดขึ้นได้และเรียนรู้การปรับตัว</p></td></tr><tr><td colspan=\"2\"><p>เหตุการณ์/สถานการณ์จำลองทางด้านสังคม</p></td></tr><tr><td><p>มีคนนอกมาจับปลาในปริมาณมากทำให้ปลาลดลง หยิบปลาชนิดใดก็ได้ออก 5 กก.</p></td><td><p>สาเหตุที่กระทบต่อความสมบูรณ์ของพื้นที่ชุ่มน้ำและส่งผลต่อคุณภาพชีวิตของชุมชน</p></td></tr><tr><td><p>มีการปล่อยน้ำเสียสู่แหล่งน้ำ ผู้ทำอาชีพติดริมคลองได้รับผลกระทบ ผลผลิตเสียหาย 200</p></td><td><p>สาเหตุที่กระทบต่อความสมบูรณ์ของพื้นที่ชุ่มน้ำและส่งผลต่อคุณภาพชีวิตของชุมชน</p></td></tr><tr><td><p>โชคร้ายจริงๆคนที่หยิบการ์ดนี้สมมุติให้คุณ คือ คนจับปลาในฤดูวางไข่ ถอยหลัง 2 ช่อง</p></td><td><p>สาเหตุที่กระทบต่อความสมบูรณ์ของพื้นที่ชุ่มน้ำและส่งผลต่อคุณภาพชีวิตของชุมชน</p></td></tr><tr><td><p>มีการสร้างถนนนอกพื้นที่ขวางทางน้ำ ปลาในพื้นที่ลดลง หยิบปลาออก 3 ชนิด ชนิดละ 1 กก.</p></td><td><p>สาเหตุที่กระทบต่อความสมบูรณ์ของพื้นที่ชุ่มน้ำและส่งผลต่อคุณภาพชีวิตของชุมชน</p></td></tr><tr><td><p>มีความต้องการข้าวอินทรีย์ ผู้ปลูกข้าวไม่ใช้ยากำจัดวัชพืชรับเงินเพิ่ม 500</p></td><td><p>จำลองสถานการณ์ที่อาจเกิดขึ้นได้และเรียนรู้การปรับตัว</p></td></tr><tr><td><p>ททท.ส่งเสริมการท่องเที่ยวดูกนกเหยี่ยวและการท่องเที่ยวเชิงอนุรักษ์ ท่องเที่ยว ค้าขาย หรือโฮมสเตย์ได้รับเงิน 300</p></td><td><p>จำลองสถานการณ์ที่อาจเกิดขึ้นได้และเรียนรู้การปรับตัว</p></td></tr><tr><td><p>มีการรวมกลุ่มพัฒนาผลิตภัณฑ์ปลาแปรรูป เพื่อเพิ่มมูลค่า คนที่เก็บของป่าหรือร้านค้ารับรายได้เพิ่ม 100</p></td><td><p>จำลองสถานการณ์ที่อาจเกิดขึ้นได้และเรียนรู้การปรับตัว</p></td></tr><tr><td><p>มีคนเข้ามาท่องเที่ยวดูความสวยงามของทุ่งท่าเรือจำนวนมากทำให้มีขยะเพิ่มขึ้นโฮมสเตย์จ่ายเงินค่าจัดการขยะ 300</p></td><td><p>บริการของระบบนิเวศด้านวัฒนธรรม</p></td></tr><tr><td><p>นักท่องเที่ยวมาดูควายอาบน้ำในทุ่ง คนเลี้ยงควายมีรายได้เพิ่มสามารถรับรายได้เพิ่ม 100</p></td><td><p>บริการของระบบนิเวศด้านวัฒนธรรม</p></td></tr></tbody></table></div><p>ขั้นตอนการเล่น</p><p>ผู้เล่นทำแบบทดสอบก่อนเล่น</p><p>ผู้เล่นตัดสินใจทำกิจกรรมตามต้นทุนที่ดินที่ผู้เล่นแต่ละคนมี เช่น การใช้กิจกรรมทางการเกษตร การใช้น้ำ การใช้สารเคมีต่าง ๆ ในพื้นที่ และการเก็บของป่า แล้วจดบันทึก (ในปีที่ 1 จะกำหนดให้น้ำเพียงพอสำหรับทุกผู้เล่น)</p><p>ผู้เล่นโยนลูกเต๋า เดินไปตามช่องบนบอร์ด เมื่อตกช่องบนบอร์ดให้ผู้เล่นปฏิบัติตามที่แต่ละช่องกำหนด</p><p>เมื่อผู้เล่นคนใดคนหนึ่งเดินผ่านจุดเริ่มต้นอีกครั้ง จะถือว่าผ่านไป 1 รอบปี</p><p>ผู้คุมเกมหยุดเกมไว้ชั่วคราว และ อภิปรายสรุปผลต่าง ๆ ภายในรอบแรก</p><p>เริ่มรอบที่ 2 โดยผู้คุมเกมแจ้งผู้เล่นว่าปริมาณน้ำฝนในปีนี้มีปริมาณลดลง และ มีผู้คนจากภายนอกพื้นที่เข้ามาใช้ประโยชน์บริเวณต้นน้ำ (ปริมาณน้ำลดลง)</p><p>ดำเนินตามขั้นตอนโดยมีผู้ช่วยคุมเกมสังเกตพฤติกรรม</p><p>เมื่อเล่นเกมครบ 2 รอบให้ผู้เล่นทำแบบทดสอบหลังเล่นเกม</p><p>สรุปและอภิปรายความรู้ต่าง ๆ ที่ได้จากการเล่นเกม</p>", "learning": "", "debrief": "<p>ชี้ให้เห็นถึงการเลือกประกอบกิจกรรมทางเศรษฐกิจที่แตกต่างกันไปตามสถานการณ์น้ำและต้นทุนที่ดิน ส่งผลต่อรายได้และการปรับตัวที่แตกต่างกัน การเลือกทำกิจกรรมโดยไม่คำนึงถึงทรัพยากรน้ำที่มีอยู่อย่างจำกัดอาจทำให้เกิดปัญหาและขาดทุนได้ ดังนั้นการประเมินสถานการณ์และวางแผนบริหารจัดการน้ำก่อนตัดสินใจลงทุนจึงมีความสำคัญเป็นอย่างมากในการเลือกอาชีพ อีกทั้งยังช่วยกระตุ้นให้เกิดการเจรจาต่อรองเรื่องการใช้น้ำ ลดพฤติกรรมการเก็บหาของป่าที่มากเกินความจำเป็น และปรับเปลี่ยนพฤติกรรมเพื่อรักษาสมดุลของระบบนิเวศได้อีกด้วย อย่างไรก็ตามยังมีปัจจัยภายนอกอื่น ๆ ที่ส่งผลกระทบต่อพื้นที่ชุ่มน้ำ เช่น การเปลี่ยนแปลงสภาพภูมิอากาศ ภัยแล้ง น้ำหลาก หรือการเข้ามาใช้ประโยชน์จากคนนอกพื้นที่</p>", "gallery": ""}, "gallery": [{"src": "assets/03-image34.png", "section": "materials"}, {"src": "assets/03-image35.png", "section": "materials"}, {"src": "assets/03-image36.png", "section": "materials"}, {"src": "assets/03-image38.png", "section": "materials"}, {"src": "assets/03-image40.png", "section": "gallery"}], "images": ["assets/03-image35.png", "assets/03-image36.png", "assets/03-image37.png", "assets/03-image38.png", "assets/03-image39.png", "assets/03-image40.png", "assets/03-image34.png"]}, {"id": "04", "title": "Herptile ESs", "category": "biodiversity", "cover": "assets/cover-04.webp", "players": "4–6 players", "time": "Facilitator-led", "intro": "Discover the ecological roles of amphibians and reptiles in agricultural landscapes.", "research": "Gaming and simulation for learning about amphibian and reptile ecosystem services in agricultural ecosystems in Nan Province.", "overview": "Agricultural chemicals, forest burning and other human activities threaten amphibian and reptile diversity. Herptile ESs makes their benefits, relationships and vulnerability visible and creates a space for participants to discuss conservation.", "materials": ["Habitat diagrams; amphibian and reptile cards (5.5 × 8.6 cm); question and event cards.", "An A2 board, six colours of pins, playing pieces and dice.", "Pre/post tests and the game manual."], "play": ["Seat 4–6 players around a board. Agree the duration with the facilitator. Each player receives twenty pins of one colour and a playing piece.", "Roll to select a starting player and agree a direction of play. Learn to read species cards, habitat symbols and the board using the source guide.", "Move around the board and follow its instructions, answer questions and resolve events. Relate species to their habitats and ecosystem roles.", "At conservation spaces, suggest ways to protect amphibians and reptiles. Finish with a shared learning summary and the assessment activities. Use the source tables for detailed card effects and conditions."], "debrief": "Discuss amphibian and reptile diversity, the ecosystem services these animals provide and the effects of farming and chemicals. Connect observations in play to practical conservation and the role of species as biological indicators.", "file": "documents/04_Herptile ESs.docx", "titleTh": "Herptile ESs", "introTh": "ค้นพบบทบาทของสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานในพื้นที่เกษตร", "researchTh": "เกมและสถานการณ์จำลองเพื่อการเรียนรู้เรื่องบริการทางระบบนิเวศของสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานในระบบนิเวศเกษตร จังหวัดน่าน", "sourceTh": "งานวิจัย", "tags": [{"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "ความหลากหลายทางชีวภาพ", "en": "Biodiversity"}, {"th": "สัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลาน", "en": "Amphibians and Reptiles"}, {"th": "สิ่งมีชีวิตเฝ้าระวังทางชีวภาพ", "en": "Bio-Sentinel Species"}, {"th": "ผลกระทบจากการเกษตรและสารเคมี", "en": "Agricultural and Chemical Impacts"}, {"th": "การอนุรักษ์", "en": "Conservation"}], "sectionsTh": {"overview": "<p>ระบบนิเวศเกษตรในปัจจุบันกำลังพบปัญหาการสูญเสียความหลากหลายทางชีวภาพของสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลาน ซึ่งได้รับผลกระทบจากกิจกรรมของมนุษย์ เช่น การใช้สารเคมี และการเผาป่า อีกทั้งชุมชนต่าง ๆ ยังไม่เห็นถึงผลกระทบที่เกิดขึ้น จึงมีการพัฒนาเครื่องมือที่สามารถชี้ให้เห็นถึงผลกระทบ และ ประโยชน์ของสัตว์กลุ่มนี้ เกม Herptile ESs ถูกพัฒนาขึ้นเพื่อให้ผู้ใช้งานสามารถเข้าใจความสำคัญ ประโยชน์ที่ได้รับ และ ความสัมพันธ์ของสัตว์กลุ่มนี้ รวมทั้งยังพัฒนาเพื่อเป็นสื่อกลางในการพูดคุยกันของผู้ใช้งานอีกด้วย</p>", "materials": "<p>การ์ด</p><p>แผนภาพที่อยู่อาศัย</p><p>การ์ดสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลาน ขนาด 5.5x8.6 เซนติเมตร</p><p>การ์ดคำถาม</p><p>การ์ดเหตุการณ์</p><p>บอร์ด ขนาด A2 (หน้าถัดไป)</p><p>เข็มหมุด 6 สี</p><p>หมากเดิน</p><p>ลูกเต๋า</p><p>แบบทดสอบก่อนเล่นเกม</p><p>แบบทดสอบหลังเล่นเกม</p><p>คู่มือการเล่นเกม</p>", "play": "<p>แนะนำและกติกาเกม</p><p>เกมสร้างสำหรับผู้เล่น 4–6 คนต่อกลุ่มโดยผู้เล่นแต่ละคนจะนั่งรอบกระดาน ระยะเวลาในการเล่นตามความเหมาะสมหรือผู้คุมเกมเป็นคนกำหนด โดยผู้เล่นจะโยนเต๋าเพื่อกำหนดผู้เริ่ม และ วนไปทางซ้ายหรือทางขวา ผู้เล่นแต่ละคนจะได้รับเซ็ตอุปกรณ์ประกอบไปด้วย เข็มหมุดสี 20 อัน หมากเดิน 1 สี</p><p>องค์ประกอบของภาพ</p><div class=\"table-scroll\"><table><tbody><tr><td><p>องค์ประกอบ</p></td><td><p>สัญลักษณ์</p></td><td><p>คำอธิบายองค์ประกอบ</p></td></tr><tr><td><p>รูปสัตว์</p></td><td></td><td><p>รูปภาพของสัตว์สะเทินน้ำสะเทินบกหรือสัตว์เลื้อยคลาน</p></td></tr><tr><td><p>ชื่อภาษาไทย (กลาง)</p></td><td></td><td><p>อยู่บริเวณขอบด้านซ้ายล่างของการ์ด</p></td></tr><tr><td><p>ชื่อวิทยาศาสตร์</p></td><td></td><td><p>อยู่ถัดจากชื่อภาษาไทย</p></td></tr><tr><td><p>กลุ่มสัตว์</p></td><td></td><td><p>อยู่บริเวณมุมซ้ายบนของภาพ โดย- รูปงู แทนสัตว์เลื้อยคลาน- รูปกบ แทนสัตว์สะเทินน้ำสะเทินบก</p></td></tr><tr><td><p>ที่อยู่อาศัย</p></td><td></td><td><p>อยู่บริเวณด้านบนของการ์ดเหนือรูปสัตว์ มีทั้งหมด 6 รูปแบบเท่ากับแผ่นภาพที่อยู่อาศัย ได้แก่ นาข้าว ไร่ สวน ปศุสัตว์ บ่อเลี้ยง และแหล่งน้ำ หากการ์ดสัตว์ปรากฏที่อยู่อาศัยหลายรูปแบบแสดงว่าสัตว์ชนิดนั้นปรับตัวได้ดีและสามารถอาศัยอยู่ในพื้นที่ได้หลากหลาย</p></td></tr><tr><td><p>คะแนนบริการทางระบบนิเวศ</p></td><td></td><td><p>อยู่มุมล่างขวาของรูปสัตว์ มีตั้งแต่ 1-5 คะแนน ยิ่งมีบริการทางระบบนิเวศมากจะยิ่งมีคะแนนสูง</p></td></tr></tbody></table></div><div class=\"table-scroll\"><table><tbody><tr><td><p>องค์ประกอบ</p></td><td><p>สัญลักษณ์</p></td><td><p>คำอธิบายองค์ประกอบ</p></td></tr><tr><td><p>บริการทางระบบนิเวศ</p></td><td></td><td><p>ด้านการเป็นแหล่งผลิต (Provisioning; P) คือ ประโยชน์โดยตรงที่มนุษย์ได้รับจากระบบนิเวศ เช่น นำมาเป็นอาหารของมนุษย์ (รูปช้อนส้อม) นำหนังสัตว์มาทำของใช้หรือเครื่องประดับ (รูปกระเป๋า)</p></td></tr><tr><td></td><td></td><td><p>ด้านการควบคุม (Regulating services; R) ย่อมาจาก “บริการด้านการควบคุมและสนับสนุน” คือ การรักษาสมดุลของระบบนิเวศ การควบคุมประชากรกันและกันให้มีความสมดุล (ภาพงูกับช้อนส้อมสื่อว่าสัตว์ในการ์ดนั้นเป็นอาหารของงู ส่วนภาพสิ่งมีชีวิตอื่น คือ สิ่งที่สัตว์ในการ์ดนั้นกินเป็นอาหาร)</p></td></tr><tr><td></td><td></td><td><p>สิ่งมีชีวิตเฝ้าระวัง (Bio-sentinel species) คือ สิ่งมีชีวิตที่ชี้วัดคุณภาพระบบนิเวศ การถูกรบกวนในพื้นที่อาศัย และการปนเปื้อนสารเคมี ถือเป็นบริการด้านการควบคุม</p></td></tr><tr><td></td><td></td><td><p>ด้านวัฒนธรรม (Cultural services; C) คือ ประโยชน์ในแง่วัฒนธรรม ประเพณี ความเชื่อ เช่น ตำนานและเรื่องเล่า สื่อต่าง ๆ รวมถึงการนำมาเลี้ยงเพื่อความเพลิดเพลิน</p></td></tr></tbody></table></div><div class=\"table-scroll\"><table><tbody><tr><td><p>องค์ประกอบ</p></td><td><p>สัญลักษณ์</p></td><td><p>คำอธิบายองค์ประกอบ</p></td></tr><tr><td><p>เกร็ดความรู้</p></td><td></td><td><p>อยู่บริเวณใต้รูปสัตว์ เป็นความรู้เสริมเกี่ยวกับสัตว์นอกเหนือจากเรื่องบริการทางระบบนิเวศ (ภาพตัวอย่างคือเกร็ดความรู้ของการ์ดงูเห่า)</p></td></tr><tr><td><p>ข้อมูลเพิ่มเติม</p></td><td></td><td><p>เป็นข้อมูลเพิ่มเติมที่ผู้เล่นควรทราบ</p></td></tr><tr><td><p>สีการ์ด</p></td><td></td><td><p>มี 6 สีตามจำนวนแผ่นภาพที่อยู่อาศัย โดย</p><p>- สีฟ้าแทนแหล่งน้ำ</p><p>- สีเหลืองแทนนา</p><p>- สีน้ำตาลแทนไร่</p><p>- สีแดงแทนปศุสัตว์</p><p>- สีเขียวแทนสวน</p><p>- สีส้มแทนบ่อเลี้ยง</p></td></tr></tbody></table></div><p>รายละเอียดการ์ดเหตุการณ์</p><div class=\"table-scroll\"><table><tbody><tr><td><p>หมายเลข</p></td><td><p>ชื่อการ์ด</p></td><td><p>ผลที่ได้รับ</p></td><td><p>องค์ความรู้ที่ได้</p></td></tr><tr><td><p>1-4</p></td><td><p>ศัตรูพืชเพิ่มจำนวน (แมลง หนู ปู หอยเชอรี่)</p></td><td><p>ผู้เล่นเสียพื้นที่ทางการเกษตร แต่ถ้ามีการ์ดสัตว์ที่กินศัตรูพืชนั้น ๆ ตามจำนวนที่กำหนดจะไม่ได้รับผลกระทบ</p></td><td><p>สัตว์ที่กินศัตรูพืชจะช่วยควบคุมไม่ให้จำนวนศัตรูพืชมากเกินไปจนทำให้พืชผลทางการเกษตรเสียหาย (บริการด้านการควบคุม)</p></td></tr><tr><td><p>5</p></td><td><p>ฝนทิ้งช่วง แล้งนานกว่าปกติ</p></td><td><p>เสียพื้นที่ทางการเกษตรและเสียการ์ดสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานอย่างละ 1 ใบ</p></td><td><p>ความแปรปรวนของสภาพอากาศเป็นสิ่งที่ไม่สามารถคาดเดาได้ ซึ่งนอกจากจะทำให้ผลผลิตเสียหาย สัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานยังได้รับผลกระทบและอาจลดจำนวนลง</p></td></tr></tbody></table></div><div class=\"table-scroll\"><table><tbody><tr><td><p>หมายเลข</p></td><td><p>ชื่อการ์ด</p></td><td><p>ผลที่ได้รับ</p></td><td><p>องค์ความรู้ที่ได้</p></td></tr><tr><td><p>6</p></td><td><p>ใช้ยาฆ่าหญ้าและแมลง (ผลต่อสิ่งมีชีวิต)</p></td><td><p>1. การ์ดกบหนองไม่สามารถอยู่บนมือได้ 3 ตา2. เสียการ์ดสัตว์สะเทินน้ำสะเทินบกหรือสัตว์เลื้อยคลาน 1 ใบ เพราะพื้นที่ของผู้เล่นคนอื่นที่ติดกัน 3 ช่องปนเปื้อนสารเคมี</p></td><td><p>กบหนองจัดเป็นสิ่งมีชีวิตเฝ้าระวังทางชีวภาพ (bio-sentinel species) วัดคุณภาพและการปนเปื้อนสารเคมีในพื้นที่ (บริการด้านการควบคุม) สารเคมียังส่งผลต่อสัตว์ชนิดอื่นด้วย (Mingo et al., 2016; Septiadi et al., 2021; Simbula et al., 2021)</p></td></tr><tr><td><p>7</p></td><td><p>ใช้ยาฆ่าหญ้าและแมลง (ผลต่อสุขภาพคน)</p></td><td><p>หยุดเล่น 1 ตาเพื่อพักรักษาตัว</p></td><td><p>ผู้ใช้งานได้รับสารเคมีทางการเกษตรได้จากการสูดละออง การสัมผัส หรือการบริโภค ซึ่งส่งผลกระทบต่อสุขภาพแตกต่างกันไป ขึ้นอยู่กับหลายปัจจัย เช่น ชนิดของสารเคมี ความเข้มข้น และระยะเวลาที่ได้รับ (Damalas et al., 2016; EPA, 2022)</p></td></tr><tr><td><p>8</p></td><td><p>สารเคมีสะสมในพื้นที่เพาะปลูก</p></td><td><p>กลับไปเริ่มที่จุด Start รอสารเคมีสลายตัว</p></td><td><p>ดินเสื่อมสภาพจากสารเคมี ซึ่งเป็นอันตรายต่อสิ่งมีชีวิตโดยรอบและมนุษย์ด้วย</p></td></tr><tr><td><p>9</p></td><td><p>น้ำเสียจากปศุสัตว์ปนเปื้อนแหล่งน้ำในชุมชน</p></td><td><p>เสียพื้นที่ทางการเกษตรและเสียการ์ดสัตว์สะเทินน้ำสะเทินบกหรือการ์ดสัตว์เลื้อยคลาน 1 ใบ</p></td><td><p>ของเสียจากปศุสัตว์อาจทำให้คุณภาพน้ำในแหล่งน้ำต่ำลง ส่งผลให้สัตว์น้ำตาย และอาจเป็นแหล่งก่อโรคต่อมนุษย์ได้ (กรมส่งเสริมคุณภาพสิ่งแวดล้อม กระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม, 2558)</p></td></tr><tr><td><p>10-11, 13</p></td><td><p>คนจับกบ/งูสิงไปกินมากเกินไป</p></td><td><p>เสียพื้นที่การเกษตร เพราะแมลงเพิ่มจำนวน</p></td><td><p>สัตว์ที่ควบคุมจำนวนศัตรูพืชลดลงทำให้ศัตรูพืชเพิ่มจำนวนขึ้น</p></td></tr><tr><td><p>12</p></td><td><p>การวางกับดักปลา</p></td><td><p>เสียการ์ดงูสายรุ้ง งูปลิง หรืองูแสงอาทิตย์ 1 ใบ เพราะงูติดกับดักตาย</p></td><td><p>หากกลุ่มงูน้ำติดกับดักตายบ่อยครั้งอาจส่งผลให้ลดจำนวนลงและทำให้ปูซึ่งเป็นศัตรูพืชเพิ่มจำนวนได้ จึงควรมีการตรวจสอบกับดักสม่ำเสมอ</p></td></tr><tr><td><p>14-15</p></td><td><p>โรคขาแดง/โรคราที่ผิวหนังระบาดในฟาร์มกบนา</p></td><td><p>1. เสียบ่อเลี้ยง 1 พื้นที่2. เสียการ์ดกบนา 1 ใบ</p></td><td><p>เป็นโรคระบาดที่พบได้บ่อยในฟาร์มเลี้ยง สร้างความเสียหายได้มากหากไม่มีการจัดการที่เหมาะสม</p></td></tr></tbody></table></div><div class=\"table-scroll\"><table><tbody><tr><td><p>หมายเลข</p></td><td><p>ชื่อการ์ด</p></td><td><p>ผลที่ได้รับ</p></td><td><p>องค์ความรู้ที่ได้</p></td></tr><tr><td><p>16</p></td><td><p>ปรับปรุงพื้นที่ปศุสัตว์</p></td><td><p>1. ได้บ่อเลี้ยง 1 พื้นที่2. ได้การ์ดสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานอย่างละ 1 ใบ</p></td><td><p>เป็นการเพิ่มพื้นที่อาศัย โดยทำให้พื้นที่เหมาะสมต่อการอยู่อาศัยของสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานมากขึ้น</p></td></tr><tr><td><p>17-18</p></td><td><p>หน่วยงานส่งเสริมการทำฟาร์มเลี้ยง (กบนา/ตะพาบไต้หวัน)</p></td><td><p>1. ได้บ่อเลี้ยง 1 พื้นที่2. ได้การ์ดตะพาบไต้หวัน/การ์ดกบนา 1 ใบ</p></td><td><p>การส่งเสริมอาชีพจากภาครัฐ สร้างรายได้หลักหรือรายได้เสริมแก่ชาวบ้าน</p></td></tr><tr><td><p>19</p></td><td><p>เกษตรอินทรีย์</p></td><td><p>ได้การ์ดสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานอย่างละ 1 ใบ</p></td><td><p>การเกษตรที่เป็นมิตรกับสิ่งแวดล้อม ปลอดภัยต่อสิ่งมีชีวิตและมนุษย์เนื่องจากไม่มีการใช้สารเคมี</p></td></tr><tr><td><p>20-21</p></td><td><p>ปลูกป่า/เฝ้าระวังทำแนวกันไฟ</p></td><td><p>ได้การ์ดสัตว์สะเทินน้ำสะเทินบก หรือ สัตว์เลื้อยคลาน 1 ใบ</p></td><td><p>เป็นการเพิ่มพื้นที่อยู่อาศัย และปกป้องรักษาไม่ให้ถูกทำลาย</p></td></tr><tr><td><p>22</p></td><td><p>เพิ่มตาแหลวในพื้นที่เพาะปลูก</p></td><td><p>ได้การ์ดสัตว์สะเทินน้ำสะเทินบก หรือ สัตว์เลื้อยคลาน 1 ใบ</p></td><td><p>ตาแหลวคือไม้ไผ่สาน มักปักไว้หน้าบ้านหรือใช้ในพิธีแฮกนาของคนภาคเหนือ เป็นสัญลักษณ์ว่าพื้นที่นั้นศักดิ์สิทธิ์ จึงไม่ถูกรบกวนโดยมนุษย์ทำให้ปลอดสารเคมีและมีความอุดมสมบูรณ์ เป็นหนึ่งในวิธีการอนุรักษ์พื้นที่อยู่อาศัย (สำนักส่งเสริมศิลปวัฒนธรรมและล้านนาสร้างสรรค์, 2563)</p></td></tr><tr><td><p>23</p></td><td><p>ช่วยเต่านาข้ามถนน</p></td><td><p>ได้การ์ดเต่านา 1 ใบ</p></td><td><p>มีรายงานเต่าถูกรถทับบ่อยครั้งไม่ใช่แค่เต่านา โดยอาจข้ามถนนเพื่อไปยังพื้นที่ที่เหมาะแก่การอาศัยมากกว่า การพาเต่าข้ามถนนหรือนำไปไว้ในที่ปลอดภัยจะช่วยลดความสูญเสียได้</p></td></tr></tbody></table></div><p>รายละเอียดการ์ดคำถาม</p><div class=\"table-scroll\"><table><tbody><tr><td><p>หมายเลข</p></td><td><p>ชื่อการ์ด</p></td><td><p>ผลที่ได้รับ</p></td><td><p>องค์ความรู้ที่ได้</p></td></tr><tr><td><p>1</p></td><td><p>งูแสงอาทิตย์กินอะไร</p></td><td><p>ตอบถูกได้การ์ดงูแสงอาทิตย์ 1 ใบ</p></td><td><p>ผู้เล่นได้เข้าใจบริการด้านการควบคุม นั่นคือควบคุมประชากรงูชนิดอื่นรวมทั้งงูพิษ</p></td></tr><tr><td><p>2</p></td><td><p>สิ่งมีชีวิตเฝ้าระวังทางชีวภาพ (Bio-sentinel sp.) คืออะไร</p></td><td><p>ตอบถูกได้การ์ดกบหนอง 1 ใบ</p></td><td><p>ผู้เล่นได้เข้าใจความหมายของคำนี้ และรู้ว่ากบหนองเป็นสิ่งมีชีวิตเฝ้าระวังทางชีวภาพ</p></td></tr><tr><td><p>3</p></td><td><p>ยกตัวอย่างปัญหาที่เกิดกับสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลานในหน้าแล้ง</p></td><td><p>ตอบถูกได้การ์ดสัตว์สะเทินน้ำสะเทินบกหรือสัตว์เลื้อยคลาน 1 ใบ</p></td><td><p>ผู้เล่นได้คิดวิเคราะห์และแลกเปลี่ยนปัญหาที่เกิดกับสัตว์กลุ่มนี้ในหน้าแล้ง</p></td></tr><tr><td><p>4</p></td><td><p>ยกตัวอย่างสัตว์เลื้อยคลานที่กินหนูศัตรูพืช</p></td><td><p>ตอบถูกได้การ์ดสัตว์เลื้อยคลาน 1 ใบ</p></td><td><p>ผู้เล่นได้เข้าใจบริการด้านการควบคุม และทราบชนิดงูที่กินหนู คือ งูสิง งูทางมะพร้าว งูเหลือม และงูเห่าไทย</p></td></tr><tr><td><p>5</p></td><td><p>สัตว์สะเทินน้ำสะเทินบกที่คนนำมากิน</p></td><td><p>ตอบถูกได้การ์ดสัตว์สะเทินน้ำสะเทินบก 1 ใบ</p></td><td><p>ผู้เล่นได้เข้าใจบริการด้านแหล่งผลิต ซึ่งคำตอบได้แก่ กบหนอง กบนา อึ่งอ่างบ้าน อึ่งเพ้า</p></td></tr><tr><td><p>6</p></td><td><p>สัตว์เลื้อยคลานที่คนนำมากิน</p></td><td><p>ตอบถูกได้การ์ดสัตว์เลื้อยคลาน 1 ใบ</p></td><td><p>ผู้เล่นได้เข้าใจบริการด้านแหล่งผลิต ซึ่งคำตอบได้แก่ งูสิง งูเห่า เหี้ย ตะพาบไต้หวัน</p></td></tr><tr><td><p>7</p></td><td><p>จงบอกผลกระทบของสารเคมีทางการเกษตรต่อสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลาน</p></td><td><p>ตอบถูก เลือกขโมยการ์ดสัตว์สะเทินน้ำสะเทินบก หรือ สัตว์เลื้อยคลานจากเพื่อนได้ 1 ใบ</p></td><td><p>สารเคมีการเกษตรมีผลต่อสุขภาพและการเจริญของสัตว์ จำนวนประชากร การขาดแคลนที่อยู่อาศัย และอาหาร</p></td></tr><tr><td><p>8</p></td><td><p>ยกตัวอย่างสัตว์สะเทินน้ำสะเทินบกและเลื้อยคลานที่เป็นสัตว์เศรษฐกิจและการเพาะพันธุ์ในฟาร์ม</p></td><td><p>ตอบถูกเลือกขโมยการ์ดสัตว์สะเทินน้ำสะเทินบก หรือ สัตว์เลื้อยคลานจากเพื่อนได้ 1 ใบ</p></td><td><p>ในเกมนี้ ได้แก่ กบนา ตะพาบไต้หวัน ฟาร์มเพาะพันธุ์เป็นบริการด้านแหล่งผลิต</p></td></tr><tr><td><p>9</p></td><td><p>การมีตาแหลวในพื้นที่เกษตรส่งผลต่อสิ่งมีชีวิตในพื้นที่นั้นอย่างไร</p></td><td><p>ตอบถูกการ์ดสัตว์สะเทินน้ำสะเทินบกหรือสัตว์เลื้อยคลานจากเพื่อนได้ 1 ใบ</p></td><td><p>พื้นที่มีตาแหลวถือเป็นพื้นที่ศักดิ์สิทธิ์จึงไม่ถูกรบกวนโดยมนุษย์ ทำให้มีความอุดมสมบูรณ์และปลอดสารเคมี เป็นหนึ่งในวิธีการอนุรักษ์พื้นที่อยู่อาศัย</p></td></tr></tbody></table></div><p>ขั้นตอนการเล่น</p><p>ผู้เล่นทำแบบทดสอบก่อนเล่น</p><p>ผู้คุมเกมอธิบายกติกา</p><p>ผู้เล่นแต่ละคนเลือกแผนภาพที่อยู่อาศัย 3 พื้นที่โดนใช้เข็มหมุดปักบนกลางกระดาน</p><p>ผู้เล่นคนแรกโยนลูกเต๋าและเดินตามช่องบนกระดาน</p><p>ทำตามช่องกระดาน</p><p>หากตกช่องคำถาม ผู้เล่นหยิบการ์ดคำถาม 1 ใบแล้วตอบคำถาม</p><p>หากตกช่องเพาะปลูก ผู้เล่นเลือกแผนภาพพื้นที่เพาะปลูก 1 ใบ วางลงบนพื้นที่เพาะปลูกของตนเอง</p><p>หากตกช่องอนุรักษ์ ผู้เล่นบอกวิธีการอนุรักษ์สัตว์สะเทินน้ำสะเทินบก และ สัตว์เลื้อยคลาน</p><p>หากตกช่อง Event ผู้เล่นหยิบการ์ดเหตุการณ์ 1 ใบ</p><p>หากตกช่องอื่น ๆ ผู้คุมเกมจะสุ่มเหตุการณ์เพิ่มเติม เช่น บอกความรู้เรื่องสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลาน หรือ การบริการระบบนิเวศ เหตุการณ์เพื่อเพิ่มอรรถรสของเกม</p><p>ผู้เล่นคนต่อไปทำการโยนลูกเต๋าและวนซ้ำ เมื่อครบระยะเวลาที่กำหนดจะทำการตัดจบเกม</p><p>ผู้ช่วยคุมเกมสรุปองค์ความรู้ และ ผู้เล่นช่วยกันเขียน</p><p>ผู้เล่นทำแบบทดสอบหลังเล่น และ แบบประเมิน</p>", "learning": "", "debrief": "<p>ผู้คุมเกมหรือผู้ช่วยคุมเกมอธิบายถึงความสำคัญของสัตว์สะเทินน้ำสะเทินบกและสัตว์เลื้อยคลาน บริการระบบนิเวศ และ ความหลากหลายทางชีวภาพ ภายในพื้นที่ ซึ่งทำให้ก่อประโยชน์ในหลาย ๆ ด้าน และพูดถึงประโยชน์ของสัตว์สะเทินน้ำสะเทินบกสัตว์เลื้อยคลาน ไม่ว่าจะเป็น บริการระบบนิเวศที่มนุษย์ได้รับจากสัตว์สะเทินน้ำสะเทินบก ความสัมพันธ์ของสิ่งมีชีวิตในระบบ เป็นต้น อีกทั้งยังสามารถสรุปในแง่ของการอนุรักษ์ไม่ว่าจะเป็น วิธีการอนุรักษ์ และ ประโยชน์ของการอนุรักษ์สัตว์สะเทินน้ำสะเทินบก</p>", "gallery": ""}, "gallery": [{"src": "assets/04-image41.png", "section": "materials"}, {"src": "assets/04-image42.png", "section": "materials"}, {"src": "assets/04-image43.png", "section": "materials"}, {"src": "assets/04-image44.png", "section": "materials"}, {"src": "assets/04-image45.png", "section": "materials"}, {"src": "assets/04-image46.png", "section": "materials"}, {"src": "assets/04-image47.png", "section": "materials"}, {"src": "assets/04-image48.png", "section": "materials"}, {"src": "assets/04-image49.png", "section": "materials"}, {"src": "assets/04-image50.png", "section": "materials"}, {"src": "assets/04-image51.png", "section": "materials"}, {"src": "assets/04-image52.png", "section": "materials"}, {"src": "assets/04-image53.png", "section": "play"}, {"src": "assets/04-image54.png", "section": "play"}, {"src": "assets/04-image55.png", "section": "play"}, {"src": "assets/04-image56.png", "section": "play"}, {"src": "assets/04-image57.png", "section": "play"}, {"src": "assets/04-image58.png", "section": "play"}, {"src": "assets/04-image59.png", "section": "play"}, {"src": "assets/04-image60.png", "section": "play"}, {"src": "assets/04-image61.png", "section": "play"}, {"src": "assets/04-image62.png", "section": "play"}, {"src": "assets/04-image63.png", "section": "gallery"}], "images": ["assets/04-image43.png", "assets/04-image54.png", "assets/04-image44.png", "assets/04-image55.png", "assets/04-image45.png", "assets/04-image56.png", "assets/04-image46.png", "assets/04-image57.png", "assets/04-image47.png", "assets/04-image42.png", "assets/04-image63.png", "assets/04-image53.png", "assets/04-image58.png", "assets/04-image48.png", "assets/04-image59.png", "assets/04-image49.png", "assets/04-image60.png", "assets/04-image50.png", "assets/04-image61.png", "assets/04-image51.png", "assets/04-image41.png", "assets/04-image62.png", "assets/04-image52.png"]}, {"id": "05", "title": "Farmer versus Climate Change", "category": "agriculture", "cover": "assets/cover-05.webp", "players": "4–5 players", "time": "5 rounds", "intro": "Adapt a farm through heavy rain, drought and changing agricultural conditions.", "research": "Gaming and simulation for learning about climate adaptation in agricultural ecosystems in Nan Province.", "overview": "Farmers face drought, heavy rainfall and other climate pressures, while land clearing can contribute to flooding and landslides. This game explores the relationship between agriculture and climate change and helps participants exchange adaptation strategies.", "materials": ["Agricultural activity, fertilizer/pesticide, profit-focused and adaptation cards; reservoir and firebreak pieces.", "A 61.5 × 76 cm board with 5.1 × 5 cm spaces, play money, tokens, coloured labels, buttons and containers.", "Price sheets, recording forms, pre/post tests, evaluation forms and a manual."], "play": ["Form groups of 4–5 players, complete a pretest, distribute starting resources and explain the rules.", "Place tokens on farmland. Choose agricultural activities, fertilizers, pesticides and adaptation options, following the source’s purchase limits. Place the cards and record decisions.", "The facilitator tracks collective greenhouse-gas emissions. In this simulation, totals of 250 and 500 units reduce crop sale prices by 1,000 and 2,000 baht per rai respectively; wildfire reduces affected crop prices to zero.", "Resolve five rounds: normal conditions, heavy rain, drought, increased pests and weeds, then drought. Calculate crop income at the end of each round.", "Before the next round, choose whether to incorporate crop residues into the soil or burn them. Complete five rounds, or adjust to the session, then debrief and take the posttest."], "debrief": "Use questions and shared responses to discuss climate causes and impacts, adaptation, agriculture–climate interactions, market shortages and surpluses, chemical contamination and bio-sentinel species.", "file": "documents/05_Farmer versus Climate change.docx", "titleTh": "Farmer versus Climate change", "introTh": "ปรับตัวรับฝนหนัก ภัยแล้ง และความเปลี่ยนแปลงในพื้นที่เกษตร", "researchTh": "เกมและสถานการณ์จำลองเพื่อการเรียนรู้เรื่องการปรับตัวต่อการเปลี่ยนแปลงสภาพภูมิอากาศในระบบนิเวศเกษตร จังหวัดน่าน", "sourceTh": "งานวิจัย", "tags": [{"th": "การเปลี่ยนแปลงสภาพภูมิอากาศ", "en": "Climate Change"}, {"th": "การปรับตัว", "en": "Adaptation"}, {"th": "ระบบนิเวศเกษตร", "en": "Agroecosystem"}, {"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "การจัดการความเสี่ยงภัยแล้งและน้ำท่วม", "en": "Drought and Flood Risk Management"}, {"th": "จังหวัดน่าน", "en": "Nan Province"}], "sectionsTh": {"overview": "<p>ในปัจจุบันเกษตรกรประสบปัญหาทางการเกษตรที่เกิดจากการเปลี่ยนแปลงสภาพภูมิ ไม่ว่าจะเป็น ภัยแล้ง ฝนตกหนัก เป็นต้น ทั้งนี้เกษตรกรยังมีการทำลายพื้นที่ธรรมชาติเพื่อทำการเกษตร นำไปสู่ปัญหาต่าง ๆ ไม่ว่าจะเป็น ปัญหาน้ำท่วม หน้าดินถล่ม และ อื่น ๆ เกษตรกรจึงจำเป็นต้องปรับตัวต่อสถานการณ์ที่เกิดขึ้น เกม Famer versus Climate change เป็นตัวกลางในการเรียนรู้การปรับตัวต่อสภาพภูมิอากาศที่เปลี่ยนไป ช่วยสร้างความเข้าใจความสัมพันธ์ระหว่างการเกษตรกับการเปลี่ยนแปลงสภาพภูมิอากาศ</p>", "materials": "<p>การ์ด</p><p>การ์ดกิจกรรมทางการเกษตร ขนาด 5.2 x 5.2 เซนติเมตร</p><p>การ์ดปุ๋ยและยากำจัด ขนาด 5.2 x 7.5 เซนติเมคร</p><p>การ์ดรวยไม่สนโลก ขนาด 5.2 x 7.5 เซนติเมตร</p><p>การ์ดปรับตัว ขนาด 5.2 x 7.5 เซนติเมตร</p><p>บ่อกักเก็บน้ำและแนวกันไฟ ขนาด 5.2 x 5.2 เซนติเมตร</p><p>เงินปลอม 4.2 x 9.2 เซนติเมตร</p><p>บอร์ด ขนาด 61.5 x 76.0 เซนติเมตร มีช่องย่อยขนาด 5.1 x 5.0 เซนติเมตร</p><p>ตัวหมาก</p><p>ป้ายสีขนาด 1.5 x 1.5 เซนติเมตร</p><p>กระดุม</p><p>กล่องพลาสติก</p><p>ใบเสนอราคา</p><p>แบบบันทึกข้อมูล</p><p>แบบทดสอบความรู้ก่อนและหลังเล่น</p><p>แบบประเมิน</p><p>คู่มือการเล่น</p>", "play": "<p>บรรยาย + สรุปขั้นตอน</p><p>เกม Famer versus Climate change เป็นเกมที่ออกแบบสำหรับผู้เล่น 5 คน โดยจะนั่งล้อมรอบบอร์ด โดยเว้นที่สำหรับผู้ส่วยคุมเกมในกรณีที่มีหลายกลุ่ม</p><p>องค์ประกอบของบอร์ด แบ่งออกเป็น ช่องสีเขียว แทน พื้นที่ป่า, ช่องสีเหลือ แทน พื้นที่ชุมชนสำหรับการเกษตร, ช่องสีน้ำเงิน แทน พื้นที่แม่น้ำ, ลูกศรสีขาว แทน ลูกศรแสดงต้นน้ำเพื่อแสดงการไหลของน้ำ</p><p>องค์ประกอบการ์ดกิจกรรมทางการเกษตร</p><p>องค์ประกอบการ์ดปุ๋ยและยากำจัด</p><p>องค์ประกอบการ์ดรวยไม่สนโลก</p><p>องค์ประกอบการ์ดปรับตัว</p><p>การจัดอุปกรณ์เริ่มต้นให้ผู้เล่น</p><div class=\"table-scroll\"><table><tbody><tr><td><p>ผู้เลนคนที่</p></td><td><p>จำนวนเงิน (บาท)</p></td><td><p>สีของตัวหมาก</p></td><td><p>จำนวนหมาก (ตัว)</p></td></tr><tr><td><p>1</p></td><td><p>5,000</p></td><td><p>ส้ม</p></td><td><p>5</p></td></tr><tr><td><p>2</p></td><td><p>5,000</p></td><td><p>ขาว</p></td><td><p>5</p></td></tr><tr><td><p>3</p></td><td><p>4,000</p></td><td><p>ฟ้า</p></td><td><p>4</p></td></tr><tr><td><p>4</p></td><td><p>3,000</p></td><td><p>ชมพู</p></td><td><p>3</p></td></tr><tr><td><p>5</p></td><td><p>3,000</p></td><td><p>เขียว</p></td><td><p>3</p></td></tr></tbody></table></div><p>สัญลักษณ์ป้ายสี</p><div class=\"table-scroll\"><table><tbody><tr><td><p>ป้ายสี</p></td><td><p>การ์ด</p></td></tr><tr><td><p>สีเทา</p></td><td><p>การ์ดปุ๋ยอินทรีย์</p></td></tr><tr><td><p>สีดำ</p></td><td><p>การ์ดปุ๋ยเคมี</p></td></tr><tr><td><p>สีส้ม</p></td><td><p>การ์ดยาฆ่าหญ้า</p></td></tr><tr><td><p>สีน้ำเงิน</p></td><td><p>การ์ดยาฆ่าแมลง</p></td></tr><tr><td><p>สีเหลือง</p></td><td><p>การ์ดการเผาเศษวัสดุทางการเกษตร</p></td></tr><tr><td><p>สีฟ้า</p></td><td><p>การ์ดบุกรุกพื้นที่ป่า</p></td></tr><tr><td><p>สีเขียว</p></td><td><p>การ์ดปรับปรุงพันธ์พืช</p></td></tr><tr><td><p>สีแดง</p></td><td><p>การ์ดการคลุมดิน</p></td></tr><tr><td><p>สีชมพู</p></td><td><p>การ์ดการขยายพื้นที่เพาะปลูก</p></td></tr><tr><td><p>สีม่วง</p></td><td><p>การ์ดการทะนุบำรุงฟาร์มปศุสัตว์</p></td></tr><tr><td><p>สีไข่</p></td><td><p>การ์ดการไถกลบ</p></td></tr></tbody></table></div><p>ขั้นตอนการใช้เกม</p><p>ผู้เล่นแบ่งกลุ่มกลุ่มละ 4–5 คน</p><p>ผู้เล่นทำแบบทดสอบก่อนเล่น</p><p>ผู้ช่วยคุมเกมนำอุปกรณ์เริ่มต้นแจกให้ผู้เล่นแต่ละคน</p><p>ผู้นำเกมแนะนำและอธิบายกติกาเกม</p><p>ผู้เล่นนำหมากวางไว้บนพื้นที่ทางการเกษตรในบอร์ด และ บันทึกข้อมูลลงในใบบันทึกข้อมูล</p><p>ผู้เล่นตัดสินใจเลือกซื้อกิจกรรมทางการเกษตร การ์ดปุ๋ยและยากำจัด การรวยไม่สนโลก และ การ์ดการปรับตัว โดยจะซื้อแต่ละชนิดได้มากที่สุดตามจำ</p><p>ผู้เล่นวางการ์ดลงบนพื้นที่ของตนเอง และ จดข้อมูล</p><p>ผู้นำเกมคำนวณปริมาณก๊าซเรือนกระจกทีปล่อยออกมา หากก๊าซเรือนกระจกที่ทุกกลุ่มปล่อยสะสมรวมกันได้ 250 หน่วย และ 500 หน่วยจะส่งผลให้ราคาขายผลิตภัณฑ์ทางการเกษตรลดลง 1,000 และ 2,000 บาทต่อไร่ ตามลำดับ หากเกิดเหตุไฟป่าราคาผลผลิตจะเท่ากับ 0 บาท โดยแต่ละรอบผู้นำเกมจะประกาศเหตุการณ์ดังตาราง</p><div class=\"table-scroll\"><table><tbody><tr><td><p>รอบการเล่น</p></td><td><p>เหตุการณ์</p></td></tr><tr><td><p>1</p></td><td><p>เหตุการณ์ปกติ</p></td></tr><tr><td><p>2</p></td><td><p>ฝนตกหนัก</p></td></tr><tr><td><p>3</p></td><td><p>ภัยแล้ง</p></td></tr><tr><td><p>4</p></td><td><p>แมลงระบาดและวัชพืชเพิ่มขึ้น</p></td></tr><tr><td><p>5</p></td><td><p>ภัยแล้ง</p></td></tr></tbody></table></div><p>ผู้เล่นคำนวณเงินจากการขายผลผลิตและสิ้นสุดรอบนั้น ๆ</p><p>ในการเริ่มรอบใหม่ผู้เล่นแต่ละคนจะต้องเตรียมพื้นที่ทางการเกษตรของตน โดยเลือกระหว่า การไถกลบ หรือ การเผา และทำซ้ำขั้นตอนดั่งกล่าว</p><p>เล่นจนครบ 5 รอบ หรือตามความเหมาะสม</p><p>ผู้นำเกมสรุปหลังเล่นเกม และ ผู้เล่นทำแบบทดสอบหลังเล่นเกม</p>", "learning": "", "debrief": "<p>ผู้นำเกมกล่าวสรุปความรู้ในประเด็นต่าง ๆ ได้แก่ ความหมาย สาเหตุ และ ผลกระทบของการเปลี่ยนแปลงสภาพภูมิอากาศ วิธีการปรับตัวต่อการเปลี่ยนแปลง สภาพภูมิอากาศ ปฏิสัมพันธ์ระหว่างเกษตรกรรมและการเปลี่ยนแปลงสภาพ ภูมิอากาศ สินค้าขาดตลาด สินค้าล้นตลาด การปนเปื้อนสารเคมีในดินและแหล่งน้ำ และสปีชีส์เฝ้าระวัง (Bio-sentinel species) โดยใช้ลักษณะการถามคำถามแล้วให้ผู้ เล่นช่วยตอบ นอกจากนี้ยังได้พูดคุยแลกเปลี่ยนความคิดเห็นเกี่ยวกับวิธีการปรับตัว ต่อการเปลี่ยนแปลงสภาพภูมิอากาศ</p>", "gallery": ""}, "gallery": [{"src": "assets/05-image64.png", "section": "materials"}, {"src": "assets/05-image65.png", "section": "materials"}, {"src": "assets/05-image66.png", "section": "materials"}, {"src": "assets/05-image67.png", "section": "materials"}, {"src": "assets/05-image68.png", "section": "materials"}, {"src": "assets/05-image69.png", "section": "materials"}, {"src": "assets/05-image68.png", "section": "materials"}, {"src": "assets/05-image70.png", "section": "materials"}, {"src": "assets/05-image72.png", "section": "materials"}, {"src": "assets/05-image73.png", "section": "materials"}, {"src": "assets/05-image74.png", "section": "materials"}, {"src": "assets/05-image75.png", "section": "materials"}, {"src": "assets/05-image76.png", "section": "materials"}, {"src": "assets/05-image77.png", "section": "materials"}, {"src": "assets/05-image78.png", "section": "materials"}, {"src": "assets/05-image79.png", "section": "materials"}, {"src": "assets/05-image80.png", "section": "play"}, {"src": "assets/05-image81.png", "section": "play"}, {"src": "assets/05-image82.png", "section": "play"}, {"src": "assets/05-image83.png", "section": "play"}, {"src": "assets/05-image84.png", "section": "gallery"}], "images": ["assets/05-image64.png", "assets/05-image75.png", "assets/05-image65.png", "assets/05-image76.png", "assets/05-image66.png", "assets/05-image77.png", "assets/05-image67.png", "assets/05-image80.png", "assets/05-image78.png", "assets/05-image68.png", "assets/05-image74.png", "assets/05-image79.png", "assets/05-image81.png", "assets/05-image69.png", "assets/05-image82.png", "assets/05-image70.png", "assets/05-image83.png", "assets/05-image84.png", "assets/05-image72.png", "assets/05-image73.png"]}, {"id": "06", "title": "Community Forest no CanCel", "category": "forest", "cover": "assets/cover-06.webp", "players": "2+ equal groups", "time": "Up to 7 rounds", "intro": "Work together to keep a community forest productive, resilient and valuable.", "research": "Gaming and simulation for learning about community forest ecosystem services and sustainable management.", "overview": "CF no CC was developed particularly for young people in Nan. It explores provisioning, regulating and cultural services while practising collective decisions, planning and sustainable resource management under climate variability.", "materials": ["Tree, product, building, activity and character cards, with their conditions.", "A 54 × 36 cm board, coloured paper, play banknotes and certificates.", "Event descriptions, pre/post tests and recording sheets for harvesting, activity planning and income."], "play": ["Prepare a table and presentation screen. Randomly place five tree cards and the initial forest-product cards. Divide participants into at least two equally sized groups with one facilitator per table.", "Allow ten minutes for the pretest. Explain forest ecosystem services, then guide the first round. Distribute character cards, money, paper clips and coloured paper.", "Players choose to collect two forest-product cards or take one learning card. Record the choice. Present five activity cards and let players discuss costs, participation and impacts.", "Players can exchange learning and products for a business card according to its conditions. Pay activity costs and place buildings where required.", "Sell products, operate businesses and receive activity income; activities pay in the following round. Announce an event and replenish products according to their conditions.", "Play for up to seven rounds or the available time. Compare forests and mission completion, then allow ten minutes for the posttest and satisfaction assessment."], "debrief": "Reflect on resource choices, their consequences and the three groups of forest ecosystem services. Compare cooperation across groups and discuss sustainable management under climate change. Collect feedback for improving the activity.", "file": "documents/06_Community Forest no CanCel (CF no CC).docx", "titleTh": "Community Forest no CanCel", "introTh": "ร่วมตัดสินใจเพื่อป่าชุมชนที่ให้ประโยชน์และคงอยู่อย่างยั่งยืน", "researchTh": "เกมและสถานการณ์จ าลองเพื่อการเรียนรู้เกี่ยวกับบริการของระบบนิเวศป่าชุมชนและการจัดการอย่างยั่งยืน", "sourceTh": "งานวิจัย", "tags": [{"th": "ป่าชุมชน", "en": "Community Forest"}, {"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "การจัดการทรัพยากรอย่างยั่งยืน", "en": "Sustainable Resource Management"}, {"th": "การเรียนรู้ของเยาวชน", "en": "Youth Learning"}, {"th": "การตัดสินใจร่วม", "en": "Collective Decision-Making"}, {"th": "จังหวัดน่าน", "en": "Nan Province"}], "sectionsTh": {"overview": "<p>โครงการนี้มุ่งพัฒนาสื่อการเรียนรู้ในรูปแบบเกมและสถานการณ์จำลอง (Gaming and Simulation) เพื่อส่งเสริมความรู้ความเข้าใจเกี่ยวกับบริการของระบบนิเวศป่าชุมชน (Community Forest Ecosystem Services) และแนวทางการจัดการทรัพยากรธรรมชาติอย่างยั่งยืน โดยมุ่งเน้นกลุ่มเป้าหมายเป็นเยาวชนในพื้นที่จังหวัดน่าน ซึ่งเป็นพื้นที่ที่มีทรัพยากรป่าชุมชนสำคัญและเผชิญความท้าทายด้านการอนุรักษ์ทรัพยากร ธรรมชาติโดยชื่อเกมว่าCommunity Forest no CanCel (CF no CC) เกมนี้มีเป้าหมาย เพื่อให้ผู้เล่นได้เรียนรู้เกี่ยวกับบริการของระบบนิเวศป่าชุมชนทั้ง 3 ด้าน ได้แก่ บริการด้านการเป็นแหล่งผลิต (Provisioning Services) บริการด้านการควบคุม (Regulating Services) และบริการด้านวัฒนธรรม (Cultural Services) ควบคู่กับการฝึกกระบวนการตัดสินใจ การวางแผน และการทำงานร่วมกันในการจัดการป่าชุมชน ภายใต้สถานการณ์ความแปรปรวนของสภาพภูมิอากาศและข้อจำกัดด้านทรัพยากร เพื่อสร้างความเข้าใจในการจัดการทรัพยากรธรรมชาติอย่างสมดุลและยั่งยืน</p>", "materials": "<p>การ์ดต้นไม้</p><p>การ์ดผลผลิต</p><p>เงื่อนไขการใช้งานของการ์ดผลผลิต</p><p>การ์ดสิ่งปลูกสร้าง</p><p>การ์ดกิจกรรม</p><p>เงื่อนไขการใช้งานของการ์ดกิจกรรม</p><p>การ์ดตัวละคร</p><p>เงื่อนไขการใช้งานของการ์ดตัวละคร</p><p>บอร์ด(กระดานขนาด 54 × 36 เซนติเมตร)</p><p>กระดาษสี</p><p>(ธนบัตร)</p><p>(ใบประกาศ)</p><p>รายละเอียดเหตุการณ์</p><p>แบบทดสอบก่อนและหลังเล่นเกม</p><p>(ก่อน)</p><p>(หลัง)</p><p>ใบบันทึกผลการเล่นเกม</p><p>บันทึกข้อมูล 3 ครั้ง  1) บันทึกข้อมูลการเก็บผลผลิต</p><p>2) บันทึกหลังการวางแผนการทำกิจกรรม</p><p>3) บันทึกช่วงที่ได้รับเงินจากกิจกรรมหรือผลผลิต</p>", "play": "<p>1. ให้ผู้นำเกมเตรียมสถานที่ อุปกรณ์ โต๊ะให้เหมาะสมโดยให้มีจอฉายสไลด์สำหรับให้ความรู้และอธิบายวิธีการเล่น และการจัดโต๊ะให้สามารถวางอุปกรณ์ทั้งหมดได้เพียงพอและผู้เรียนสามารถเข้าเล่นเกมได้สะดวก</p><p>2. ผู้นำเกมวางการ์ดต้นไม้ 5 ต้นและการ์ดผลผลิตลงในป่าชุมชนอย่างละ 2 ชนิดลงในพื้นที่กระดานป่าชุมชนแบบสุ่ม</p><p>3. แบ่งผู้เล่นเป็น 2 กลุ่มขึ้นไปโดยมีจำนวนสมาชิกกลุ่มละเท่า ๆ กันและมีผู้นำเกมประจำอยู่ที่โต๊ะละ 1 คน</p><p>4. ผู้นำเกมแจกแบบทดสอบก่อนเล่นเกมให้ทำและจับเวลา 10 นาที</p><p>5. ผู้นำเกมเริ่มนำเข้าสู่เนื้อหาเกี่ยวกับความหมายของบริการระบบนิเวศป่าชุมชนประโยชน์ของป่าชุมชน ปัญหาในปัจจุบันและวิธีการจัดการป่าชุมชนอย่างยั่งยืน</p><p>6. จากนั้นให้ผู้เล่นอธิบายวิธีการเล่นเกมจากสไลด์ (ภาคผนวกที่ 1) พร้อมกับเล่นเกมไปพร้อมกันในรอบแรก</p><p>7. ผู้เล่นจะได้การ์ดตัวละคร 1 ใบ เงินจำนวนหนึ่ง คลิปหนีบกระดาษและกระดาสี (หากสมาชิกกลุ่มในเกมมีมากกว่า 4 คน ให้เล่นด้วยกันได้)</p><p>8. ผู้เล่นเริ่มพาเล่นเกมในรอบแรก โดยให้ผู้เล่นเริ่มตัดสินใจว่าอยากเก็บการ์ดของป่าหรือเลือกการ์ดเรียนรู้ ถ้าหากเลือกเก็บของป่าจะสามารถเลือกหยิบการ์ดออกจากกระดานป่าชุมชนจำนวน 2 ใบ แต่ถ้าเลือกการ์ดเรียนรู้จะได้รับการเรียนรู้ 1 ใบ และยังได้รับเกร็ดความรู้เล็ก ๆ จากของป่าในป่าชุมชน</p><p>9. ผู้นำเกมทำการบันทึกข้อมูลการเก็บของป่าหรือการ์ดเรียนรู้ลงในใบบันทึกผลการเล่นเกม</p><p>10. ผู้นำเกมจะนำการ์ดกิจกรรมที่เตรียมไว้ขึ้นมา 5 ใบ ให้ผู้เล่นทำการจัดสินใจเพราะแต่ละกิจกรรมต้องใช้เงิน จำนวนคนและผลกระทบที่แตกต่างกัน</p><p>11. ผู้เล่นทำการคุยกันและวางคลิปหนีบกระดาษเพื่อเป็นการยืนยันกับผู้นำเกมว่าผู้เล่นร่วมกันทำกิจกรรมนี้</p><p>12. ผู้เล่นสามารถทำธุรกิจได้โดยการนำการเรียนรู้และของป่าตามเงื่อนไขมาแลกกับการ์ดธุรกิจ 1 ใบ ผู้เล่นถึงจะได้รับเงินจากการทำธุรกิจ การ์ดธุรกิจจะอยู่กับผู้เล่นตลอด ในครั้งที่ 2 ผู้เล่นใช้เพียงแค่ของป่าตามเงื่อนไขอย่างเดียวก็ได้เงินจากการทำธุรกิจแล้ว</p><p>13. หลังจากนั้นให้ผู้เล่นจ่ายเงินค่ากิจกรรมให้กับผู้นำเกมและผู้นำเกม และผู้นำเกมจะบันทึกข้อมูลลงในใบบันทึกผลการเล่นเกม</p><p>14. ผู้นำเกมตรวจสอบความถูกต้องและนำกระดาษสีทีเป็นตัวแทนของตัวละครนั้น ๆ มาวางบนการ์ดและวางไว้ใกล้ ๆ กับป่าชุมชน</p><p>15. การ์ดกิจกรรมบางใบจำเป็นต้องใช้พื้นที่ในกระดานป่าชุมชนด้วย ถ้ามีให้ผู้นำเกมวางการ์ดสิ่งปลูกสร้างไปวางในพื้นที่และเก็บใบใหญ่ที่วางกระดาษสีไว้กับตัวผู้เล่นคนไหนก็ได้</p><p>16. ต่อมาผู้เล่นสามารถเลือกขายของป่า เลือกทำธุรกิจและรับเงินจากการทำกิจกรรมได้(การขายของป่าและการทำธุรกิจสามารถทำแล้วได้เงินในรอบเดียวกันแต่กิจกรรมจะได้รับเงินในรอบถัดไป)</p><p>17. ผู้นำเกมทำการตรวจสอบความถูกต้องและบันทึกผลลงในใบบันทึกผลการเล่นเกม</p><p>18. ผู้นำเกมทำการประกาศเหตุการณ์ที่แสดงออกจากจอฉายสไลด์และมีผลกับป่าชุมชนทันที</p><p>19. ผู้เล่นทำการเพิ่มผลผลิตกลับเข้าไปในป่าชุมชนอย่างละ 2 ชนิด ตามเงื่อนไขของของป่าชนิดนั้น ๆ ก่อนเล่นรอบที่ 2</p><p>20. ผู้เล่นกลุ่มไหนที่สามารถเล่นและทำภารกิจสำเร็จครบก่อบ 7 รอบหรือก่อนเวลาหมดจะเป็นผู้ชนะ</p><p>21. ผู้นำเกมทำการสรุปสั้น ๆ ของบริการระบบนิเวศป่าชุมชน กิจกรรมในการจัดการป่าชุมชน และเปรียบเทียบความแตกต่างของป่าชุมชนในแต่ละกลุ่ม</p><p>22. ผู้นำเกมให้ผู้เล่นทำแบบสดสอบหลังเล่นเกมและประเมินความพึงพอใจเป็นเวลา 10นาที</p><p>คู่มือการเล่นเกม</p>", "learning": "", "debrief": "<p>หลังจากเล่นเกม จะมีการพูดคุยสรุปและแลกเปลี่ยนความคิดเห็นร่วมกัน (Debriefing) เพื่อให้ผู้เล่นได้สะท้อนสิ่งที่ได้เรียนรู้จากเกม เช่น การตัดสินใจ การจัดการทรัพยากร และผลที่เกิดขึ้นจากการเลือกทำกิจกรรมต่าง ๆ ในเกม ผู้เล่นจะได้ร่วมกันพูดคุยถึงความสำคัญของบริการของระบบนิเวศป่าชุมชนทั้ง 3 ด้าน บทบาทของการทำงานร่วมกันของคนในชุมชน รวมถึงแนวทางการดูแลและจัดการทรัพยากรธรรมชาติให้เกิดความยั่งยืนภายใต้สถานการณ์การเปลี่ยนแปลงสภาพภูมิอากาศ นอกจากนี้ ยังมีการประเมินหลังการเล่นเกมเพื่อดูความรู้ ความเข้าใจ และรับข้อเสนอแนะเพื่อนำไปพัฒนากิจกรรมต่อไป</p>", "gallery": ""}, "gallery": [{"src": "assets/06-image85.png", "section": "materials"}, {"src": "assets/06-image86.png", "section": "materials"}, {"src": "assets/06-image87.png", "section": "materials"}, {"src": "assets/06-image88.png", "section": "materials"}, {"src": "assets/06-image89.png", "section": "materials"}, {"src": "assets/06-image90.png", "section": "materials"}, {"src": "assets/06-image91.png", "section": "materials"}, {"src": "assets/06-image92.png", "section": "materials"}, {"src": "assets/06-image93.png", "section": "materials"}, {"src": "assets/06-image94.png", "section": "materials"}, {"src": "assets/06-image95.png", "section": "materials"}, {"src": "assets/06-image96.png", "section": "materials"}, {"src": "assets/06-image97.png", "section": "materials"}, {"src": "assets/06-image98.png", "section": "materials"}, {"src": "assets/06-image99.png", "section": "materials"}, {"src": "assets/06-image100.png", "section": "materials"}, {"src": "assets/06-image101.png", "section": "materials"}, {"src": "assets/06-image102.png", "section": "materials"}, {"src": "assets/06-image103.png", "section": "materials"}, {"src": "assets/06-image104.png", "section": "materials"}, {"src": "assets/06-image105.png", "section": "materials"}, {"src": "assets/06-image106.png", "section": "materials"}, {"src": "assets/06-image107.png", "section": "materials"}, {"src": "assets/06-image108.png", "section": "materials"}, {"src": "assets/06-image109.png", "section": "materials"}, {"src": "assets/06-image110.png", "section": "play"}, {"src": "assets/06-image111.png", "section": "gallery"}, {"src": "assets/06-image112.png", "section": "gallery"}, {"src": "assets/06-image113.png", "section": "gallery"}, {"src": "assets/06-image114.png", "section": "gallery"}], "images": ["assets/06-image97.png", "assets/06-image87.png", "assets/06-image108.png", "assets/06-image98.png", "assets/06-image88.png", "assets/06-image109.png", "assets/06-image99.png", "assets/06-image110.png", "assets/06-image89.png", "assets/06-image100.png", "assets/06-image90.png", "assets/06-image111.png", "assets/06-image101.png", "assets/06-image96.png", "assets/06-image91.png", "assets/06-image112.png", "assets/06-image86.png", "assets/06-image107.png", "assets/06-image102.png", "assets/06-image92.png", "assets/06-image113.png", "assets/06-image103.png", "assets/06-image93.png", "assets/06-image114.png", "assets/06-image104.png", "assets/06-image94.png", "assets/06-image105.png", "assets/06-image95.png", "assets/06-image85.png", "assets/06-image106.png"]}, {"id": "07", "title": "Diversity at Lai Nan", "category": "forest", "cover": "assets/cover-07.webp", "players": "Not specified", "time": "Not specified", "intro": "Meet local trees, birds, insects and fungi—and connect them into a food web.", "research": "The research-title field is blank in the supplied document.", "overview": "Research in community forests at Lai Nan, Wiang Sa District, Nan, found high biological diversity. This card-based model uses those findings to help local people recognise and learn about their own natural resources.", "materials": ["Resource cards representing trees, birds, insects and fungi.", "Forest-abundance level cards, question cards and a game manual."], "play": ["Give each player five resource cards and begin with a level-one forest. Track how many resource cards have been played.", "Choose the first player and continue to the right. Play one resource or tree card at a time, read its name and ability, apply the effect and calculate points.", "Use the requirements printed on each card. Forest levels represent different capacities to support organisms. Moving from level one to two requires twenty resource cards; moving from two to three requires forty.", "Explore questions about trees, birds, insects, mushrooms and community forests. Card symbols explain organism size, diet and ecological roles. The source does not specify group size or duration."], "debrief": "Ask participants what they learned and which organisms interested them. Draw arrows between familiar organisms to create a food web, then discuss producers, consumers, decomposers and the benefits people receive from forests.", "file": "documents/07_หลากหลาย ณ ไหลน่าน.docx", "titleTh": "หลากหลาย ณ ไหลน่าน", "introTh": "รู้จักต้นไม้ นก แมลง และเห็ดในท้องถิ่น แล้วเชื่อมโยงเป็นสายใยอาหาร", "researchTh": "ไม่ได้ระบุชื่อเรื่องในเอกสารต้นฉบับ", "sourceTh": "งานวิจัย", "tags": [{"th": "ความหลากหลายทางชีวภาพ", "en": "Biodiversity"}, {"th": "ป่าชุมชน", "en": "Community Forest"}, {"th": "ทรัพยากรธรรมชาติท้องถิ่น", "en": "Local Natural Resources"}, {"th": "สายใยอาหาร", "en": "Food Web"}, {"th": "การเรียนรู้ของชุมชน", "en": "Community Learning"}], "sectionsTh": {"overview": "<p>จากการศึกษาวิจัยเกี่ยวกับความหลากหลายทางชีวภาพของสิ่งมีชีวิตในป่าชุมชน ณ ตำบลไหลน่าน อำเภอเวียงสา จังหวัดน่าน พบว่ามีความหลากหลายทางชีวภาพสูง ผู้วิจัยจึงได้นำข้อมูลความหลากหลายทางชีวภาพเหล่านี้ สร้างเป็นแบบจำลอง นั้นคือเกม หลากหลาย ณ ไหลน่าน เพื่อเป็นเครื่องมือในการเรียนรู้ทรัพยากรธรรมชาติที่พบได้ในป่าชุมชน เพื่อให้คนชุมชนได้รู้จักทรัพยากรธรรมชาติในท้องถิ่นของตน</p>", "materials": "<p>การ์ด</p><p>การ์ดทรัพยากร</p><p>การ์ดแสดงความอุดมสมบูรณ์ของป่า</p><p>การ์ดคำถาม</p><p>คู่มือเกม</p>", "play": "<p>คำอธิบายเกม</p><p>การ์ดระดับความอุดมสมบูรณ์ของป่า</p><p>แบ่งออกเป็น 3 ระดับนั้นคือ 1, 2 และ 3 แต่ละระดับความอุดมสมบูรณ์มีความสามารถในการรองรับสิ่งมีชีวิตแตกต่างกัน เมื่อระดับสูงขึ้นจะรองรับสิ่งมีชีวิตได้มากกว่า</p><p>1 หมายถึงระดับความอุดมสมบูรณ์ของป่า</p><p>⭐️ หมายถึง ป่าชุมชนระดับ 1</p><p>⭐️⭐️ หมายถึง ป่าชุมชนระดับ 2</p><p>⭐️⭐️⭐️ หมายถึง ป่าชุมชนระดับ 3</p><p>2 หมายถึง ประเภททรัพยากรที่สามารถลงได้</p><p>3 หมายถึง จำนวนการ์ดทรัพยากรที่ใช้ในการเปลี่ยนระดับป่า</p><p>การ์ดคำถาม</p><p>คือการคำถามเพิ่มเติมเกี่ยวกับทรัพยากรณ์ธรรมชาติ แบ่งออกเป็น 5 หมวดได้แก่ ต้นไม้ นก แมลง เห็ด และ ป่าชุมชน</p><p>การ์ดทรัพยากรณ์</p><p>แบ่งเป็นสิ่งมีชีวิต 4 หมวดได้แก่ ต้นไม้ นก แมลง และ เห็ด การ์ดแต่ละใบมีคุณสมบัติและความสามารถแตกต่างกัน โดยต้นไม้เป็นตัวแทนผู้ผลิต นกและแมลงเป็นตัวแทนผู้บริโภค และ เห็ดเป็นตัวแทนผู้ย่อยสลาย คุณสมบัติการ์ดแต่ละใบจะมีรายละเอียดของการ์ดแต่ละใบ</p><p>1 หมายถึง หมวดหมูทรัพยากร</p><p>หมายถึง ต้นไม้</p><p>หมายถึง นก</p><p>หมายถึง แมลง</p><p>หมายถึง เห็ด</p><p>2 หมายถึง ระดับความอุดมสมบูรณ์</p><p>⭐️ หมายถึง ลงการ์ดใบนี้ได้ในป่าระดับที่ 1</p><p>⭐️⭐️ หมายถึง ลงการ์ดใบนี้ได้ในป่าระดับที่ 1, 2</p><p>⭐️⭐️⭐️ หมายถึง ลงการ์ดใบนี้ได้ในป่าระดับที่ 1, 2, 3</p><p>3 หมายถึง คะแนนของการ์ดแต่ละใบ</p><p>4 หมายถึง ปัจจัยทางชีวภาพ</p><p>Producer หมายถึง ผู้ผลิต</p><p>Herbivore หมายถึง ผู้บริโภคที่กินพืช</p><p>Carnivore หมายถึง ผู้บริโภคที่กินสัตว์</p><p>Detritivore หมายถึง ผู้บริโภคที่กินซากพืชซากสัตว์</p><p>Decomposer หมายถึง ผู้ย่อยสลาย</p><p>5 หมายถึงสัญลักษ์แทนลักษณะของสิ่งมีชีวิต</p><p>ขนาด</p><p>S หมายถึง ขนาดเล็ก (น้อยกว่า 15 เซนติเมตร)</p><p>M หมายถึง ขนาดกลาง (ขนาด 15–30 เซนติเมตร)</p><p>L หมายถึง ขนาดใหญ่ (มากกว่า 30 เซนติเมตร)</p><p>อาหาร</p><p>หมายถึง กินน้ำหวานดอกไม้</p><p>หมายถึง กินพืชและผลไม้</p><p>หมายถึง กินแมลง</p><p>หมายถึง กินสัตว์เลี้ยงลูกด้วยนมขนาดเล็ก</p><p>หมายถึง เห็ดกินได้</p><p>หมายถึง เห็ดมีพิษ</p><p>หมายถึง ขนาดความกว้างของเห็ด</p><p>ขั้นตอนการเล่น</p><p>แจกการ์ดทรัพยากร์ให้ผู้เล่นแต่ละคน 5 ใบ</p><p>วางการ์ดระดังความอุดมสมบูรณ์ระดับที่ 1 และคอยนับจำนวนการ์ดทรัพยากรที่ลงไปแล้ว โดยการเลื่อนระดับความอุดมสมบูรณ์ จากระดับ 1 ไป 2 ใช้การ์ดทรัพยากร 20 ใบ และ จากระดับ 2 ไป 3 ใช้การ์ดทรัพยากร 40 ใบ</p><p>ตกลงผู้เริ่มเล่นคนแรกแล้ววนไปทาวขวา</p><p>โดยผู้เล่นจะลงการทรัพยากรณ์หรือการ์ดต้นไม้ครั้งละ 1 ใบเท่านั้น</p><p>ผู้เล่นอ่านชื่อ และ ความสามารถ ปฏิบัติตามความสามารถนั้น ๆ และ คำนวนคะแนน</p>", "learning": "", "debrief": "<p>ผู้นำเกมชวนผู้เล่นพูดคุยแลกเปลี่ยนสิ่งที่ได้เรียนรู้หลังจบเกม เช่น ได้เรียนรู้อะไรบ้าง ชอบต้นไม้หรือสัตว์ชนิดใด ไม่ชอบอะไร พร้อมให้ผู้เล่นทบทวนสิ่งมีชีวิตที่รู้จักหลังจากเล่นเกม แล้ววาดลูกศรเชื่อมโยงความสัมพันธ์เป็นสายใยอาหาร (food web) ลงในใบงาน เพื่อสรุปบทบาทของสิ่งมีชีวิตในระบบนิเวศป่า ทั้งผู้ผลิต ผู้บริโภค และผู้ย่อยสลาย รวมถึงประโยชน์ที่มนุษย์ได้รับจากป่า จากนั้นชวนคิดเพิ่มเติมด้วยคำถามกระตุ้นการเรียนรู้ เช่น สังเกตไหมว่ามีสิ่งมีชีวิตชนิดใดเป็นชนิดเด่นหรือชนิดหายาก ป่าที่เล่นเป็นป่าประเภทอะไร ใกล้บ้านมีต้นไม้อะไรบ้างที่เหมือนหรือต่างจากในเกม และปัญหาที่พบในป่า ฯลฯ</p>", "gallery": ""}, "gallery": [{"src": "assets/07-image129.png", "section": "play"}, {"src": "assets/07-image130.png", "section": "play"}, {"src": "assets/07-image131.png", "section": "play"}, {"src": "assets/07-image132.png", "section": "play"}, {"src": "assets/07-image133.png", "section": "play"}, {"src": "assets/07-image134.png", "section": "play"}, {"src": "assets/07-image135.png", "section": "play"}, {"src": "assets/07-image136.png", "section": "play"}, {"src": "assets/07-image137.png", "section": "play"}, {"src": "assets/07-image138.png", "section": "play"}, {"src": "assets/07-image139.png", "section": "play"}, {"src": "assets/07-image140.png", "section": "play"}, {"src": "assets/07-image141.png", "section": "play"}], "images": ["assets/07-image139.png", "assets/07-image129.png", "assets/07-image140.png", "assets/07-image130.png", "assets/07-image141.png", "assets/07-image131.png", "assets/07-image132.png", "assets/07-image138.png", "assets/07-image133.png", "assets/07-image134.png", "assets/07-image135.png", "assets/07-image136.png", "assets/07-image137.png"]}, {"id": "08", "title": "Manage-For-Nan", "category": "forest", "cover": "assets/cover-08.webp", "players": "6–11 players", "time": "5 rounds", "intro": "Bring villagers and forest managers together to plan a thriving planted forest.", "research": "Assessing ecosystem services and testing a participatory integrated model for planted-forest management in Nan Province.", "overview": "Manage-For-Nan is a three-dimensional role-playing board game that makes planted-forest ecosystem services visible. Participants share knowledge and develop forest-management plans suited to their local community.", "materials": ["A 420-cell landscape board (20 × 21), with each cell representing one rai; land-cover pieces and pins.", "Forest-product, bird, pavilion and six event cards covering normal conditions, recession, drought and unseasonal rainfall.", "Role and income records, planting and crop cost/price sheets, play money, labour tokens and wildfire beads.", "An Excel recording/results file and pre/post learning assessments are listed in the source; no separate spreadsheet was supplied."], "play": ["Assign one university regional learning-centre officer and 5–10 villagers. The officer aims for 80 rai of planted forest, including 20 rai at level three, over five rounds with an annual budget of 200,000 baht.", "Villagers seek the highest cumulative income from farming and forest products. Each has ten rai and starting capital of 30,000 or 50,000 baht; they can also plant and maintain forest.", "Explain the roles and scenario. In scenario two, negotiate joint agreements before selecting activities.", "Choose farming, collection, planting and maintenance activities; allocate labour and record costs. Resolve special activities such as birdwatching, school projects, research and pavilion placement.", "Draw wildfire and event outcomes, calculate income and ecosystem-service benefits, update records and the board, and continue for five rounds."], "debrief": "Compare villagers’ and officers’ experiences. Discuss provisioning, regulating and cultural services, shared project planning, planting and ongoing care. Consider wildfire, drought and economic risks when designing a management plan for the community.", "file": "documents/08_วางแผนปลูกป่า (Manage-For-Nan).docx", "titleTh": "วางแผนปลูกป่า (Management of Planted Forest at Nan Province: Manage-For-Nan game)", "introTh": "ให้ชาวบ้านและผู้ดูแลป่าร่วมออกแบบอนาคตของป่าปลูก", "researchTh": "การประเมินบริการของระบบนิเวศและการทดสอบแบบจำลองเชิงบูรณาการอย่างมีส่วนร่วมสำหรับการจัดการป่าปลูกในจังหวัดน่าน", "sourceTh": "งานวิจัย", "tags": [{"th": "ป่าปลูก", "en": "Planted Forest"}, {"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "การวางแผนการจัดการอย่างมีส่วนร่วม", "en": "Participatory Management Planning"}, {"th": "เกมกระดาน 3 มิติ", "en": "3D Board Game"}, {"th": "การสวมบทบาท", "en": "Role Playing"}, {"th": "จังหวัดน่าน", "en": "Nan Province"}], "sectionsTh": {"overview": "<p>จากงานวิจัยการประเมินบริการของระบบนิเวศป่าปลูกและการทดสอบแบบจำลองเชิงบูรณาการเพื่อการมีส่วนร่วมในจังหวัดน่าน ผู้วิจัยได้สร้างเกม Manage-For-Nan ซึ่งเป็นเกมสวมบทบาท ในรูปแบบเกมกระดาน 3 มิติ เพื่อให้ผู้เล่น เห็นภาพบริการของระบบนิเวศป่าปลูก เกิดการแลกเปลี่ยนเรียนรู้เกี่ยวกับบริการของระบบนิเวศป่าปลูก และร่วมกันออกแบบแผนการจัดการป่าปลูกที่มีประสิทธิภาพในบริบทของชุมชนท้องถิ่นของตนเอง</p>", "materials": "<p>กระดานพื้นที่ชุมชน ภูมิทัศน์จำลองขนาด 420 ช่อง (20 x 21 ช่อง) โดย 1 ช่องแทนพื้นที่จริง 1 ไร่ พร้อมฟีเจอร์บอร์ดและกระดาษแสดงสิ่งปกคลุมดิน (ป่าธรรมชาติ ป่าปลูกระดับที่ 1-3 และพื้นที่เกษตรกรรม) และเข็มหมุดสำหรับตรึงอุปกรณ์</p><p>การ์ด</p><p>การ์ดของป่า เช่น เห็ดเผาะ เห็ดแดง เห็ดระโงก ไม้ยางนา หน่อไม้ และไก่ป่า</p><p>การ์ดนก แทนนกที่เข้ามาใช้ประโยชน์ในป่าปลูกตามระดับความอุดมสมบูรณ์ของป่า</p><p>การ์ดศาลา สำหรับกิจกรรมพิเศษที่ได้รับการสนับสนุนจาก อบต.</p><p>การ์ดเหตุการณ์ 6 ใบ ได้แก่ เหตุการณ์สภาพอากาศและสภาวะทางเศรษฐกิจปกติ 3 ใบ เศรษฐกิจตกต่ำ ภัยแล้ง และฝนไม่ตกตามฤดูกาล อย่างละ 1 ใบ</p><p>ใบบันทึกข้อมูลสำหรับเจ้าหน้าที่ ศคภ. และชาวบ้าน ใบบันทึกรายได้อื่น ๆ และกิจกรรมปลูกป่า พร้อมใบข้อมูลต้นทุนการปลูกป่าและต้นทุน-ราคาผลผลิตทางการเกษตร</p><p>เงินปลอมสำหรับใช้เป็นสื่อกลางในการซื้อขาย</p><p>หมากตัวแทนแรงงาน และลูกปัดตัวแทนไฟป่า</p><p>ไฟล์บันทึกข้อมูลและแสดงผลลัพธ์ในโปรแกรม Microsoft Excel</p><p>แบบประเมินการเรียนรู้ก่อนและหลังเล่นเกม</p>", "play": "<p>คำอธิบายเกม</p><p>ฝ่ายเจ้าหน้าที่ ศคภ. (ศูนย์เครือข่ายการเรียนรู้เพื่อภูมิภาค จุฬาลงกรณ์มหาวิทยาลัย) จำนวน 1 คน มีเป้าหมายขยายพื้นที่ป่าปลูกให้ครบ 80 ไร่ ภายใน 5 รอบการเล่น โดยต้องมีป่าที่อุดมสมบูรณ์ระดับสูงสุด (LV.3) จำนวน 20 ไร่ ด้วยงบประมาณปีละ 200,000 บาท</p><p>ฝ่ายชาวบ้าน จำนวน 5-10 คน มีเป้าหมายสร้างรายได้สะสมสูงสุดจากการทำเกษตรกรรมบนที่ดินของตนเอง (คนละ 10 ไร่ ด้วยต้นทุนเริ่มต้น 30,000 หรือ 50,000 บาท) และการหาของป่า โดยสามารถเลือกปลูกป่าหรือดูแลป่าปลูกได้เช่นเดียวกับเจ้าหน้าที่ ศคภ.</p><p>ขั้นตอนการเล่น (ในแต่ละรอบการเล่น)</p><p>ผู้นำเกมแจกและอธิบายอุปกรณ์ ชี้แจงเป้าหมาย วิธีการเล่น และสถานการณ์จำลอง</p><p>ผู้เล่นทั้งสองฝ่ายพูดคุยสร้างข้อตกลงในการดำเนินกิจกรรมร่วมกัน (เฉพาะสถานการณ์จำลองที่ 2)</p><p>ชาวบ้านเลือกพื้นที่และประเภทของเกษตรกรรม พื้นที่เก็บของป่า และกิจกรรมปลูกป่า พร้อมวางหมากตัวแทนแรงงานบนกระดาน ส่วนเจ้าหน้าที่ ศคภ. เลือกกิจกรรมปลูกป่าและดูแลป่าปลูก และคำนวณค่าใช้จ่ายลงในใบบันทึกข้อมูล</p><p>ผู้เล่นร่วมกันดำเนินกิจกรรมพิเศษประจำรอบ เช่น เยาวชนขอเข้าพื้นที่เพื่อทำโครงงานวิทยาศาสตร์ นักท่องเที่ยวเข้ามาดูนก นักวิจัยขอใช้พื้นที่วิจัย และการวางศาลาที่ได้รับการสนับสนุนจาก อบต.</p><p>ผู้นำเกมสุ่มไฟป่าและการ์ดเหตุการณ์ประจำรอบการเล่น ผู้เล่นปรับผลลัพธ์ตามเหตุการณ์ที่เกิดขึ้น</p><p>ผู้นำเกมแจงรายได้ แจกเงิน และการ์ดบริการของระบบนิเวศให้ชาวบ้านแต่ละคน</p><p>ผู้ช่วยนำเกมกรอกข้อมูลของผู้เล่นลงไฟล์บันทึกข้อมูล Microsoft Excel เพื่อคำนวณและแสดงผลลัพธ์ พร้อมปรับผลลัพธ์บนกระดาน จากนั้นเริ่มรอบการเล่นถัดไปจนครบ 5 รอบ</p>", "learning": "", "debrief": "<p>ผู้นำเกมให้ผู้เล่นทำแบบประเมินการเรียนรู้ก่อนและหลังเล่นเกม เพื่อประเมินความรู้ความเข้าใจเรื่องบริการของระบบนิเวศและการจัดการป่าปลูก จากนั้นชวนผู้เล่นพูดคุยแลกเปลี่ยนสิ่งที่ได้เรียนรู้ระหว่างฝ่ายชาวบ้านและเจ้าหน้าที่ ศคภ. โดยชี้ให้เห็นถึงบริการของระบบนิเวศที่ได้รับจากป่าปลูกทั้ง 3 ด้าน ได้แก่ ด้านการให้ผลผลิต เช่น เห็ดและของป่า ด้านการควบคุมและรักษาสมดุล เช่น การเข้ามาใช้ประโยชน์ของนกตามระดับความอุดมสมบูรณ์ของป่า และด้านวัฒนธรรม เช่น การท่องเที่ยวดูนก การเป็นแหล่งศึกษาเรียนรู้และพักผ่อนหย่อนใจ รวมถึงการจัดการป่าปลูกทั้ง 3 ระยะ คือ การร่วมกันวางแผนโครงการ การมีส่วนร่วมในกิจกรรมปลูกป่า และการดูแลป่าหลังการปลูก ตลอดจนการวางแผนรับมือความเสี่ยงจากเหตุการณ์ที่ไม่สามารถควบคุมได้ เช่น ไฟป่า ภัยแล้ง และสภาวะเศรษฐกิจตกต่ำ เพื่อนำไปสู่การร่วมกันออกแบบแผนการจัดการป่าปลูกที่เหมาะสมกับบริบทของชุมชนต่อไป</p>", "gallery": ""}, "gallery": [{"src": "assets/08-image142.png", "section": "materials"}, {"src": "assets/08-image143.png", "section": "materials"}, {"src": "assets/08-image144.png", "section": "materials"}, {"src": "assets/08-image145.png", "section": "materials"}, {"src": "assets/08-image146.png", "section": "materials"}, {"src": "assets/08-image147.png", "section": "materials"}, {"src": "assets/08-image148.png", "section": "materials"}, {"src": "assets/08-image149.png", "section": "materials"}, {"src": "assets/08-image150.png", "section": "materials"}, {"src": "assets/08-image151.png", "section": "materials"}, {"src": "assets/08-image152.png", "section": "materials"}, {"src": "assets/08-image153.png", "section": "gallery"}], "images": ["assets/08-image150.png", "assets/08-image151.png", "assets/08-image152.png", "assets/08-image142.png", "assets/08-image153.png", "assets/08-image143.png", "assets/08-image144.png", "assets/08-image149.png", "assets/08-image145.png", "assets/08-image146.png", "assets/08-image147.png", "assets/08-image148.png"]}, {"id": "09", "title": "Coco Green Space", "category": "urban", "cover": "assets/cover-09.webp", "players": "9 per group", "time": "≈2 hours / 3 rounds", "intro": "Co-design urban green spaces that serve people, birds and a shared future.", "research": "Gaming and simulation for shared learning about the importance and co-construction of urban green space.", "overview": "Urban growth can reduce green space and worsen biodiversity loss, heat, air pollution and wellbeing. This game helps community roles explore six green-space types, agree shared benefits and negotiate the trade-offs involved in creating useful, lasting green spaces.", "materials": ["A 200-cell board with 6 × 6 cm cells; nine role tokens; green-space and other land-use pictograms.", "Recording and purchase sheets; five scenario cards; sixteen co-benefit types; bird habitat condition cards.", "Activity and knowledge cards, fish/forest-product/bird tokens, orange carbon beads, certificates, pre/post tests and satisfaction forms.", "The source also lists an Excel income/results file; no separate spreadsheet was supplied."], "play": ["Use nine players per group, ideally two groups for comparison. Assign teacher, student, local authority, factory, health centre, farmer, monk, bird and environmentalist roles. Complete a five-minute pretest.", "Agree three shared co-benefits. Allow three minutes to plan green-space purchases and discuss joint development.", "Roles one to seven purchase and place green-space pictograms in turn. The bird player places birds according to habitat conditions; the environmentalist records biodiversity and benefits.", "Plan two public activities, pay the game’s participation costs, exchange knowledge and award certificates. Photograph the board, place carbon beads representing absorption and pay income.", "Introduce the remaining climate, tourism, pollution and funding scenarios, recording carbon and outcomes. The design includes five scenarios; the documented trial used approximately two hours for three rounds.", "Finish with a five-minute posttest, a satisfaction assessment and a group debrief."], "debrief": "Compare the two groups’ boards and strategies. Use carbon-bead totals and available results to discuss emissions and absorption. Examine birds as indicators of green-space quality, then agree desired co-benefits and co-design a real pilot green space.", "file": "documents/09_เกมพื้นที่สีเขียวร่วมออกแบบ (Coco green space).docx", "titleTh": "เกมพื้นที่สีเขียวร่วมออกแบบเพื่อประโยชน์ร่วม (Coco green space: Co-design for co-benefits)", "introTh": "ร่วมออกแบบพื้นที่สีเขียวเพื่อคน นก และประโยชน์ร่วมของชุมชน", "researchTh": "เกมและสถานการณ์จำลองเพื่อการแลกเปลี่ยนเรียนรู้เรื่องความสำคัญและการร่วมสร้างพื้นที่สีเขียวในเมือง (Gaming and simulation for shared learning about the importance and co-construction of urban green space)", "sourceTh": "งานวิจัย", "tags": [{"th": "พื้นที่สีเขียว", "en": "Green Space"}, {"th": "ประโยชน์ร่วม", "en": "Co-Benefits"}, {"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "คาร์บอนฟุตพริ้นท์", "en": "Carbon Footprint"}, {"th": "ความหลากหลายทางชีวภาพ", "en": "Biodiversity"}, {"th": "การร่วมออกแบบ", "en": "Co-Design"}, {"th": "แบบจำลองเพื่อนคู่คิด", "en": "Companion Modelling"}], "sectionsTh": {"overview": "<p>การสูญเสียพื้นที่สีเขียวจากการขยายตัวของเมืองและพื้นที่เกษตรส่งผลกระทบต่อทั้งสิ่งมีชีวิตและมนุษย์ ทั้งการสูญเสียความหลากหลายทางชีวภาพ ฝุ่นละออง ปรากฏการณ์เกาะความร้อนในเมือง และสุขภาพจิตของคนเมือง แต่นโยบายเพิ่มพื้นที่สีเขียวที่มีอยู่มักเน้นเป้าหมายเชิงปริมาณมากกว่าคุณภาพ และขาดการมีส่วนร่วมของประชาชน ทำให้พื้นที่สีเขียวที่สร้างขึ้นไม่ยั่งยืนเพราะไม่ตอบโจทย์ความต้องการของคนในพื้นที่ เกมนี้จึงถูกพัฒนาขึ้นเพื่อให้ผู้เล่นซึ่งมีบทบาทต่างกันในชุมชนได้เรียนรู้ประเภทของพื้นที่สีเขียว 6 ประเภท เข้าใจประโยชน์ร่วม ที่ชุมชนจะได้รับ และร่วมกันออกแบบและวางแผนเพิ่มพื้นที่สีเขียวในพื้นที่จริง โดยผู้เล่นต้องตกลงร่วมกันว่าจะให้พื้นที่สีเขียวของชุมชนให้ประโยชน์ด้านใด ขณะเดียวกันก็ต้องทำกิจกรรมให้บรรลุเป้าหมายของบทบาทตนเอง จึงเกิดการเรียนรู้เรื่องการได้-เสีย และทางออกแบบได้ประโยชน์ร่วมกัน ในการสร้างและปรับปรุงพื้นที่สีเขียว</p>", "materials": "<p>กระดานเกม ขนาด 200 ช่อง (ช่องละ 6 x 6 เซนติเมตร) สำหรับวางภาพสัญลักษณ์ประเภทต่าง ๆ</p><p>หมากผู้เล่น 9 บทบาท ได้แก่ ครู นักเรียน องค์การบริหารส่วนตำบล โรงงานเอกชน โรงพยาบาลส่งเสริมสุขภาพตำบล เกษตรกร พระ นก และนักสิ่งแวดล้อม เพื่อให้เรียนรู้ว่าแต่ละบทบาทมีส่วนร่วมในการวางแผนและจัดการพื้นที่สีเขียวได้อย่างไร</p><p>ภาพสัญลักษณ์ (pictogram) ขนาด 6 x 6 เซนติเมตร แบ่งเป็น 2 กลุ่ม</p><p>ภาพพื้นที่สีเขียว 6 ประเภท (21 รูปแบบ) ได้แก่ พื้นที่สีเขียวส่วนบุคคล พื้นที่สีเขียวสถาบัน พื้นที่สีเขียวสาธารณูปการ พื้นที่สีเขียวแนวยาวตามแนวสาธารณูปการ พื้นที่สีเขียวเศรษฐกิจชุมชน และพื้นที่สีเขียวธรรมชาติ</p><p>ภาพการใช้ที่ดินและสิ่งปกคลุมดินอื่น ๆ 10 แบบ ได้แก่ ถนน โรงเรียน โรงงาน องค์การบริหารส่วนตำบล โรงพยาบาล บ้าน วัด สำนักงาน และพื้นที่ว่างเปล่า</p><p>แบบบันทึกข้อมูล สำหรับบันทึกเป้าหมายของแต่ละบทบาท (นักสิ่งแวดล้อมมีแบบบันทึกความหลากหลายทางชีวภาพเพิ่มเติมเพื่อบันทึกสิ่งมีชีวิตที่เข้ามาใช้พื้นที่สีเขียว) และใบสั่งซื้อสำหรับบันทึกการตัดสินใจซื้อภาพสัญลักษณ์</p><p>การ์ดสถานการณ์ 5 สถานการณ์ ที่พัฒนาจากสถานการณ์ที่พบได้จริงในพื้นที่ศึกษา</p><p>สภาวะปกติ ใช้ในรอบแรกเพื่อให้ผู้เล่นทำความคุ้นเคยกับอุปกรณ์และขั้นตอนของเกม</p><p>นักท่องเที่ยวเข้ามาดูนก แสดงความสำคัญของพื้นที่สีเขียวต่อการอนุรักษ์ความหลากหลายทางชีวภาพ (แทนด้วยนก) และรายได้จากการท่องเที่ยวดูนก</p><p>ภาวะโลกร้อน แสดงผลกระทบด้านสิ่งแวดล้อมและเศรษฐกิจสังคมจากการเปลี่ยนแปลงสภาพภูมิอากาศ ซึ่งทำให้รายได้ของชุมชนลดลง</p><p>ฝุ่นละออง PM 2.5 แสดงความสำคัญของพื้นที่สีเขียวและผลของมลพิษทางอากาศต่อสุขภาพ ซึ่งนำไปสู่ค่าใช้จ่ายด้านการรักษาและความจำเป็นในการอบรมเพื่อปรับตัว</p><p>ทุนสนับสนุนจากภาคเอกชน แสดงการพัฒนาพื้นที่สีเขียวด้วยแหล่งทุนจากภายนอก</p><p>การ์ดประโยชน์ร่วม (co-benefit cards) 16 ประเภท เช่น ความหลากหลายทางชีวภาพ การกักเก็บคาร์บอน การตรวจวัดคุณภาพอากาศ การลดอุณหภูมิ การศึกษาเรียนรู้ ของป่า พื้นที่รับน้ำ พื้นที่ออกกำลังกาย พื้นที่จัดกิจกรรม นันทนาการ การสร้างอาชีพ และการท่องเที่ยว ใช้ให้ผู้เล่นร่วมกันเลือกประโยชน์ที่ต้องการได้รับจากพื้นที่สีเขียวของชุมชน</p><p>การ์ดเงื่อนไขการเข้าอยู่อาศัยของนก แสดงคุณสมบัติที่เกิดขึ้นเมื่อพื้นที่สีเขียวมีขนาดใหญ่พอ โดยนกน้ำ 1 ตัวต้องการพื้นที่น้ำที่เชื่อมต่อกัน 2 ช่อง และนกที่ไม่ใช่นกน้ำ 1 ตัวต้องการพื้นที่สีเขียวที่ติดกัน 4 ช่อง ทั้งแนวตั้ง แนวนอน หรือแนวทแยง</p><p>ไฟล์ Excel สำหรับบันทึกการตัดสินใจซื้อของผู้เล่น คำนวณรายได้ และแสดงผลการตัดสินใจเพื่อใช้ในช่วงสรุปผล</p><p>อุปกรณ์อื่น ๆ ได้แก่ การ์ดกิจกรรม การ์ดความรู้ (ผู้เล่นอ่านเพื่อแลกเปลี่ยนความรู้) หมากปลา หมากของป่า หมากนก ลูกปัดสีส้ม (แทนคาร์บอนไดออกไซด์ที่ปล่อยจากกิจกรรมของมนุษย์) และเกียรติบัตร 4 ประเภทที่ผู้เล่นได้รับเมื่อเข้าร่วมกิจกรรม</p><p>แบบทดสอบก่อนและหลังเล่นเกม พร้อมแบบประเมินความพึงพอใจ</p>", "play": "<p>แนะนำและกติกาเกม</p><p>เกมออกแบบสำหรับผู้เล่น 9 คนต่อกลุ่ม โดยผู้เล่นแต่ละคนรับบทบาทที่ต่างกันในชุมชน สามารถเล่นพร้อมกัน 2 กลุ่มเพื่อเปรียบเทียบผลการตัดสินใจและเพิ่มประสบการณ์การเรียนรู้ เกมกำหนดไว้ 5 รอบ โดยแต่ละรอบใช้การ์ดสถานการณ์ที่ต่างกัน ผู้เล่นต้องตกลงร่วมกันว่าจะให้พื้นที่สีเขียวของชุมชนให้ประโยชน์ร่วมด้านใด 3 ประการ ขณะเดียวกันต้องทำกิจกรรมให้บรรลุเป้าหมายของบทบาทตนเอง จากการทดสอบพบว่าการเล่น 3 รอบใช้เวลาประมาณ 2 ชั่วโมง</p><p>ขั้นตอนการเล่น</p><p>เตรียมอุปกรณ์ 2 ชุดสำหรับผู้เล่น 2 กลุ่ม (กระดานเกม 2 แผ่น และธนาคารพร้อมอุปกรณ์)</p><p>แบ่งผู้เล่นเป็น 2 กลุ่ม กลุ่มละ 9 คน</p><p>กำหนดหมายเลขผู้เล่น 1-9 ตามลำดับที่นั่ง แจกป้ายรหัสผู้เล่น A และ B พร้อมกระดานรองเขียนและแบบบันทึกข้อมูล</p><p>ผู้เล่นทำแบบทดสอบก่อนเล่นเกม 5 นาที จากนั้นแจกชุดอุปกรณ์ให้ผู้เล่นแต่ละคน</p><p>ผู้นำเกมอธิบายอุปกรณ์ กติกา เป้าหมายส่วนบุคคลและเป้าหมายร่วมของชุมชน และขั้นตอนการเล่น พร้อมเปิดโอกาสให้ซักถาม</p><p>ผู้เล่นตกลงร่วมกันเลือกการ์ดประโยชน์ร่วม 3 ใบ ที่ต้องการได้รับจากพื้นที่สีเขียวของชุมชน</p><p>ให้เวลา 3 นาที เพื่อวางแผนการซื้อพื้นที่สีเขียว (กรอกใบสั่งซื้อ) และหารือแนวทางการพัฒนาร่วมกัน</p><p>ผู้เล่นคนที่ 1 (ครู) ยื่นใบสั่งซื้อต่อธนาคาร ซื้อภาพสัญลักษณ์พื้นที่สีเขียวและวางลงบนกระดาน จากนั้นผู้เล่นคนที่ 2-7 ทำตามลำดับ</p><p>ผู้เล่นคนที่ 8 (นก) วางหมากนกบนพื้นที่สีเขียวตามเงื่อนไขการเข้าอยู่อาศัยของนก</p><p>ผู้เล่นคนที่ 9 (นักสิ่งแวดล้อม) บันทึกชนิดของนกและประโยชน์ที่ได้รับลงในแบบบันทึกความหลากหลายทางชีวภาพ</p><p>ผู้เล่นปรึกษากันเพื่อจัดกิจกรรมสาธารณะ 2 กิจกรรม ผู้เข้าร่วมจ่ายค่าใช้จ่าย 1,000 และวางหมากของตนในพื้นที่จัดกิจกรรม ผู้จัดกิจกรรมอ่านการ์ดความรู้และมอบเกียรติบัตรให้ผู้เข้าร่วม</p><p>ผู้นำเกมถ่ายภาพกระดานจากหลายมุมเพื่อใช้วิเคราะห์ต่อ แล้วให้ผู้เล่นนำหมากกลับไปยังพื้นที่ของตนเอง</p><p>ผู้เล่นวางลูกปัดคาร์บอนบนพื้นที่สีเขียวเพื่อแทนการดูดซับคาร์บอนของพื้นที่สีเขียว แล้วผู้นำเกมถ่ายภาพกระดานอีกครั้ง</p><p>ธนาคาร (ผู้ช่วยดำเนินเกม) จ่ายรายได้ให้ผู้เล่นแต่ละคน ถือเป็นการจบรอบที่ 1</p><p>เริ่มรอบที่ 2 โดยเทลูกปัดคาร์บอนลงในภาชนะใสเพื่อแสดงการปล่อยและการสะสมคาร์บอนในบรรยากาศ (ใช้ในช่วงสรุปผล) ผู้นำเกมประกาศสถานการณ์ที่ 2 และ 3 แจกลูกปัดคาร์บอนชุดใหม่แทนการปล่อยคาร์บอน และวางของป่าในพื้นที่ป่าชุมชน</p><p>ทำซ้ำขั้นตอนที่ 6-14 จนจบรอบที่ 2 และเล่นรอบที่ 3 ด้วยอีก 2 สถานการณ์หากมีเวลาเพียงพอ จากนั้นเทลูกปัดคาร์บอนลงในภาชนะใสอีกใบเพื่อเปรียบเทียบการปล่อยคาร์บอนของแต่ละรอบ</p><p>ผู้เล่นทำแบบทดสอบหลังเล่นเกมภายใน 5 นาที พร้อมแบบประเมินความพึงพอใจ</p><p>ผู้นำเกมดำเนินการสรุปผลการใช้งาน (debriefing)</p>", "learning": "", "debrief": "<p>ผู้นำเกมเปิดโอกาสให้ผู้เล่นทั้งสองกลุ่มเดินดูกระดานเกมของกลุ่มอื่น เพื่อเปรียบเทียบความแตกต่างของการสร้างพื้นที่สีเขียวและกลยุทธ์การตัดสินใจที่ใช้เพื่อให้บรรลุเป้าหมายส่วนบุคคลและเป้าหมายร่วม จากนั้นสรุปเรื่องการปล่อยคาร์บอนไดออกไซด์โดยแสดงภาชนะที่สะสมลูกปัดสีส้มของแต่ละรอบเปรียบเทียบกัน พร้อมแสดงกราฟการเปลี่ยนแปลงอุณหภูมิจากไฟล์ Excel เพื่อสะท้อนความสัมพันธ์ระหว่างการปล่อยคาร์บอนกับความสามารถในการดูดซับของพื้นที่สีเขียวในชุมชน และชี้ให้เห็นว่าการจัดการพื้นที่สีเขียวอย่างเหมาะสมช่วยลดคาร์บอนในบรรยากาศได้ ต่อด้วยการสรุปผลด้านความหลากหลายทางชีวภาพ โดยเน้นว่านกในเกมนี้เป็นตัวชี้วัดคุณภาพของพื้นที่สีเขียว หากพื้นที่สีเขียวเสื่อมโทรมหรือมีไม่เพียงพอจะส่งผลต่อที่อยู่อาศัยของนกและทำให้ความหลากหลายทางชีวภาพลดลง สุดท้ายผู้นำเกมจัดวงพูดคุยและถาม-ตอบเพื่อให้บรรลุวัตถุประสงค์ของเกม รวมทั้งจัดกระบวนการระดมสมองเพื่อร่วมกันกำหนดประโยชน์ร่วมที่ต้องการได้รับจากพื้นที่สีเขียวที่จะสร้างขึ้นในชุมชน และร่วมออกแบบพื้นที่นำร่องเพื่อสนับสนุนการเพิ่มพื้นที่สีเขียวในพื้นที่จริงต่อไป</p>", "gallery": ""}, "gallery": [{"src": "assets/09-image154.png", "section": "materials"}, {"src": "assets/09-image155.png", "section": "materials"}, {"src": "assets/09-image156.png", "section": "materials"}, {"src": "assets/09-image157.png", "section": "gallery"}, {"src": "assets/09-image158.png", "section": "gallery"}], "images": ["assets/09-image154.png", "assets/09-image155.png", "assets/09-image156.png", "assets/09-image157.png", "assets/09-image158.png"]}, {"id": "10", "title": "Green Roof Bingo", "category": "urban", "cover": "assets/cover-10.webp", "players": "8–12 players", "time": "≈30 min / round", "intro": "Design a rooftop landscape and discover the ecosystem services it can provide.", "research": "Board game for collective learning on green roof ecosystem services.", "overview": "Green roofs can add vegetation to existing buildings where ground-level green space is limited. Players act as building owners, designing roofs within a budget and exploring provisioning, habitat, regulating and cultural services through bingo and redesign.", "materials": ["Individual 25-cell roof boards and roof-component pieces, including vegetation, ground surfaces, water and facilities.", "Numbered ecosystem-service condition cards (1–24), bingo materials, component descriptions and cost information.", "Roof recording sheets, assessments of four ecosystem-service groups, pre/post tests and satisfaction forms. Detailed component quantities and illustrations are in the original source."], "play": ["Prepare 8–12 building-owner roles with equal starting funds and individual 25-cell boards. Introduce green roofs and complete the pretest.", "In round one, draw building locations A–H and spend 10–20 minutes filling the board with selected components within the budget. Record the roof design.", "Draw numbers 1–24 and read their ecosystem-service conditions. Players whose roofs qualify mark the corresponding number. Five aligned marks earn a bingo bonus.", "The first round ends when one player completes three bingo lines. Add component service scores and bingo bonuses, then discuss the design choices.", "In round two, redesign the roofs using what was learned and assess all four service groups. The highest total wins, with an additional award for the greatest improvement.", "Use approximately thirty minutes per round. Discuss context-specific building load and public-access conditions; in this game bees require at least four flowering-plant cells. Complete the posttest and satisfaction assessment."], "debrief": "Walk around the roof designs and compare components, costs and services. Discuss carbon storage, shade, runoff, food, income, habitat and recreation. Compare scores between rounds and explore how roofs can act as habitat stepping stones and inspire local green-space projects.", "file": "documents/10_เกมหลังคาเขียวบิงโก (Green Roof Bingo).docx", "titleTh": "เกมหลังคาเขียวบิงโก (Green Roof Bingo)", "introTh": "ออกแบบสวนบนดาดฟ้า แล้วค้นพบบริการของระบบนิเวศผ่านเกมบิงโก", "researchTh": "เกมกระดานเพื่อการแลกเปลี่ยนเรียนรู้เรื่องบริการของระบบนิเวศหลังคาเขียว (Board game for collective learning on green roof ecosystem services)", "sourceTh": "งานวิจัย", "tags": [{"th": "หลังคาเขียว", "en": "Green Roof"}, {"th": "พื้นที่สีเขียวในเมือง", "en": "Urban Green Space"}, {"th": "บริการของระบบนิเวศ", "en": "Ecosystem Services"}, {"th": "เกมกระดาน 3 มิติ", "en": "3D Board Game"}, {"th": "บิงโก", "en": "Bingo"}, {"th": "การแลกเปลี่ยนเรียนรู้", "en": "Collective Learning"}], "sectionsTh": {"overview": "<p>พื้นที่สีเขียวในเขตเมืองมีอยู่อย่างจำกัด โดยกรุงเทพมหานครมีสัดส่วนพื้นที่สีเขียวเพียง 6.16 ตารางเมตรต่อคน (พ.ศ. 2560) ซึ่งต่ำกว่าเกณฑ์ขององค์การอนามัยโลกที่กำหนดไว้ 9 ตารางเมตรต่อคน หลังคาเขียว (green roof) จึงเป็นทางเลือกหนึ่งในการเพิ่มพื้นที่สีเขียวบนอาคารที่มีอยู่เดิม แต่คนเมืองส่วนใหญ่ยังไม่ตระหนักถึงประโยชน์ที่ได้รับจากหลังคาเขียว เกมนี้จึงถูกพัฒนาขึ้นเพื่อให้ผู้เล่นสวมบทบาทเป็นเจ้าของอาคารที่ต้องการสร้างหลังคาเขียวบนดาดฟ้าของตนเอง โดยเลือกซื้อและวางชิ้นส่วนองค์ประกอบหลังคาเขียวลงบนกระดานบิงโกให้ครบทุกช่องภายใต้ต้นทุนที่จำกัด แล้วประเมินบริการของระบบนิเวศที่หลังคาเขียวของตนให้ได้ครบทั้ง 4 ด้าน (ด้านการให้ผลผลิต ด้านการเป็นแหล่งที่อยู่อาศัย ด้านการควบคุมและรักษาสมดุล และด้านวัฒนธรรม) ผู้เล่นจึงได้เรียนรู้ว่าการออกแบบและการเลือกองค์ประกอบที่ต่างกันส่งผลต่อบริการของระบบนิเวศที่ได้รับอย่างไร พร้อมทั้งได้แลกเปลี่ยนแนวคิดการออกแบบระหว่างกัน</p>", "materials": "<p>กระดานเกมหลังคาเขียว 1 แผ่นต่อผู้เล่น 1 คน แบ่งเป็นตาราง 5 x 5 ช่อง รวม 25 ช่อง แทนพื้นที่ดาดฟ้าของอาคาร โดย 1 ช่อง เทียบเท่าพื้นที่จริง 36 ตารางเมตร และใช้เป็นบัตรบิงโกของผู้เล่นในเวลาเดียวกัน</p><p>ชิ้นส่วนภาพองค์ประกอบหลังคาเขียว (หมาก 3 มิติ) 20 หมายเลข แต่ละหมายเลขระบุรายละเอียดองค์ประกอบและต้นทุนที่ใช้กำกับไว้ ดังนี้</p><div class=\"table-scroll\"><table><tbody><tr><td><p>เบอร์</p></td><td><p>ภาพชิ้นส่วน</p></td><td><p>รายละเอียด</p><p>ส่วนประกอบ</p></td><td><p>ต้นทุน</p><p>ที่ใช้</p></td></tr><tr><td><p>1</p></td><td></td><td><p>Tree-มะม่วง 1 ต้น</p><p>Tree-อินทนิลน้ำ 1 ต้น</p><p>Shrub-ชบา 2 ต้น</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>110</p></td></tr><tr><td><p>2</p></td><td></td><td><p>Tree-แก้ว 1 ต้น</p><p>Tree-ลั่นทม 2 ต้น</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>132</p></td></tr><tr><td><p>3</p></td><td></td><td><p>Tree-กระถินณรงค์ 2 ต้น</p><p>Tree-พิกุล 2 ต้น</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>120</p></td></tr><tr><td><p>4</p></td><td></td><td><p>Tree-หมากนวล ปลูกในกระถาง 4 ต้น</p><p>โซลาร์เซลล์ 4 แผง</p><p>พื้นคอนกรีต 36 ตร.ม.</p></td><td><p>303</p></td></tr><tr><td><p>5</p></td><td></td><td><p>Herb-กะหล่ำปลี 15 หัว</p><p>Herb-ข้าวโพด 10 ต้น</p><p>Herb-นาข้าว 4.5 ตร.ม.</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>94</p></td></tr><tr><td><p>6</p></td><td></td><td><p>Shrub-มะนาว 2 ต้น</p><p>Herb-มะเขือเทศ 5 ต้น</p><p>พื้นคอนกรีต 36 ตร.ม.</p></td><td><p>1</p></td></tr><tr><td><p>7</p></td><td></td><td><p>รังผึ้ง 3 รัง</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>94</p></td></tr><tr><td><p>8</p></td><td></td><td><p>Tree-ปีบ 1 ต้น</p><p>Tree-อินทนิลน้ำ 2 ต้น</p><p>Tree-ไผ่ 3 ก่อ (รวม 45 ต้น)</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>120</p></td></tr><tr><td><p>9</p></td><td></td><td><p>ทางเดิน</p><p>สนามเด็กเล่น</p><p>โต๊ะ-เก้าอี้</p><p>ไฟฟ้าให้แสงสว่าง</p><p>พื้นที่คอนกรีต 4 ตร.ม.</p><p>พื้นดิน ขนาด 6.25 ตร.ม.</p><p>สนามหญ้า 36 ตร.ม.</p></td><td><p>289</p></td></tr><tr><td><p>10</p></td><td></td><td><p>สระว่ายน้ำ</p><p>ร่มกันแดด</p><p>เก้าอี้ริมสระว่ายน้ำ</p><p>ไฟฟ้าให้แสงสว่าง</p><p>พื้นที่คอนกรีต 36 ตร.ม.</p></td><td><p>400</p></td></tr><tr><td><p>11</p></td><td></td><td><p>Tree-ลั่นทม 1 ต้น</p><p>Herb-พลับพลึงตีนเป็ด 2 ต้น</p><p>Herb-แปลงดอกไม้ 3 แปลง ขนาดรวม 6.75 ตร.ม.</p><p>โต๊ะ-เก้าอี้</p><p>ป้ายคำอธิบายชื่อวิทยาศาสตร์ของพรรณไม้</p><p>กิจกรรมการเรียนรู้บนหลังคาเขียว</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>147</p></td></tr><tr><td><p>12</p></td><td></td><td><p>Tree-เหลืองปรีดียาธร 1 ต้น</p><p>Herb-ดาวเรือง 4 ต้น</p><p>Shrub-เฟื่องฟ้า 3 ต้น</p><p>โต๊ะ-เก้าอี้</p><p>ร่มกันแดด</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>176</p></td></tr><tr><td><p>13</p></td><td></td><td><p>Tree-มะม่วง 1 ต้น</p><p>Tree-ไทรย้อยใบแหลม 2 ต้น</p><p>ที่ให้อาหารนก</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>119</p></td></tr><tr><td><p>14</p></td><td></td><td><p>Tree-ลั่นทม 1 ต้น</p><p>สระบัว</p><p>ทางเดิน</p><p>พื้นดิน 18 ตร.ม.</p><p>สนามหญ้า ขนาด 18 ตร.ม.</p></td><td><p>116</p></td></tr><tr><td><p>15</p></td><td></td><td><p>Shrub-กุหลาบ 5 ต้น</p><p>Tree-ปีบ 1 ต้น</p><p>อ่างอาบน้ำนก</p><p>โต๊ะ-เก้าอี้</p><p>พื้นดิน 36 ตร.ม.</p></td><td><p>140</p></td></tr><tr><td><p>16</p></td><td></td><td><p>Tree-อินทนิลน้ำ 2 ต้น</p><p>Herb-ดาวเรือง 4 ต้น</p><p>Herb-ต้อยติ่งฝรั่ง 3 ต้น</p><p>Shrub-ชาฮกเกี้ยน 2 ต้น</p><p>พื้นคอนกรีต 36 ตร.ม.</p></td><td><p>18</p></td></tr><tr><td><p>17</p></td><td></td><td><p>พื้นดิน 36 ตร.ม.</p></td><td><p>94</p></td></tr><tr><td><p>18</p></td><td></td><td><p>สนามหญ้า 36 ตร.ม.</p></td><td><p>103</p></td></tr><tr><td><p>19</p></td><td></td><td><p>พื้นกรวด 36 ตร.ม.</p></td><td><p>160</p></td></tr><tr><td><p>20</p></td><td></td><td><p>สนามหญ้า 36 ตร.ม.</p></td><td><p>103</p></td></tr></tbody></table></div><p>สลากตำแหน่งอาคาร A-H พร้อมแผนที่ที่ตั้งของอาคารในพื้นที่ศึกษา ซึ่งมีบริบทรอบข้างแตกต่างกัน (สวนสาธารณะ สำนักงาน และมหาวิทยาลัย) เพื่อให้เห็นผลของที่ตั้งต่อศักยภาพของหลังคาเขียวในการเป็นพื้นที่พักพิงต่อเนื่อง (stepping stone) ของสิ่งมีชีวิต</p><p>การ์ดเงื่อนไขบริการของระบบนิเวศของหลังคาเขียว 24 ใบ (ภาษาไทยและภาษาอังกฤษ) สำหรับสุ่มอ่านในช่วงบิงโก โดยแต่ละใบระบุเงื่อนไขพร้อมเหตุผลทางวิชาการ เช่น</p><p>แบบประเมินบริการของระบบนิเวศหลังคาเขียว 4 ด้าน สำหรับให้ผู้เล่นประเมินหลังคาเขียวจำลองของตนเองในรอบที่ 2</p><p>แบบบันทึกข้อมูลหลังคาเขียว (Google Form) สำหรับบันทึกองค์ประกอบและต้นทุนที่ผู้เล่นเลือกใช้ เพื่อใช้วิเคราะห์และเปรียบเทียบผลการออกแบบในช่วงสรุปผล</p><p>เครื่องมือสุ่มตัวเลข 1-24 (random number) สำหรับสุ่มการ์ดเงื่อนไขในช่วงบิงโก</p><p>แบบทดสอบก่อนและหลังเล่นเกม พร้อมแบบประเมินความพึงพอใจต่อเกม</p>", "play": "<p>แนะนำและกติกาเกม</p><p>เกมออกแบบสำหรับผู้เล่น 8-12 คนต่อชุดกิจกรรม โดยผู้เล่นทุกคนสวมบทบาทเป็นเจ้าของอาคารที่ต้องการสร้างหลังคาเขียวบนดาดฟ้าของตนเอง ได้รับต้นทุนเท่ากัน และมีกระดานหลังคาเขียว 25 ช่องเป็นของตนเอง เกมแบ่งเป็น 2 รอบ รอบที่ 1 เน้นการเรียนรู้เงื่อนไขของบริการของระบบนิเวศผ่านการเล่นบิงโก และรอบที่ 2 ให้ผู้เล่นนำความรู้ที่ได้ไปออกแบบหลังคาเขียวใหม่แล้วประเมินตนเอง ใช้เวลาประมาณ 30 นาทีต่อรอบ</p><p>เงื่อนไขเพิ่มเติมที่ผู้นำเกมกำหนดตามบริบทของพื้นที่ ได้แก่ น้ำหนักที่โครงสร้างอาคารสามารถรับได้ การระบุการเปิดให้คนเข้าใช้งานหลังคาเขียว (ใช้สัญลักษณ์ในเกม) และเงื่อนไขที่ผึ้งจะเข้ามาใช้พื้นที่ได้ต่อเมื่อมีการปลูกพืชดอกอย่างน้อย 4 ช่อง</p><p>ขั้นตอนการเล่น</p><p>เกริ่นนำเกี่ยวกับหลังคาเขียวและความสำคัญของพื้นที่สีเขียวในเมือง (5 นาที)</p><p>แนะนำเกม อุปกรณ์ และวิธีการเล่นเกม (5-8 นาที) แล้วให้ผู้เล่นทำแบบทดสอบก่อนเล่นเกม (2 นาที)</p><p>รอบที่ 1: ผู้เล่นจับสลากเลือกตำแหน่งอาคาร (A-H) ที่ตนเป็นเจ้าของ จากนั้นออกแบบและสร้างหลังคาเขียวโดยเลือกชิ้นส่วนภาพองค์ประกอบมาวางบนกระดานให้ครบทั้ง 25 ช่อง ภายใต้ต้นทุนที่ได้รับ (10-20 นาที) แล้วบันทึกข้อมูลหลังคาเขียวของตนเองลงในแบบบันทึก</p><p>ช่วงบิงโก: ผู้นำเกมสุ่มตัวเลข 1-24 และอ่านการ์ดเงื่อนไขบริการของระบบนิเวศ ผู้เล่นที่หลังคาเขียวของตนมีคุณสมบัติตรงตามเงื่อนไขนั้นจะกาเครื่องหมายในช่องหมายเลขดังกล่าว หากกาได้ครบ 5 ช่องติดกันในแนวตั้ง แนวนอน หรือแนวทแยง จะได้คะแนนพิเศษจากการทำบิงโก</p><p>รอบที่ 1 จบลงเมื่อมีผู้เล่นทำบิงโกได้ครบ 3 แนวในกระดานเดียว จากนั้นผู้เล่นแต่ละคนรวมคะแนนจาก 2 ส่วน คือ คะแนนบริการของระบบนิเวศที่ปรากฏบนชิ้นส่วนที่เลือกใช้ และคะแนนพิเศษจากการทำบิงโก ผู้ที่ทำคะแนนได้สูงสุดเป็นผู้ชนะของรอบนี้</p><p>พูดคุยแลกเปลี่ยนความเห็นเกี่ยวกับแนวคิดการออกแบบและเงื่อนไขบริการของระบบนิเวศที่ได้เรียนรู้จากรอบที่ 1</p><p>รอบที่ 2: ผู้เล่นออกแบบและสร้างหลังคาเขียวใหม่โดยใช้ความรู้เรื่องบริการของระบบนิเวศที่ได้รับจากรอบที่ 1 เมื่อเสร็จแล้วให้ประเมินบริการของระบบนิเวศบนหลังคาเขียวจำลองของตนเองด้วยแบบประเมินทั้ง 4 ด้าน ผู้ที่ได้คะแนนสูงในแต่ละด้านและคะแนนรวมทั้ง 4 ด้านจะได้คะแนนพิเศษ</p><p>ผู้ชนะของเกมคือผู้เล่นที่ทำคะแนนรวมในรอบที่ 2 ได้สูงสุด และมีรางวัลพิเศษสำหรับผู้ที่ทำคะแนนเพิ่มขึ้นจากรอบที่ 1 ได้มากที่สุด</p><p>พูดคุยแลกเปลี่ยนความเห็น จากนั้นให้ผู้เล่นทำแบบทดสอบหลังเล่นเกมและแบบประเมินความพึงพอใจ</p><p>ผู้นำเกมดำเนินการสรุปผลการใช้งาน (debriefing)</p>", "learning": "", "debrief": "<p>ผู้นำเกมเปิดโอกาสให้ผู้เล่นเดินดูหลังคาเขียวจำลองของผู้เล่นคนอื่น เพื่อเปรียบเทียบความแตกต่างของแนวคิดการออกแบบ การเลือกองค์ประกอบ และการจัดสรรต้นทุน จากนั้นนำผลการประเมินบริการของระบบนิเวศทั้ง 4 ด้าน และข้อมูลที่ผู้เล่นบันทึกไว้มาอภิปรายร่วมกัน โดยชี้ให้เห็นว่าองค์ประกอบแต่ละอย่างให้บริการของระบบนิเวศด้านใด เช่น ไม้ยืนต้นช่วยสะสมคาร์บอนและให้ร่มเงาแก่อาคาร พื้นที่ที่น้ำซึมผ่านได้ช่วยลดและชะลอน้ำไหลนอง พืชผักและการเลี้ยงผึ้งเป็นแหล่งอาหารและรายได้ แหล่งน้ำและที่ให้อาหารนกช่วยเพิ่มศักยภาพในการเป็นแหล่งที่อยู่อาศัยของสิ่งมีชีวิต และพื้นที่พักผ่อนกับศูนย์การเรียนรู้เป็นบริการด้านวัฒนธรรมและนันทนาการ พร้อมอภิปรายถึงการได้-เสียระหว่างการลงทุนกับบริการของระบบนิเวศที่ได้รับ และผลของที่ตั้งอาคารต่อการทำหน้าที่เป็นพื้นที่พักพิงต่อเนื่อง (stepping stone) ให้สิ่งมีชีวิตเคลื่อนย้ายระหว่างพื้นที่สีเขียว ต่อด้วยการเปรียบเทียบคะแนนของผู้เล่นระหว่างรอบที่ 1 และรอบที่ 2 เพื่อสะท้อนการเรียนรู้ที่เกิดขึ้น สุดท้ายผู้นำเกมจัดวงพูดคุยและถาม-ตอบเพื่อเชื่อมโยงสิ่งที่เรียนรู้จากเกมไปสู่สถานการณ์จริง โดยให้ผู้เล่นร่วมเสนอแนวทางการเพิ่มพื้นที่สีเขียวและการสร้างหลังคาเขียวในอาคารหรือที่พักอาศัยของตนเอง รวมถึงแนวทางการประชาสัมพันธ์เทคโนโลยีหลังคาเขียวในเมืองต่อไป</p>", "gallery": ""}, "gallery": [{"src": "assets/10-image159.png", "section": "materials"}, {"src": "assets/10-image160.png", "section": "materials"}, {"src": "assets/10-image161.png", "section": "materials"}, {"src": "assets/10-image162.png", "section": "materials"}, {"src": "assets/10-image163.png", "section": "materials"}, {"src": "assets/10-image164.png", "section": "materials"}, {"src": "assets/10-image165.png", "section": "materials"}, {"src": "assets/10-image166.png", "section": "materials"}, {"src": "assets/10-image167.png", "section": "materials"}, {"src": "assets/10-image168.png", "section": "materials"}, {"src": "assets/10-image169.png", "section": "materials"}, {"src": "assets/10-image170.png", "section": "materials"}, {"src": "assets/10-image171.png", "section": "materials"}, {"src": "assets/10-image172.png", "section": "materials"}, {"src": "assets/10-image173.png", "section": "materials"}, {"src": "assets/10-image174.png", "section": "materials"}, {"src": "assets/10-image175.png", "section": "materials"}, {"src": "assets/10-image176.png", "section": "materials"}, {"src": "assets/10-image177.png", "section": "materials"}, {"src": "assets/10-image178.png", "section": "materials"}, {"src": "assets/10-image179.png", "section": "materials"}, {"src": "assets/10-image180.jpeg", "section": "materials"}, {"src": "assets/10-image181.jpeg", "section": "materials"}, {"src": "assets/10-image182.jpeg", "section": "materials"}, {"src": "assets/10-image183.jpeg", "section": "materials"}, {"src": "assets/10-image184.jpeg", "section": "materials"}, {"src": "assets/10-image185.jpeg", "section": "materials"}, {"src": "assets/10-image186.jpeg", "section": "materials"}, {"src": "assets/10-image187.jpeg", "section": "materials"}, {"src": "assets/10-image188.jpeg", "section": "materials"}, {"src": "assets/10-image189.jpeg", "section": "materials"}, {"src": "assets/10-image190.jpeg", "section": "materials"}, {"src": "assets/10-image191.jpeg", "section": "materials"}, {"src": "assets/10-image192.jpeg", "section": "materials"}, {"src": "assets/10-image193.jpeg", "section": "materials"}, {"src": "assets/10-image194.jpeg", "section": "materials"}, {"src": "assets/10-image195.jpeg", "section": "materials"}, {"src": "assets/10-image196.jpeg", "section": "materials"}, {"src": "assets/10-image197.jpeg", "section": "materials"}, {"src": "assets/10-image198.jpeg", "section": "materials"}, {"src": "assets/10-image199.jpeg", "section": "materials"}, {"src": "assets/10-image200.jpeg", "section": "materials"}, {"src": "assets/10-image201.jpeg", "section": "materials"}, {"src": "assets/10-image202.jpeg", "section": "materials"}, {"src": "assets/10-image203.jpeg", "section": "materials"}, {"src": "assets/10-image204.jpeg", "section": "materials"}], "images": ["assets/10-image171.png", "assets/10-image185.jpeg", "assets/10-image161.png", "assets/10-image196.jpeg", "assets/10-image172.png", "assets/10-image186.jpeg", "assets/10-image162.png", "assets/10-image197.jpeg", "assets/10-image173.png", "assets/10-image187.jpeg", "assets/10-image163.png", "assets/10-image198.jpeg", "assets/10-image174.png", "assets/10-image188.jpeg", "assets/10-image164.png", "assets/10-image199.jpeg", "assets/10-image159.png", "assets/10-image175.png", "assets/10-image189.jpeg", "assets/10-image170.png", "assets/10-image184.jpeg", "assets/10-image200.jpeg", "assets/10-image165.png", "assets/10-image160.png", "assets/10-image190.jpeg", "assets/10-image195.jpeg", "assets/10-image176.png", "assets/10-image180.jpeg", "assets/10-image201.jpeg", "assets/10-image166.png", "assets/10-image191.jpeg", "assets/10-image177.png", "assets/10-image181.jpeg", "assets/10-image202.jpeg", "assets/10-image167.png", "assets/10-image192.jpeg", "assets/10-image178.png", "assets/10-image182.jpeg", "assets/10-image203.jpeg", "assets/10-image168.png", "assets/10-image193.jpeg", "assets/10-image179.png", "assets/10-image183.jpeg", "assets/10-image204.jpeg", "assets/10-image169.png", "assets/10-image194.jpeg"]}, {"id": "11", "title": "NEST", "category": "urban", "cover": "assets/cover-11.webp", "players": "12–14 players", "time": "90–150 minutes", "intro": "See the city through a bird’s eyes and make room for the next generation.", "research": "Ecological factors on bird nest site selection and integrative model for bird conservation in urban green space. Master’s thesis in Zoology, Faculty of Science, Chulalongkorn University, academic year 2025 (2568 BE), by เอื้อการย์ ทองโชติ.", "overview": "NEST (Nesting Ecology and the Selection of Trees) uses Companion Modelling to explore urban bird conservation. A campus survey from April 2024 to March 2025 recorded 182 nests in four nest categories on 124 trees of twenty species. Players take gardener, bird and birdwatcher roles to negotiate tree management and nesting needs. The source describes three versions used with young people, university students and green-space stakeholders.", "materials": ["A 54 × 54 cm, 43-cell board: twelve rain-tree, nine pradu, six pink trumpet-tree, four copperpod, five building and seven empty cells.", "Tree models with a trunk, two main branches and two small branches; bird and egg pieces for five bird species.", "Six situation cards and six building-activity cards; role, goal and placement-condition sheets.", "Gardener and birdwatcher records, scoring criteria, a ten-question pre/post test, an eleven-item model assessment, clay, bottle caps and fruit picks."], "play": ["Assign 12–14 participants to gardeners/facilities staff, five bird species and birdwatchers, with 1–2 people per role. Provide one facilitator per seven players and allow 90–150 minutes.", "Complete the pretest and explain role goals and placement conditions. Play six rounds, each representing two months.", "Draw a situation card and place activity cards on buildings. Gardeners can take up to ten pruning/planting actions, with pruning restricted to trees around active buildings.", "Birds place themselves and eggs according to species-specific rounds, tree/branch conditions and distance from buildings. Near-building nests earn one egg and farther nests earn two under the game rules.", "Birdwatchers count eggs and occupied trees and score the site. A total below five reduces the gardener’s next-round actions by one. Before round four, add small branches to trees that retain main branches.", "After six rounds, check each role’s goals. Gardeners aim to prune at least sixty branches and plant at least as many replacement trees as the first-round tree count; birds have species-specific egg goals. Debrief and complete the posttest and assessment."], "debrief": "Let each role explain successes and obstacles. Discuss tree species, branches, canopy, building distance, nest types, pruning and disturbance. Explore negotiation and possible local actions such as protecting occupied branches, nesting boxes, diverse green spaces and quieter conservation areas.", "file": "documents/11_NEST.docx", "titleTh": "เกม NEST (Nesting Ecology and the Selection of Trees)", "introTh": "มองเมืองผ่านสายตาของนก และร่วมดูแลพื้นที่สำหรับการสร้างรัง", "researchTh": "ปัจจัยทางนิเวศต่อการเลือกพื้นที่สร้างรังของนกและแบบจำลองเชิงบูรณาการเพื่อการอนุรักษ์นกในพื้นที่สีเขียวเขตเมือง (Ecological factors on bird nest site selection and integrative model for bird conservation in urban green space)", "sourceTh": "งานวิจัย (วิทยานิพนธ์ระดับปริญญาโท สาขาวิชาสัตววิทยา คณะวิทยาศาสตร์ จุฬาลงกรณ์มหาวิทยาลัย ปีการศึกษา 2568 โดย นางสาวเอื้อการย์ ทองโชติ)", "tags": [{"th": "นิเวศวิทยาการสร้างรัง", "en": "Nesting ecology"}, {"th": "พื้นที่สีเขียวในเมือง", "en": "Urban green space"}], "sectionsTh": {"overview": "<p>พื้นที่สีเขียวเขตเมืองเป็นทั้งแหล่งอาศัยและแหล่งสร้างรังที่สำคัญของนกในเมือง แต่ข้อมูลเกี่ยวกับปัจจัยที่ส่งผลต่อการเลือกพื้นที่สร้างรังของนกยังมีอยู่อย่างจำกัด ทำให้การจัดการไม้ยืนต้นและการอนุรักษ์นกทำได้ยาก จากการสำรวจในพื้นที่สีเขียวของจุฬาลงกรณ์มหาวิทยาลัย ระหว่างเดือนเมษายน 2567 – มีนาคม 2568 พบรังนกรวม 182 รัง จาก 4 ประเภท คือ platform, cavity, globular และ cavity adopter บนไม้ยืนต้น 124 ต้น 20 ชนิด โดยพบบนต้นจามจุรีมากที่สุด และไม่พบรังนกบนไม้ยืนต้นที่มีการตัดแต่งกิ่ง เกม NEST จึงพัฒนาขึ้นเป็นเกมกระดานสวมบทบาทสมมติ (role-playing board game) ตามแนวคิดแบบจำลองเพื่อนคู่คิด (Companion Modelling) ให้ผู้เล่นรับบทเป็นคนสวนหรือเจ้าหน้าที่ฝ่ายกายภาพ นก 5 ชนิด (อีกา นกเค้าจุด นกตีทอง นกเอี้ยงด่าง และนกยางเขียว) และคนดูนก เพื่อแลกเปลี่ยนเรียนรู้เรื่องปัจจัยการเลือกพื้นที่สร้างรังของนก ผลของการตัดแต่งกิ่งและการรบกวนจากกิจกรรมของมนุษย์ และร่วมกันตัดสินใจวางแผนจัดการพื้นที่สีเขียวเพื่อการอนุรักษ์นกในเมือง โดยเกมนี้มีการพัฒนาทั้งหมด 3 เวอร์ชัน และนำไปใช้กับเยาวชน นิสิต และผู้มีส่วนเกี่ยวข้องกับการจัดการพื้นที่สีเขียว</p>", "materials": "<p>กระดานจำลองพื้นที่สีเขียวของจุฬาลงกรณ์มหาวิทยาลัย ขนาด 54 x 54 เซนติเมตร จำนวน 43 ช่อง (1 ช่อง = ต้นไม้ 1 ต้น) ประกอบด้วยช่องจามจุรี 12 ช่อง ประดู่ 9 ช่อง ชมพูพันธุ์ทิพย์ 6 ช่อง นนทรี 4 ช่อง ช่องอาคาร 5 ช่อง และพื้นที่ว่าง 7 ช่อง</p><p>ต้นไม้จำลอง 4 ชนิด (จามจุรี 12 ต้น ประดู่ 9 ต้น ชมพูพันธุ์ทิพย์ 6 ต้น นนทรี 4 ต้น) แต่ละต้นมีลำต้น 1 ต้น กิ่งหลัก 2 กิ่ง และกิ่งย่อย 2 กิ่ง</p><p>ตัวนกและไข่นก 5 ชนิด ได้แก่ อีกา 24 ตัว นกตีทอง 14 ตัว นกเอี้ยงด่าง 14 ตัว นกยางเขียว 8 ตัว และนกเค้าจุด 4 ตัว</p><p>การ์ดเหตุการณ์ 2 ประเภท คือ (1) การ์ดสถานการณ์ 6 สถานการณ์ (สถานการณ์ปกติ งบประมาณเพิ่มขึ้น ฝนตกหนักทำให้กิ่งไม้หัก ฝนตกหนักทำให้ต้นไม้ล้ม ฝุ่น PM 2.5 และการเปลี่ยนแปลงสภาพภูมิอากาศ) และ (2) การ์ดกิจกรรมของอาคาร 6 กิจกรรม (ก่อสร้าง ซ้อมหนีไฟ การเรียน-การสอน รับน้อง รับปริญญา และ Open house)</p><p>ใบแสดงหน้าที่ เป้าหมาย และเงื่อนไขการวางของผู้เล่นแต่ละบทบาท (คนสวน นก 5 ชนิด และคนดูนก)</p><p>ใบบันทึกข้อมูลของผู้เล่นคนสวน และใบบันทึกจำนวนไข่นก/จำนวนต้นไม้ที่พบรังของผู้เล่นคนดูนก พร้อมใบเกณฑ์ให้คะแนน</p><p>แบบทดสอบก่อนและหลังการใช้แบบจำลอง จำนวน 10 ข้อ (ปรนัย 6 ข้อ อัตนัย 4 ข้อ) และแบบประเมินคุณภาพแบบจำลอง 11 ข้อ</p><p>วัสดุประกอบอุปกรณ์ต้นทุนต่ำ เช่น ดินน้ำมัน ฝาขวดน้ำ และไม้จิ้มผลไม้</p>", "play": "<p>ผู้เล่น 12–14 คนต่อกลุ่ม แบ่งเป็นคนสวน/เจ้าหน้าที่ฝ่ายกายภาพ 1–2 คน ผู้เล่นบทบาทนก 5 ชนิด ชนิดละ 1–2 คน และคนดูนก 1–2 คน โดยมีผู้นำเกม 1 คนต่อผู้เล่น 7 คน ใช้เวลาประมาณ 1 ชั่วโมง 30 นาที ถึง 2 ชั่วโมง 30 นาที</p><p>ผู้นำเกมให้ผู้เล่นทำแบบทดสอบก่อนเล่น (pretest) แล้วอธิบายกติกา บทบาท เป้าหมาย และเงื่อนไขของแต่ละบทบาท</p><p>เกม 1 ครั้ง (game session) เล่นทั้งหมด 6 รอบ โดย 1 รอบเทียบเท่า 2 เดือนในความเป็นจริง</p><p>เริ่มรอบการเล่น: ผู้นำเกมสุ่มการ์ดสถานการณ์ และวางการ์ดกิจกรรมบนช่องอาคาร เพื่อบอกตำแหน่งที่มีกิจกรรมในรอบนั้น</p><p>ผู้เล่นคนสวนเลือกตัดแต่งกิ่งและปลูกต้นไม้ ได้ไม่เกินรอบละ 10 กิจกรรม และตัดแต่งกิ่งได้เฉพาะต้นไม้รอบอาคารที่มีกิจกรรมในรอบนั้น</p><p>ผู้เล่นบทบาทนกเลือกต้นไม้และวางนกพร้อมไข่ตามเงื่อนไข 3 ข้อของชนิดตนเอง คือ (1) รอบที่ลงได้และจำนวนตัวที่วางได้ (2) ชนิดต้นไม้และตำแหน่งกิ่ง (กิ่งหลัก/กิ่งย่อย) (3) ระยะห่างจากอาคาร ซึ่งกำหนดจำนวนไข่ที่ได้ (ใกล้อาคารได้ 1 ฟอง ห่างอาคารได้ 2 ฟอง)</p><p>ผู้เล่นคนดูนกสำรวจและบันทึกจำนวนไข่ของนกแต่ละชนิดและจำนวนต้นไม้ที่พบรัง แล้วให้คะแนนพื้นที่สีเขียวในรอบนั้น หากคะแนนรวมน้อยกว่า 5 คะแนน ผู้เล่นคนสวนจะถูกลดจำนวนกิจกรรมลง 1 กิจกรรมในรอบถัดไป</p><p>ก่อนเริ่มรอบที่ 4 เพิ่มกิ่งย่อยบนต้นไม้ที่ยังมีกิ่งหลักเหลืออยู่ เปรียบเสมือนการเติบโตของไม้ยืนต้นในระยะ 1 ปี</p><p>เล่นซ้ำตามขั้นตอนเดิมจนครบ 6 รอบ ระหว่างเล่นเปิดโอกาสให้ผู้เล่นทุกบทบาทปรึกษาและแลกเปลี่ยนความคิดเห็นกัน</p><p>เมื่อจบเกม ตรวจสอบว่าแต่ละบทบาทบรรลุเป้าหมายหรือไม่ (คนสวนต้องตัดแต่งกิ่งอย่างน้อย 60 กิ่ง และปลูกต้นไม้ทดแทนไม่น้อยกว่าจำนวนต้นไม้ในรอบที่ 1; นกแต่ละชนิดต้องวางไข่ให้ได้ตามเป้าหมายของตน)</p><p>ผู้นำเกมสรุปผลการใช้งาน (debriefing) และให้ผู้เล่นทำแบบทดสอบหลังเล่น (posttest) พร้อมแบบประเมินคุณภาพแบบจำลอง</p>", "learning": "", "debrief": "<p>ผู้นำเกมเปิดโอกาสให้ผู้เล่นแต่ละบทบาทเล่าว่าตนเองบรรลุเป้าหมายหรือไม่ และอะไรเป็นอุปสรรค จากนั้นชวนคุยเชื่อมโยงกับสถานการณ์จริง ในประเด็นต่อไปนี้ (1) ปัจจัยที่นกใช้ในการเลือกพื้นที่สร้างรัง ทั้งชนิดไม้ยืนต้น ตำแหน่งกิ่ง ขนาดเรือนยอด และระยะห่างจากอาคาร (2) ประเภทรังนกทั้ง 4 ประเภท (platform, cavity, cavity adopter และ globular) และความหลากหลายของชนิดนกที่พบในพื้นที่สีเขียวเขตเมือง (3) ผลของการตัดแต่งกิ่งและกิจกรรมของมนุษย์ต่อความสำเร็จในการสร้างรังและวางไข่ของนก (4) การแลกเปลี่ยนและต่อรองระหว่างบทบาทต่าง ๆ ที่เกิดขึ้นระหว่างเล่น ซึ่งสะท้อนการทำงานร่วมกันของผู้มีส่วนเกี่ยวข้องในความเป็นจริง</p><p>จากนั้นให้ผู้เล่นร่วมกันเสนอแนวทางการจัดการพื้นที่สีเขียวเพื่อการอนุรักษ์นก เช่น ลดความถี่ของการตัดแต่งกิ่งในช่วงฤดูผสมพันธุ์ (มกราคม–มิถุนายน และธันวาคม) และเลือกตัดแต่งกิ่งในช่วงเดือนสิงหาคม–พฤศจิกายน การหลีกเลี่ยงการตัดกิ่งที่พบรังนก การเพิ่มพื้นที่สีเขียวและปรับภูมิทัศน์ให้หลากหลาย การจัดทำกล่องรังนก (nest box) การกันพื้นที่บางส่วนไว้เพื่อการอนุรักษ์ และการลดกิจกรรมที่ส่งเสียงดังรบกวนนก ปิดท้ายด้วยการให้ผู้เล่นทำแบบทดสอบหลังเล่นและแบบประเมินคุณภาพแบบจำลอง</p>", "gallery": ""}, "gallery": [{"src": "assets/11-image1.png", "section": "materials"}, {"src": "assets/11-image2.png", "section": "materials"}, {"src": "assets/11-image3.png", "section": "materials"}, {"src": "assets/11-image4.png", "section": "materials"}, {"src": "assets/11-image5.png", "section": "materials"}, {"src": "assets/11-image6.png", "section": "materials"}, {"src": "assets/11-image7.png", "section": "materials"}, {"src": "assets/11-image8.png", "section": "materials"}, {"src": "assets/11-image9.png", "section": "materials"}, {"src": "assets/11-image10.png", "section": "materials"}, {"src": "assets/11-image3.png", "section": "materials"}, {"src": "assets/11-image4.png", "section": "materials"}, {"src": "assets/11-image5.png", "section": "materials"}, {"src": "assets/11-image6.png", "section": "materials"}, {"src": "assets/11-image7.png", "section": "materials"}, {"src": "assets/11-image11.png", "section": "materials"}, {"src": "assets/11-image12.png", "section": "materials"}, {"src": "assets/11-image13.png", "section": "materials"}, {"src": "assets/11-image14.png", "section": "materials"}, {"src": "assets/11-image15.png", "section": "gallery"}, {"src": "assets/11-image16.png", "section": "gallery"}, {"src": "assets/11-image17.png", "section": "gallery"}], "images": ["assets/11-image11.png", "assets/11-image17.png", "assets/11-image16.png", "assets/11-image15.png", "assets/11-image14.png", "assets/11-image1.png", "assets/11-image2.png", "assets/11-image3.png", "assets/11-image4.png", "assets/11-image5.png", "assets/11-image6.png", "assets/11-image7.png", "assets/11-image8.png", "assets/11-image9.png", "assets/11-image13.png", "assets/11-image12.png", "assets/11-image10.png"]}];
